-- ============================================================
-- Son18c (3/4): Günə-özəl push bildirişlərinin ru+tr tərcüməsi
-- pregnancy_day_notifications (294) + mommy_day_notifications (4370) — Azure/Fable
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('b97073a4-f745-41b1-953a-0e776ded1591'::uuid, 'Выключите свет — и придёт сон 🌙', 'Чтобы малыш быстрее заснул, за 1 час до сна выключите все дополнительные источники света и уберите планшеты. Мелатонин активнее вырабатывается в тёмной обстановке без электронных устройств.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'Театр перед зеркалом 🎭', 'С самого утра малыш стоит перед зеркалом и изображает плач, смех и удивление. Он изучает, как выражать свои эмоции и как при этом меняется его лицо. Наблюдайте издалека с улыбкой за этой гениальной актёрской игрой.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'Волшебные папины руки 🫂', 'У вас уже отваливаются руки после целого дня с малышом, а он снова просится на ручки. Позовите папу. Полёты на папиных руках удовлетворят потребность ребёнка во внимании, а вашим рукам подарят столь необходимый отдых.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'Не мусор, а искусство 🎨', 'Посреди комнаты малыш создал большое произведение искусства из обрывков бумаги и нарезанных ниток и не разрешает вам его выбросить. Отложите стремление к идеальной чистоте. Отнеситесь с уважением к созданному им хаосу — уборка может подождать до завтра.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', 'Упрямое «Я сам!» 🛑', 'Малыш хочет сам завязать шнурки, а вы уже на 10 минут опаздываете с выходом из дома. Не торопите его. Для его развития непошатнувшаяся уверенность в себе важнее нарушенного расписания. Позвольте ему попробовать.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'Истории шёпотом 🌙', 'Сегодня вы так много говорили, что голос и дыхание уже устали. Выключите свет, лягте рядом с малышом и шёпотом расскажите ему о том, что произошло за день. Шёпот помогает сосредоточить его внимание и словно гипнотизирует, настраивая мозг на глубокий сон.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'Мифы об идеальной маме 🛑', 'Дети из социальных сетей уже называют цвета и считают по-английски, а ваш ребёнок не хочет? Немедленно прекратите сравнивать! У каждого ребёнка свой уникальный темп развития. В своём темпе он идеален.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'Дневной сон закончился? ⏱️', 'Вечером укладывание занимает больше 1 часа? Проверьте режим сна. Возможно, в бурном возрасте 3 лет уже пора полностью отказаться от дневного сна и перенести вечернее укладывание на более раннее время.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'Бесконечные вопросы «Почему?» 🌪️', '«Почему рыбы не ходят?», «Куда ушло солнце?» С самого утра мозг малыша ищет ответы на философские вопросы со скоростью 100 вопросов в час. Даже если вы устали, отвечайте кратко и понятно. Тайны Вселенной он познаёт через ваш голос.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'Путешественник по кроватям 🛏️', 'Он начинает ночь в своей кровати, а утром просыпается уже в вашей, растянувшись поперёк и положив ноги вам на лицо. Отнеситесь к этому захвату территории с улыбкой. Ваш родной тёплый запах — для него самая надёжная зона безопасности.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'Магия коробки 📦', 'Он отбросил дорогую шумную игрушку, которую вы ему купили, и уже целый час играет с её коробкой? Детский мозг любит не готовые сценарии, а пустые предметы, которые можно наполнить фантазией. Картонная коробка для него — космический корабль, не мешайте.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'Летний бунт зимой ❄️', 'На улице дует ветер, а он упорно хочет надеть летние шорты. Объяснять — только терять время. Откройте инструмент погоды и одежды и покажите ему на экране значок тепло одетого ребёнка. Уловка «Смотри, даже телефон говорит, что сегодня нужно надеть брюки» отлично работает.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'Воображаемый кусочек 🍏', 'В руках у него ничего нет, но он подходит к вам и протягивает воображаемое яблоко со словами: «На, откуси». Ролевые игры — важнейшее пространство, в котором формируется личность. С аппетитом откусите пустоту со звонким «хрум» и подтвердите, что это самое вкусное яблоко в мире.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'Монстр у окна 👻', 'Тень от дерева, качающегося на улице, падает в комнату, и малыш в страхе прячется за вами. Не включайте свет. Возьмите фонарик, направьте его на тень и скажите: «Смотри, это всего лишь танец дерева», превратив страх в волшебство.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', 'Марафон «Посмотри на меня!» 👀', 'Едва проснувшись утром, он уже ровно 40 раз сказал: «Мама, посмотри на меня»? Он прыгает, крутится и ждёт вашего одобрения. Оторвитесь от телефона, всего 3 минуты смотрите только на него и скажите: «Ты великолепен». Этого безраздельного внимания ему хватит, чтобы насытиться им.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'Право мамы на лень 🍕', 'Сегодня вам хочется на всё кричать? Дома полный беспорядок? Забудьте об уборке и не заходите на кухню. Закажите пиццу или что-нибудь простое. Разрушьте иллюзию идеальной мамы: ваше психологическое здоровье гораздо ценнее домашней еды.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'Семейная кома 📺', 'Ребёнок уснул! Наконец-то вы с партнёром устроились на диване, чтобы посмотреть фильм, но через 10 минут оба заснули. Такова ваша реальность. Эта усталая, но милая картина, где вы спите, прижавшись друг к другу, и есть сама любовь.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'В пищевой избирательности нет логики. 🥦', 'Сегодня он отказывается даже пробовать суп, который ещё вчера ел с удовольствием? Перейдите к полезным рецептам и узнайте, как спрятать овощное пюре в цветных соусах для макарон. Освойте искусство маскировки.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'Подводное царство 🛀', 'Купание в ванне — уже не гигиеническая процедура, а миссия на подводной лодке. Пусть вода разбрызгивается во все стороны. Её притягательная сила смоет упрямство и негативную энергию, накопившиеся за день, и унесёт их в канализацию.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'Гениальный изобретатель 👟', 'Он прикладывает ботинок к уху и с серьёзным видом говорит: «Алло», продолжая что-то рассказывать. Он придумывает предметам новые функции! Не упустите этот абсурдный и гениальный момент. Запечатлейте забавного изобретателя с помощью детской фотосессии и сохраните снимок на самом видном месте в архиве.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'Терапия цифровой тишиной 🤫', 'Наконец-то в комнате воцарилась абсолютная тишина. Не спешите загружать посудомоечную машину. Включите инструмент измерения шума и, наблюдая, как цифры на экране опускаются до 0 децибел, почувствуйте, как очищается ваш уставший мозг.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'Художник, умножающий мусор ✂️', 'Он разрывает попавшийся ему чистый лист бумаги на тысячу мелких кусочков и разбрасывает их по комнате? Так развивается мелкая моторика! Не сердитесь и не спешите за веником. Соберите обрывки в коробку и поиграйте в снегопад.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'Соперник в зеркале 🪞', 'Стоя перед зеркалом, он хмурится, сердится и корчит странные рожицы. Так он проверяет, как эмоции выглядят на его лице. Не издавая ни звука, с интересом наблюдайте со стороны за репетицией этого маленького театрального актёра.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'Тоска по уединению 🚪', 'Вы устали от ребёнка, который весь день карабкается на вас и не отлипает ни на минуту. Вы зашли в туалет, закрыли дверь и остались одни на 5 минут. Сразу откройте Дневник настроения, выплесните на экран накопившееся чувство внутренней тесноты и ощутите облегчение.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'Режиссёр сказки 🪄', 'Сегодня вечером ваш голос устал. Включите Умные сказки. Скажите ребёнку: «Сегодня главным героем будешь ты, а на заднем плане будет идти дождь», создайте особую, успокаивающую и персонализированную звуковую атмосферу и мягко погрузите его в сон.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'Первая бессмысленная шутка 🤡', '«Собака села в машину и взорвалась!» — говорит малыш и заливается смехом. Смысла в этом нет, но он только открывает для себя чувство юмора. Не ищите логики — лучше присоединитесь к его искреннему и весёлому смеху.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'Правила горки 🛝', 'В парке малыш стоит на вершине горки и не разрешает другим детям кататься. Не стаскивайте его вниз резко из-за чувства неловкости. Не обращая внимания на окружающих, мягко напомните ему, что нужно соблюдать очередь. Так он отстаивает своё чувство собственности.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'Он уже не малыш! 🌟', 'Перед вами полноценная личность со своими решениями, необычными вопросами и огромным сердцем. Поблагодарите себя за то, что помогаете ему расти, направляя его и не подавляя сильный характер. Вы прекрасно справляетесь.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'Победа без шампанского 🥂', 'После трудного дня налейте в стаканы обычный горячий чай. Сядьте с партнёром друг напротив друга на диване, скажите: «Сегодня мы пережили и этот хаос» — и чокнитесь стаканами. Вы одновременно и полководцы, и команда своего дома.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'Сила сообщества 💬', 'Мысль «Почему мой ребёнок такой упрямый?» не даёт вам покоя. Присоединитесь к Сообществу Anacan. Прочитав о таких же абсурдных кризисах в домах других мам, вы поймёте, что не одиноки и всё происходящее совершенно нормально.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'Ритм освещения 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин активнее вырабатывается в тёмной обстановке без гаджетов, облегчая засыпание.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'Завтрак динозавра 🦖', 'За завтраком малыш хочет есть как динозавр: не пользоваться руками, а тянуться ртом прямо к тарелке. Не устраивайте урок хороших манер! Позвольте ему 5 минут побыть динозавром — вскоре эта игра ему надоест, и он сам возьмёт ложку.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', 'Скорость «Я сам» 🐢', 'Вам нужно выходить из дома, но малыш непременно хочет сам надеть обувь, а с его черепашьей скоростью это занимает 15 минут. Если вмешаться, приступ плача продлится 30 минут. Не думайте о потраченном времени — сосредоточьтесь на его самостоятельности и терпеливо подождите.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'Исчезнувшие ключи 🔑', 'Не можете найти ключи от дома? Загляните в холодильник или шкаф для обуви. Пряча вещи, малыш проверяет постоянство существования объектов. Вместо того чтобы сердиться во время этих забавных поисков сокровищ, постарайтесь посмеяться.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'Гипноз шёпота 🤫', 'Малыш лежит в кровати, поднимает ноги вверх и не хочет засыпать. Вместо того чтобы кричать, внезапно понизьте голос и говорите с ним только шёпотом. Когда ребёнок сосредоточится, чтобы расслышать вас, его мозг автоматически успокоится и переключится в режим сна.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'Отдых для рук 🫂', 'У вас болит всё тело от того, что малыш весь день карабкается на вас и просится на руки. Вечером передайте эстафету папе. Пока он катает ребёнка на спине, как на лошадке, малыш получает необходимое внимание, а ваши руки — долгожданный отдых.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'Утренний концерт 🎤', 'Солнце ещё не успело полностью взойти, а малыш уже прыгает на кровати и громко поёт на непонятном вам языке. Да, вам хочется спать, но эта бурлящая в комнате энергия жизни поднимет и вас. Просто улыбнитесь, услышав его голос.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'Искусственный интеллект спешит на помощь 🤖', '«Мама, куда солнце уходит спать?» Этот вопрос застал вас врасплох? Не усложняйте объяснение. Задайте этот вопрос Anacan AI, указав возраст ребёнка, и получите замечательный ответ в виде истории, которую легко поймёт трёхлетний малыш.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'Тихие слёзы 💖', 'Весь день малыш сводил вас с ума. Но теперь он так невинно спит в своей кровати, что при одном взгляде на него вы растрогались, правда? В этом и заключается главный парадокс материнства. Слеза, скатившаяся по вашей щеке, — это благодарность за то, что он есть в вашей жизни.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'Операция «Секретное питание» 🥣', 'Ещё вчера малыш любил яйца, а сегодня категорически отказывается их есть. Не боритесь с его волей. Используйте хитрые рецепты полезных перекусов, в которых белковые продукты приобретают необычные, яркие и интересные формы, — и победа останется за вами.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'Крах логики 🛑', 'Малыш кричит, требуя налить воду в красный стакан, а когда вы это делаете, плачет: «Зачем ты налила сюда?» Здесь нет логики. Он просто устал и нуждается в эмоциональной разрядке. Спокойно подождите — буря утихнет сама.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'Гордитесь собой 🚀', 'Оглядываясь назад, вы видите, какой сильной личностью стал ваш ребёнок. Сегодня внимательно посмотрите на него и гордитесь собой за то, что вырастили такого прекрасного человека.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'Благодарность команде 🥂', 'Ещё один трудный и бурный день остался позади. Когда ребёнок уснёт, налейте себе чаю вместе с партнёром и скажите: «Сегодня ты мне очень помог, спасибо». Родительство становится прекраснее, когда вы не одни, а действуете как сплочённая команда.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'Проблески эмпатии 🧸', 'Когда игрушка падает, малыш гладит её и говорит: «Не плачь»? Значит, у него развивается эмпатия! Обязательно отметьте этот милый этап в Трекере развития.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'Одежда задом наперёд 👗', 'Малыш непременно хочет надеть футболку задом наперёд? Не спорьте. Пусть хотя бы один день походит так дома — не подавляйте его волю.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'Мы — одна команда! 💖', 'После трудного дня сядьте напротив партнёра и поговорите по душам. Взаимная поддержка действительно помогает разделить нагрузку пополам.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'Одеяльная инженерия 🛏️', 'Малыш уже почти уснул, но внезапно начинает плакать: край одеяла загнулся! Идеальная ровность одеяла до миллиметра имеет для него жизненно важное значение. Глубоко вдохните, расправьте одеяло так, словно его только что выгладили, и просто улыбнитесь этой забавной требовательности.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'Подозрительная тишина 🤫', 'В доме внезапно воцарилась глубокая тишина. Шумомер показывает 0 децибел. Если ребёнок притих, значит, где-то идёт серьёзная исследовательская работа. Входите в комнату, морально подготовившись увидеть рисунки на стенах или нарезанную бумагу.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'Не вступайте в спор. 💼', '«Я не буду есть эту кашу, потому что она жёлтая!» Логика настолько безупречно убедительна в своей абсурдности, что вы почти почувствуете себя виноватой. Не вступайте в спор. Уговорите маленького адвоката словами: «Ты прав, она жёлтая. А что, если добавить в неё красные ягоды?»'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'Папина водная битва 🛁', 'Сегодня вечерний ритуал купания полностью на папе. Пусть они разбрызгивают воду во все стороны, а вы наслаждайтесь полной тишиной за дверью.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'Бунт в гардеробе 🥽', 'Малыш хочет ходить по дому в плавательных очках и зимней шапке. Настаивает и не снимает их. Забудьте об общественных нормах. Чтобы не подавлять его творческое начало и свободу выбора, позвольте ему провести день в этом необычном и забавном наряде.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'Сюрприз в тележке 🛒', 'У кассы в тележке обнаружились 3 разные шоколадки и 1 кусок мыла странной формы, которые вы не выбирали. Быстрым движением верните эти товары на место. А чтобы ничего не забыть и не отклоняться от цели, постоянно сверяйтесь со Списком покупок.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'Слуховой аппарат отключён 🙉', 'Вы говорите: «Собери игрушки», «Иди помой руки», но реакции нет. Делать вид, что ничего не слышишь, — любимое хобби в 3 года. Вместо того чтобы кричать, подойдите к малышу и прошепчите ему что-нибудь очень тихо на ухо. Внезапная смена тона сразу привлечёт его внимание.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'Шантаж в ванной 🛀', 'Когда малыш заходил в ванну, он плакал, а теперь кричит, потому что не хочет выходить из воды. Магическая сила воды его околдовала. Предупредите об окончании купания за 3 минуты и установите таймер. Ритуал «таймер прозвенел — игра окончена» всегда помогает.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'Дизайнер блюд 🥦', 'Малыш сортирует еду в тарелке по цвету и форме, а всё зелёное отодвигает на край стола. Загляните в План питания. Узнайте, как превратить овощи в незаметное пюре и спрятать их в котлетах и соусах, чтобы победить в этой игре.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'Главный врач дома 🩺', 'Малыш берёт игрушечный стетоскоп, прикладывает его к вашей груди и, нахмурив брови, говорит: «Дышите». Вы — послушный пациент. Воспользуйтесь этой ролевой игрой: закройте глаза и просто полежите на полу, давая спине отдохнуть во время 3-минутного осмотра.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'Папины голосовые связки 📖', 'Сегодня ваш голос устал, а горло пересохло. Поручите папе прочитать вечернюю сказку. Он придумает смешную историю, совершенно не похожую на то, что изображено в книге, и рассмешит ребёнка до слёз. А вы наблюдайте за этой чудесной сценой со стороны, наслаждаясь горячим чаем.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', 'Период «Мама, смотри!» 👀', 'Он прыгает с дивана и каждый раз повторяет одно и то же движение ровно 50 раз, восклицая: «Мама, смотри на меня!» Оторвитесь от телефона. Он прыгает не ради самого движения, а ради искры одобрения в ваших глазах. Подарите ему 5 минут безраздельного внимания, чтобы он им насытился.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'Музыкальный гипноз 🎶', 'Начались беспричинные вечерние бури и приступы плача. Выключите телевизор, приглушите свет и включите в комнате очень тихую классическую музыку. Её глубокое звучание волшебным образом изменит атмосферу и принесёт в комнату умиротворение.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'Сценарист мультфильмов 📺', 'Он пересказывает просмотренный мультфильм с таким необычным сюжетом и так убедительно, что вы почти готовы поверить. У него формируется прекрасное воображение.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'Кнопка перезагрузки для мамы 🚪', 'Шум словно сверлит вам мозг, и хочется на всех кричать. Откройте дневник настроения. Свободно выпишите туда всё, что накопилось из-за эмоционального истощения. Эта короткая цифровая терапия поможет вам перезагрузиться.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'Танец с темнотой 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите все лишние источники света и экраны планшетов. Мелатонин (гормон сна) активнее вырабатывается в тёмной обстановке без гаджетов, помогая легче погрузиться в сон.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'Сокровище с улицы 🍁', 'Он радостно показывает вам найденную на земле грязную крышку от бутылки или камешек необычного цвета, словно обнаружил золото. Вместо слов «Выбрось, это грязное» скажите: «Какой необычный цвет! Давай помоем это дома», — и поддержите его страсть к открытиям.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'Час философии снова открыт 🤔', 'Почему дует ветер? Почему опадают листья? Глубокие философские вопросы с самого утра заставляют ваш мозг кипеть. Не усложняйте объяснения — рассказывайте о природе понятным ему языком сказок. Тон вашего голоса для него — самый надёжный способ познавать Вселенную.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'Концерт на кухне 🥄', 'Он достаёт кастрюли и деревянные ложки и устраивает концерт посреди кухни. Даже если у вас болит голова, помните: так развиваются его чувство ритма и творческие способности. Не спешите вмешиваться — позвольте этой неуёмной энергии несколько минут разливаться по комнате звуковыми волнами.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'Поддержка сообщества 💬', 'Мысль «Почему мой ребёнок такой упрямый?» изводит вас изнутри. Зайдите в сообщество Anacan. Прочитав о таких же абсурдных истериках в домах других мам, вы поймёте, что не одиноки и растите совершенно нормального, здорового ребёнка.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'Тепло его дыхания 💖', 'Весь день он сводил вас с ума и плакал по любому поводу. Но теперь он прижался к вашей груди в кровати, а комнату наполняет его ритмичное, тёплое дыхание. Именно в этом и заключается главная награда материнства. Прижмите его к себе и почувствуйте, как вся усталость улетучивается с каждым его вдохом.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'Плод командной работы 🥂', 'Ещё один трудный и бурный день позади. Когда ребёнок уснёт, налейте себе и партнёру чаю и поблагодарите друг друга словами: «Сегодня мы пережили и этот хаос. Мы отличная команда!» Родительство становится прекраснее, когда вы не одни и рядом есть поддержка.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'Обувь не на ту ногу 👟', 'Он надел обувь не на ту ногу, но ходит с таким гордым видом, словно покорил весь мир. Если вы вмешаетесь и попытаетесь всё исправить, волшебство исчезнет. Его уверенность в себе и самостоятельность важнее эстетики. Пусть этот маленький бунтарь гордо шагает вперёд.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'Диверсия на кухне 🧑‍🍳', 'Пока вы раскатываете тесто, он запускает руки в муку и превращает всё вокруг в белоснежный беспорядок. Да, кухня теперь вверх дном. Но сразу запечатлейте его серьёзное, деловитое выражение лица с помощью фотосессии малыша. Беспорядок можно убрать, а этот забавный кадр останется навсегда.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'Живое зеркало 🦜', 'Он ругает свою игрушку, в точности повторяя выражение вашего лица, когда вы сердитесь. Взгляните на себя со стороны! Он копирует всё, что видит. Эта забавная, но заставляющая задуматься сцена — прекрасное зеркало, которое поможет вам внимательнее относиться к своему поведению.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'Я в умной сказке 🪄', 'Вы уже выучили классические книги наизусть и устали их читать. Откройте умные сказки. Сделайте своего ребёнка главным героем, добавьте на фон успокаивающие звуки леса и создайте необычный сеанс перед сном, не требующий от вас никаких усилий.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'Свежий воздух ⛅', 'Проверьте погоду, подберите подходящую одежду и обязательно выведите его на прогулку. Поручите ему простую миссию — собирать сухие веточки и камешки. Так он выплеснет энергию, а вы выберетесь из четырёх стен и глубоко вдохнёте свежий воздух.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'Внезапный прилив любви 🥰', 'Он бросает игрушку, с которой играл, подбегает к вам, обнимает за шею и говорит: «Я тебя люблю». Вот оно — волшебство, которое в один миг стирает всю усталость и бессонные ночи. Крепко прижмите малыша к груди и вдохните его родной запах.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'Необычная папина сказка 📖', 'Сегодня вечером ваш голос устал. Поручите чтение сказки папе. Он придумает совершенно новую забавную историю, не имеющую ничего общего с картинками в книге, и рассмешит малыша до слёз. А вы с чашкой чая с удовольствием понаблюдайте за ними со стороны.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'Буря с тележкой в супермаркете 🛒', 'Малыш непременно хочет сам катить большую тележку, хотя она выше него. Чтобы не доводить его до слёз на людях, позвольте ему держаться за тележку, а сами незаметно направляйте её.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'Свобода шиворот-навыворот 👗', 'Малыш надел брюки задом наперёд и очень решительно заявляет: «Я сам оделся». Забудьте об эстетике. Его растущая уверенность в себе и чувство самостоятельности гораздо важнее того, правильно ли надета одежда. Гордитесь своим маленьким бунтарём.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'Кофе посреди хаоса ☕', 'Малыш разбросал все игрушки посреди комнаты и строит из них крепость. Как только вы всё соберёте, он снова устроит беспорядок. Поэтому прекратите эту борьбу, устройтесь в уголке комнаты, выпейте кофе, пока он горячий, и отдохните, наблюдая за хаосом со стороны.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'Тени в комнате 🐰', 'Малыш начал бояться темноты? Полностью погасите свет в комнате и с помощью маленького фонарика устройте на потолке игру света и театр теней с фигурками животных. Превратите пугающую темноту в развлечение и маленькое приключение, над которым вы вместе посмеётесь перед сном.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'Надежда на непрерывный сон 🤞', 'Малыш уснул, и дом погрузился в глубокую тишину. Больше всего вам хочется, чтобы этой ночью он не просыпался. Тихо включите нежный шелест леса в качестве фонового звука шумомера, чтобы помочь малышу оставаться в фазе глубокого сна.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'Лаборатория природы 🍂', 'Вам тесно в четырёх стенах, а малыш беспокоен. Проверьте погоду, подберите подходящую одежду и обязательно выйдите с ним на улицу. Устройте простую миссию по сбору сухих веточек и листьев: малыш выплеснет энергию, а вы вырветесь из дома и подышите свежим воздухом.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'Мама для игрушек 🧸', 'Из комнаты доносится голос. Вы прислушиваетесь и понимаете, что малыш ругает своего плюшевого мишку точно вашим тоном и вашими фразами! Он — ваша самая точная копия. Это прекрасная возможность посмотреть на своё поведение со стороны.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'Завтрак, которым не делятся 🍳', 'Малыш ни за что не хочет делиться с вами едой из своей тарелки, но настойчиво требует яйцо из вашей. Дети всегда больше доверяют выбору родителей. Не спорьте — с любовью отдайте свой кусочек этому маленькому эгоисту.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'Катастрофа без списка 🛒', 'Вы понадеялись на свою память, вернулись домой и обнаружили, что забыли купить самое важное для малыша — молоко. Ваш мозг и так перегружен. Чтобы избежать стресса, заведите привычку записывать всё в «Список покупок» в приложении, как только возникает необходимость что-то купить.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'Океан в ванне 🌊', 'Купание в ванне — уже не просто мытьё, а игра с настоящими волнами. Пусть вода брызжет во все стороны. Её волшебное притяжение смоет всю накопившуюся за день упрямую негативную энергию, унесёт её в слив и поможет малышу крепче спать.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'Вы идеальны 🛑', 'Вы упрекаете себя, глядя в социальных сетях на мам, которые каждый день создают с детьми шедевры, а их дома сияют чистотой? Не верьте этим фильтрам. Ваш беспорядочный, шумный и настоящий дом — самое тёплое и совершенное гнёздышко любви для вашего ребёнка.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'Аргумент маленького адвоката 🗣️', '«Я съем шоколад, потому что я уже большой». Малыш уже выстраивает причинно-следственные связи и пытается договориться с вами! Это прекрасный показатель развития речи. Похвалите его, но продолжайте мягко придерживаться своих границ и правил.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'Терапия тишиной 🤫', 'Малыш наконец уснул! Включите шумомер и, наблюдая, как цифры на экране опускаются до 0 децибел, почувствуйте, как успокаивается ваш уставший мозг и как эта видимая тишина мягко массирует его.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'Катастрофа на кухне 🧑‍🍳', 'Пока вы раскатываете тесто, малыш опускает руку в муку и всё вокруг становится белым. Да, на кухне беспорядок, и работы у вас прибавилось. Но не упустите момент: сразу запечатлейте его серьёзное, деловитое выражение лица с помощью «Фотосессии малыша». Беспорядок исчезнет, а воспоминание останется.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'Ночная миграция 🛏️', 'Малыш засыпает в правильной позе, а утром просыпается с ногами на подушке и головой в противоположном углу кровати. Даже во сне он исследует мир! Прежде чем будить малыша, с улыбкой понаблюдайте за его забавными ночными перемещениями.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'Философская отсрочка сна 🦉', 'Стоит лечь в кровать, как малыш задаёт глубокие вопросы вроде: «Мама, почему звёзды не падают?» Цель не в том, чтобы узнать что-то новое, а в том, чтобы отложить сон. Давайте короткие, выдуманные и милые ответы, а затем включите «Умные сказки», чтобы в комнате сразу воцарилась сонная тишина.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'Герой в костюме 🦸‍♂️', 'Малыш упорно хочет ходить по дому в зимних сапогах или маске супергероя? Забудьте об общественных нормах и эстетике. Так он исследует свою индивидуальность. Позвольте ему почувствовать себя героем, расхаживая по комнате в сапогах.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'Зубы динозавра 🦖', 'Малыш наотрез отказывается чистить зубы и бросает щётку. Превратите всё в игру! Дайте ему запасную щётку и скажите: «Давай сначала почистим зубы твоему игрушечному динозавру». Пока он чистит зубы динозавру, вы сможете незаметно почистить зубы ему.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'Пятна самостоятельности 🥣', 'Малыш непременно хочет есть йогурт вилкой и пачкает всё вокруг. Не вмешивайтесь и не забирайте у него вилку. Разбросанную еду можно убрать, а вот восстановить его уверенность «я сам» гораздо сложнее. Наденьте на малыша силиконовый нагрудник и терпеливо наблюдайте за происходящим.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'Мамины 10 минут 🚪', 'От шума у вас уже гудит голова. Откройте дневник настроения и свободно выпишите на экран всё, что сегодня выводило вас из себя, чтобы нажать свою внутреннюю кнопку перезагрузки.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'Очарование ненужных вещей 📦', 'Вокруг столько дорогих светящихся игрушек, а малыш часами играет с пустой пластиковой бутылкой или картонной коробкой. Детское воображение любит не готовые сценарии, а простые предметы, открывающие простор для творчества. Наблюдайте и учитесь.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'Бунт после сна ☁️', 'Проснувшись утром, малыш хмурится и обижается на вас. Причина? Во сне вы не дали ему желанную игрушку! Детский мозг пока не умеет полностью отличать сон от реальности. Серьёзно попросите прощения, а про себя улыбнитесь этой абсурдной ситуации.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'Молчаливый обмен взглядами 🥂', 'Ребёнок наконец уснул. Вы с партнёром сидите рядом на диване, и у вас нет сил даже разговаривать. Вы просто молча смотрите друг на друга и улыбаетесь. Да, такой безмолвный обмен взглядами — лучший способ сказать: «Мы справляемся с этим хаосом».'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'Театр на стене 🐰', 'Малыш убегает из кровати, потому что боится темноты. Выключите в комнате весь свет, включите фонарик и покажите на стене тени птицы или собаки с помощью рук. Темнота, которой он боялся, за считаные секунды превратится для него в самый безопасный театр в мире.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'Тактика ухода из парка 🌳', 'Пора возвращаться из парка, и начинается истерика. Не пытайтесь увести малыша силой. Устройте соревнование, сказав: «Посмотрим, кто быстрее добежит до машины?» Дети редко отказываются от возможности посоревноваться и победить.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'Невидимый гость 👻', 'За завтраком малыш требует поставить тарелку и для своего воображаемого друга. Это не признак психологической проблемы, а скачок в развитии интеллекта. Поставьте тарелку и налейте гостю воображаемого чая, став частью этого прекрасного представления.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'Открытия в новом словаре 🗣️', 'Малыш придумывает предметам совершенно новые названия, которых нет ни в одном языке. И упорно требует, чтобы вы тоже использовали эти слова! Откройте трекер развития и обязательно запишите его забавные словечки, чтобы в будущем перечитывать их и смеяться.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'Тайные сокровища дома 🔑', 'Не можете найти ключи от дома или пульт? Загляните в игрушечную духовку или под кровать малыша. Пряча предметы, он исследует устройство мира. Во время этих забавных поисков сокровищ постарайтесь не сердиться, а улыбнуться и глубоко вдохнуть.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'Парадокс купания 🛀', 'Малыш плакал, потому что не хотел идти в ванну, а теперь кричит, потому что не хочет из неё выходить! Волшебное успокаивающее действие воды словно загипнотизировало его. Чтобы выход из ванны прошёл без лишней драмы, назовите полотенце «тёплыми объятиями», заверните в него малыша и вынесите.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'Упрямое «Моё!» 🧸', 'Малыш обнимает какой-нибудь случайный предмет в доме, кричит: «Это моё!» — и никому его не отдаёт. Так он исследует границы собственности. Не обвиняйте его в эгоизме — просто на время признайте этот предмет его собственностью.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'Оттенок вашего голоса 🌙', 'Малыш слушает не сюжет сказки из книги, а тон вашего голоса. Сегодня вечером забудьте о сюжете. Читайте медленно, растягивая повествование, тихим голосом, словно нежную мелодию, — так вы напрямую подадите его нервной системе сигнал ко сну.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'Иллюзия социальных сетей 📱', 'Смотрите на идеальных мам в интернете и вините себя за беспорядок дома? Остановитесь. Не верьте этим 15-секундным видео с фильтрами.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'Децибелы тишины 🤫', 'Малыш наконец уснул! Не спешите убираться в комнате. Включите шумомер и посмотрите на эти 0-10 децибел на экране. Это визуальное подтверждение абсолютной тишины в доме подействует на ваш уставший мозг как самый приятный массаж.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'Профессор философии 🧐', 'Мама, малыш уже спрашивает не «Почему солнце там?», а просто «Почему солнце существует?». Его вопросы становятся всё более абстрактными. Не утомляйте себя многочасовыми научными объяснениями. Короткий, сказочный и тёплый ответ вроде «Потому что оно любит нас согревать» полностью его удовлетворит.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'Ножки ушли в отпуск 🚶‍♂️', 'Посреди улицы малыш внезапно садится на землю и говорит: «У меня ножки сломались, возьми меня на руки». Нет, он не устал — просто проверяет вас. Не поддавайтесь на шантаж. Скажите: «Посмотрим, как мы дойдём до машины по-пингвиньи?» — и вовлеките его в игру.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'Цветная диета 🥕', 'Сегодня малыш решил есть только оранжевые продукты и отказывается от всего остального. Детская логика снова в деле! Узнайте, как замаскировать овощи в полезных блюдах. Победите это упрямство с помощью разных рецептов с пюре из тыквы и моркови.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'Утренний солист 🎤', 'Ещё раннее утро, вы с трудом открываете глаза, а малыш уже даёт концерт посреди комнаты с игрушкой в руке. Не пытайтесь его утихомирить. Эта безумная, неиссякаемая детская энергия на самом деле приносит в дом благополучие и радость. Посмотрите на него с улыбкой.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'Исцеляющее прикосновение 💆‍♂️', 'Малыш никак не успокаивается в постели. Отложите сказку и музыку. Сделайте ему очень лёгкий, поглаживающий массаж маленьких ножек или спины. Физический контакт мгновенно снизит уровень кортизола (гормона стресса) и у малыша, и у вас, помогая заснуть.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'Невидимые крошки 🧹', 'С очень серьёзным выражением лица малыш убирает невидимую пыль с ковра маленькой щёткой. Он просто подражает вам. Запечатлейте этот ответственный момент на фотосессии малыша: самый маленький и милый помощник по дому уже за работой.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'Терапия шумомером 🤫', 'Маленький домашний ураган наконец сдался и лёг спать. В комнате не слышно ничего, кроме шума посудомоечной машины. Включите шумомер, посмотрите на минимальные значения децибел на экране и закройте глаза. Эта визуальная тишина — лучший массаж для вашего мозга.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'Пробуждение по-кошачьи 🐾', 'Сегодня утром малыш — не человек. Он ходит на четвереньках, трётся о ваши ноги и общается исключительно с помощью «мяу». Это самый милый и яркий расцвет воображения. Вместо того чтобы устанавливать правила, протяните ему воображаемую миску с молоком и наслаждайтесь этой игрой вместе.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'Признание в сообществе 💬', 'Сегодня вы на всё реагировали криком и чувствуете себя самой нетерпеливой мамой на свете? Пожалуйста, помните: вы не одиноки. Зайдите в сообщество Anacan, прочитайте, что другие мамы сегодня вымотались не меньше вас, и успокойте свою совесть.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'Безумная папина сказка 📖', 'Сегодня вечером в комнате будет звучать не ваш голос. Передайте книгу сказок папе и пусть он намеренно рассказывает историю наоборот — смешно и абсурдно. А вы наблюдайте со стороны, с каким удовольствием малыш его поправляет и как звонко смеётся над папиными выдумками.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'Архитектор-авангардист 🥞', 'За завтраком малыш складывает блинчики друг на друга, строит башню, проделывает в ней отверстие и просовывает туда палец. Игра с едой для него — новый инженерный проект. Закройте глаза на испачканный стол: так он исследует текстуру пищи.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'Воображаемый магазин 🍅', 'В углу комнаты малыш разложил игрушки и продаёт вам воображаемый помидор за воображаемые деньги. Отнеситесь к этой торговле со всей серьёзностью. Купите воображаемый помидор и притворитесь, будто едите его с аппетитом. Ролевые игры закладывают прочнейший фундамент его социального интеллекта и математического мышления.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'Мамин тайный шоколад 🍫', 'Мама, которая тайком от малыша ест кусочек шоколада за кухонным шкафом, эта глюкоза — ваше законное право. Чтобы весь день выдерживать такой темп и бесконечные «почему», вам тоже необходимо подзаряжаться. Вдохните и смакуйте каждый кусочек.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'Ночной страх 😭', 'Посреди ночи малыш просыпается с закрытыми глазами, плачет и никого не слышит. Проверьте с помощью анализа плача: если это ночной страх, не трясите и не пытайтесь разбудить малыша. Просто молча побудьте рядом, давая ему чувство безопасности, — это пройдёт.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'Ледяная логика 🥶', 'Малыш открывает холодильник, требует формочку со льдом и не выпускает её из рук, даже когда они мёрзнут. Так он исследует тепло и холод с помощью собственного тела. Налейте в одну ёмкость тёплую, а в другую — ледяную воду, превратив это открытие в небольшой научный эксперимент. Упрямство исчезнет вмиг.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'Обязательная вылазка на природу ⛅', 'В четырёх стенах его энергия превращается в агрессию, и каждое предложение начинается со слова «нет». Независимо от погоды и одежды обязательно выйдите с ним на улицу, предварительно как следует подготовившись. Контакт с землёй поможет его нервной системе быстро перезагрузиться.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'Ночник 🌙', 'Малыш беспокоится, когда в спальне гаснет свет? Поставьте в углу комнаты небольшой ночник тёплого оттенка — оранжевого или красного. При этом остальная часть комнаты должна оставаться совершенно тёмной для выработки мелатонина и глубокого сна.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'Цифровой список-спасатель 🛒', 'Стоя посреди магазина, вы пытаетесь вспомнить, что собирались купить? Мамино внимание и так разрывается между тысячей дел. Возьмите за привычку сразу же записывать всё необходимое в список покупок в приложении — так вы облегчите себе жизнь.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', 'Провокация «Давай я помогу!» 🧽', 'Когда вы моете посуду, малыш непременно хочет поставить рядом стул и играть с водой? На самом деле он хочет не помочь, а оказаться в самом центре событий. Дайте ему небольшую пластиковую миску и губку. Кухню зальёт водой, зато его самооценка взлетит до небес.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'Волшебная частота музыки 🎶', 'Попробуйте останавливать беспричинные вечерние бури и крики с помощью спокойной классической музыки. Часто этот простой, но действенный приём волшебным образом меняет напряжённую атмосферу в комнате и погружает ребёнка в умиротворение.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'Инженер гардероба 👗', 'Сегодня малыш хочет выйти на улицу в разных носках и вывернутой наизнанку футболке. Забудьте об общественных нормах сочетаемости. Свобода самостоятельно принимать и отстаивать решения — гораздо более важный жизненный урок, чем сочетание цветов. Позвольте ему.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'Искусственный интеллект и спокойствие 🤖', 'Резкие перепады настроения у ребёнка ближе к 3 с половиной годам встревожили вас? Закройте пугающие и травмирующие форумы в интернете. Получите от Anacan AI спокойный, научно и психологически обоснованный ответ о возрастных кризисах этого периода.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'Пусть малыш напишет сценарий 🪄', 'Вам обоим надоели обычные книги, и в комнате царит скука. Откройте умные сказки и сегодня вечером позвольте малышу направлять сюжет. Спросите: «Куда теперь отправится летающая машина?» — и пусть он уснёт, покоряя воображаемые миры.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'Гипноз шёпотом 🤫', 'Малыш лежит в кровати, задирает ноги вверх и совсем не хочет засыпать. Вместо крика внезапно понизьте голос и разговаривайте с ним только шёпотом. Когда ребёнок сосредоточится, чтобы расслышать вас, его мозг автоматически успокоится и переключится в режим сна.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Offline-момент для мамы 🛋️', 'Пока малыш смотрит мультфильм или увлечён игрушками, вы спешите разгрузить посудомоечную машину или развесить бельё? Остановитесь! Потратьте эти 10 минут на то, чтобы просто полежать на диване, посмотреть в потолок и ни о чём не думать. Вы не робот.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'Закончите фразу 🗣️', 'Забыв слово, малыш жестикулирует, хмурит брови и ждёт, что вы догадаетесь. Его словарный запас растёт — просто мозг работает быстрее, чем речь. Терпеливо закончите его фразу и увидите на лице облегчение: «Да, именно это я и хотел сказать!»'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'Пищевой дизайнер 🥦', 'Малыш сортирует еду на тарелке по цвету и форме, а всё зелёное отодвигает в сторону. Загляните в раздел полезных рецептов. Узнайте, как превратить овощи в незаметное пюре и спрятать их во вкусных соусах, чтобы незаметно одержать победу в этой игре.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'Верхом на папе 🐴', 'Малыш не успел выплеснуть всю энергию и отказывается ложиться спать. Позовите папу на помощь. Когда папа катает ребёнка на спине, словно на лошади, комнату наполняет смех, а накопившееся физическое напряжение и неуёмная энергия исчезают за считаные секунды вместе с потом.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'Опасные словечки 🤐', 'Малыш со смехом повторяет вам плохое слово, услышанное на улице или по телевизору, и с огромным любопытством ждёт вашей реакции. Ваше главное оружие — отсутствие реакции. Не смейтесь, не сердитесь, просто проигнорируйте. Вскоре он забудет это слово.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'Океан в ванне 🌊', 'Купание в ванне — это уже не просто гигиена, а игра с волнами. Пусть вода разбрызгивается вокруг, а ванная намокнет. Магическая сила воды смоет всю накопившуюся за день упрямую негативную энергию и унесёт её в канализацию.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'Тайны за закрытой дверью 🚪', 'Малыш заходит в свою комнату, закрывает за собой дверь и хочет побыть один? Так формируются представление о личном пространстве и индивидуальность. Позаботьтесь о безопасности и признайте его право на это небольшое личное пространство. Он взрослеет.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'Признание в дневнике настроения 📝', 'Возьмите телефон. Вместо того чтобы листать в социальных сетях чужие идеальные жизни, откройте дневник настроения и запишите на память самый забавный поступок малыша за сегодня — момент, который рассмешил вас больше всего. Такие записи — настоящая терапия.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'Шампанское для двоих 🥂', 'Малыш уснул. Даже если шампанского нет, налейте в бокалы горячий чай, чокнитесь с партнёром и скажите: «Мы благополучно пережили ещё один бурный день». Вы одновременно и полководцы этого дома, и его несокрушимая команда.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'Нелогичные слёзы 🐶', 'Малыш рыдает из-за того, что встреченная на улице собака не посмотрела на него или лист упал на землю? Не ищите здесь логики. Для него это действительно глубокое огорчение. Просто признайте его чувства, сказав: «Я знаю, тебе хотелось, чтобы собака посмотрела на тебя».'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'Дипломатия в парке 🤝', 'Малыш толкает другого ребёнка на горке, потому что хочет прокатиться сам? Умение делиться для него пока остаётся сложным и не до конца понятным. Вместо того чтобы стыдить или наказывать, просто напомните правило: «Сейчас его очередь».'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'Сигналы тела 🩸', 'Не позволяйте беспричинной раздражительности и усталости взять верх. Загляните в трекер менструации — ваше тело подаёт сигнал. Вместо того чтобы винить себя, отдохните и перекусите чем-нибудь богатым магнием.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'Битва с тенью 👻', 'Малыш пугается своей тени на стене и прячется за вами? Ближе к середине третьего года жизни воображение не знает границ. Затемните комнату и устройте с помощью фонарика театр теней, складывая руками фигурки на стене. Превратите пугающую его темноту в самое весёлое развлечение.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'Волшебство сказок 🪄', 'Отложите привычную манеру чтения. Откройте умные сказки. Устройте в комнате небольшой звуковой театр: голосом изображайте шум ветра, скрип двери и шаги героя. Малыш будет в восторге от этого представления.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'Тактика откладывания сна ⏱️', 'Когда приходит время спать, малыш внезапно хочет пить, просится в туалет или начинает прощаться со стеной? Установите таймер. Введите правило «Когда звенит таймер, все ложатся спать» и терпеливо положите конец этим бесконечным прощаниям и искусным манипуляциям.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'Мама для игрушек 🧸', 'Из комнаты доносится голос. Вы прислушиваетесь и слышите, как малыш ругает своего плюшевого мишку, в точности повторяя вашу интонацию и характерные фразы! Он — ваша точная копия. Это прекрасная возможность взглянуть на собственное поведение со стороны.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'Погодная разведка ⛅', 'На улице непонятная погода: светит солнце, но при этом дует ветер? Пусть инструмент погоды и одежды мгновенно подскажет вам скорость ветра, которую не определишь из окна, и подходящий комплект одежды. Больше никаких сомнений и потери времени у двери — отправляйтесь на прогулку.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'Секретная тактика папы 👨‍🍼', 'За день вы уже достаточно устали от шума и забот. Вечером поручите папиным играм подготовку малыша ко сну и чистку зубов, а сами обязательно отдохните в полной тишине в другой комнате.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'Энергетический батончик для мамы 🥑', 'Вы составили для малыша меню в 4 разных вариантах, но что поели сами? Выберите среди полезных рецептов особый богатый кальцием перекус, который можно приготовить за 5 минут, и насладитесь им, даже если придётся есть стоя. Вы — двигатель этого дома.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'Завтрак, которым не делятся 🍳', 'Малыш ни за что не поделится с вами тем, что лежит на его тарелке, но настойчиво требует яйцо или сыр из вашей. Дети безоговорочно доверяют выбору родителей. Не сопротивляйтесь — с любовью отдайте ему свой кусочек.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'Командный массаж 💆‍♂️', 'Когда малыш уснёт, сделайте друг другу с партнёром массаж плеч, чтобы снять физическое и эмоциональное напряжение, накопившееся за день. Вы не просто родители, живущие под одной крышей, а несокрушимая команда поддержки.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'Это не моя вина! 🤷‍♂️', 'Он нарочно пролил воду на пол, но свалил вину на стол, сказав: «Стол подвинулся». Это не ложь, а инстинктивная попытка защитить себя. Не спорьте с ним, а мягко прививайте ответственность, предложив: «Давай поможем столу и вместе всё вытрем».'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'Поддержка сообщества 💬', 'Вас внезапно накрывает мысль: «Я уже никогда не стану прежней — свободной»? Поделитесь этим временным, но очень тяжёлым и глубоким чувством с мамами в Сообществе Anacan. Женщины, прошедшие тот же путь, смогут утешить и поддержать вас.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'Просто обнимите 🫂', 'Не нужны ни игры, ни шумные книжки, ни сказки. Сегодня вечером просто прижмите малыша к груди, глубоко вдохните его чистый аромат и прошепчите в темноте, как он дорог вам и как сильно вы его любите.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', '«Я сам повезу!» в магазине 🛒', 'Он хочет сам катить тележку и, врезаясь в стеллажи, устраивает настоящий хаос. Чтобы не доводить малыша до слёз на людях, позвольте ему держаться за края тележки, а сами незаметно направляйте её. А всё ли вы купили, проверьте по списку покупок.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'Игрушечный хаос 🌪️', 'Устали каждый день собирать одни и те же игрушки? Сегодня не собирайте! Дом — не музей, а тёплое пространство, где кипит жизнь и растёт маленький исследователь. Не думайте о беспорядке — сосредоточьтесь на радости свободных открытий вашего ребёнка и отдохните.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'Посмотрите вниз: что он исследует? 👣', 'Ему нравится ходить босиком, ощущая ковёр, каменную поверхность или холодную плитку. Стимуляция нервных окончаний на стопах очень важна для равновесия и неврологического развития, поэтому не мешайте ему ходить без носков.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'Искусственный интеллект, реальное решение 🤖', 'Вас пугает, что ребёнок на всё реагирует слишком остро? Забудьте о тревожных статьях из интернета. Спросите у Anacan AI, может ли это быть лишь временной реакцией на стресс, и получите научно обоснованный, одобренный педиатрами ответ, который поможет вам успокоиться.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'Тишина в цифрах 🤫', 'Он наконец уснул! Вы не можете поверить в тишину, воцарившуюся дома. Включите шумомер и, глядя на показатель 0-10 децибел на экране, буквально почувствуйте, как ваш мозг постепенно восстанавливается и отдыхает.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'Выключите свет — и сон придёт 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин (гормон сна) активно вырабатывается в темноте и при отсутствии гаджетов, облегчая засыпание.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'Вдохновение из блогов 📱', 'Какие скачки развития происходят у ребёнка ближе к 40-му месяцу? Что он уже должен уметь? Загляните в блоги о развитии в приложении и порадуйтесь тому, как далеко продвинулся ваш ребёнок в понимании и логическом мышлении.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'Окончание незаконченных фраз 🗣️', 'Забыв слово, он показывает жестами, хмурит брови и ждёт, пока вы догадаетесь. Терпеливо закончите его фразу и посмотрите, как на лице появляется облегчение: «Да, именно это я и хотел сказать!» Только вы умеете переводить его мысли без слов.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'Синдром внезапного голода 🥱', 'Стоит лечь в постель, как он говорит: «Мама, я голоден» — и хочет бежать на кухню. Настоящий шедевр для отсрочки сна! Заранее предусмотрите в плане питания небольшой вечерний перекус, способствующий засыпанию, и лишите эту отговорку силы.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', 'Шантаж «У меня устали ножки» 🚶‍♂️', 'Во время прогулки он внезапно садится на землю и говорит: «У меня ножки сломались, возьми меня на ручки»? Возможно, дело не в физической усталости, а в попытке добиться желаемого. Превратите ситуацию в игру: «Посмотрим, кто быстрее допрыгает до дома, как зайчик?»'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'Кнопка перезагрузки для мамы 🚪', 'Шум буквально сверлит мозг, и вам хочется на всех накричать. Откройте дневник настроения и свободно опишите в нём всё своё истощение. Эта короткая цифровая терапия поможет вам перезагрузиться.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'Папина сказка 📖', 'Сегодня ваш голос устал. Поручите чтение сказки папе. Глядя на картинку в книге, он придумает совершенно другую, забавную историю и рассмешит ребёнка до слёз. А вы с удовольствием наблюдайте за ними со стороны за чашкой чая.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'Помощник по стирке 🧺', 'Вы с большим трудом складываете одежду, а он со словами «Я помогаю» снова разбрасывает всё по комнате. Вместо того чтобы сердиться, превратите дело в игру: «Посмотрим, кто быстрее и точнее забросит эти носки в корзину?»'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'Обязательно выбирайтесь на природу ⛅', 'В четырёх стенах его энергия превращается в агрессию, и каждое предложение начинается со слова «нет». Независимо от погоды и одежды, подготовьтесь как следует и обязательно выведите его на улицу. Контакт с землёй поможет его нервной системе быстро перезагрузиться.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'Когда логика не работает 🔴', 'Он кричит, чтобы вы налили воду в красный стакан, а когда вы наливаете, плачет: «Зачем ты налила сюда?» Здесь нет логики. Он просто устал, и ему нужно выплеснуть эмоции. Спокойно подождите — буря утихнет сама.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'Сокровища из карманов 🪨', 'При стирке вы нашли в кармане его брюк 2 камешка, засохший лист и обломок веточки? Для вас это мусор, а для него — ценная коллекция, собранная во время исследования мира. Не выбрасывайте находки, а сложите их в небольшую шкатулку с сокровищами.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'Я — герой волшебной сказки 🪄', 'Классические книги вы уже знаете наизусть. Включите умные сказки, сделайте своего ребёнка главным героем, а его комнату — местом, которое предстоит покорить. Так вы создадите необычный аудиосеанс для сна, не требующий никаких усилий.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'Не мусор, а искусство 🎨', 'Посреди комнаты он создал огромное произведение искусства из обрывков бумаги и нарезанных ниток и не разрешает вам его выбросить. Отложите стремление к идеальной чистоте. Отнеситесь с уважением к созданному им хаосу — уборка может подождать до завтра.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'Помощь анализа плача 😭', 'Он проснулся среди ночи, плачет с закрытыми глазами и никого не слышит. Проверьте это с помощью анализа плача: если это ночной ужас, не пытайтесь его разбудить. Просто молча побудьте рядом — через несколько минут он снова уснёт.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'Разговоры с неодушевлёнными предметами 🗣️', 'В парке он совершенно серьёзно разговаривает с камнем, а дома — со стулом и даже ругает их. С помощью символических игр он осмысляет мир и его правила. Обязательно отмечайте такие необычные сценарии в трекере развития.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'Игры в ванне 🌊', 'Купание в ванне — это уже не про чистоту, а про игру с волнами. Пусть вода разбрызгивается и ванная намокнет. Притягательная сила воды смоет накопившуюся за день упрямую негативную энергию и унесёт её в слив.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'Разрушение с целью 🧱', 'Он с большим трудом строит башню, а затем со смехом разрушает её одним ударом. Так он изучает физику и причинно-следственные связи. Не сердитесь: разрушенные башни создают новые нейронные связи в его мозге. Помогите ему построить башню заново.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'Катастрофа с дневным сном 🥱', 'Не хочет ложиться и плачет? Не заставляйте. Приглушите свет в комнате и объявите тихий час для рассматривания книг. Создайте новый распорядок, который поможет отдохнуть вам обоим, пусть и по-разному.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'Воображаемый магазин 🍅', 'Он собрал игрушки в углу комнаты и продаёт вам воображаемый помидор за воображаемые деньги. Отнеситесь к этой торговле со всей серьёзностью. Купите воображаемый помидор и сделайте вид, что едите его с аппетитом. Ролевые игры — важнейшая основа его социального интеллекта.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'Музыкальный гипноз 🎶', 'Под вечер начались беспричинные бури и приступы плача. Выключите телевизор, приглушите свет и включите в комнате очень тихую классическую музыку. Её глубокие частоты волшебным образом изменят атмосферу.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'Совершенства не существует 🛑', 'Сегодня ваше терпение иссякло? Не вините себя. Забудьте об иллюзии идеальной мамы из интернета. Вы настоящая мама и имеете право испытывать эмоции и усталость.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'Спасение в супермаркете 🛒', 'Отправляясь в магазин, вы всегда забываете самое важное? Список покупок уже ждёт вас в приложении. Запишите туда всё необходимое, чтобы ваш партнёр по дороге с работы купил именно то, что нужно, а вам не пришлось держать всё в голове.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', 'Этап «Мама, смотри на меня!» 👀', 'Он прыгает с дивана и ровно 50 раз повторяет одно и то же, каждый раз говоря: «Мама, смотри на меня!» Оторвитесь от телефона. Он прыгает ради искорки одобрения в ваших глазах. Подарите ему 5 минут безраздельного внимания, чтобы он им насытился.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'Истории шёпотом 🌙', 'Сегодня вам пришлось много говорить, и голос уже устал. Выключите свет, лягте рядом и шёпотом расскажите ему на ухо о том, что произошло за день. Шёпот помогает сосредоточить его внимание и словно гипнотизирует, подготавливая мозг к глубокому сну.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'Утренний диктатор за работой 👑', 'Не садись туда, там будет сидеть мишка! За завтраком малыш командует всем столом. Не подавляя его волю, скажите: «Хорошо, пусть мишка сидит там, а я сяду здесь», — и сохраните баланс и мир в комнате.'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'Чай при свечах 🕯️', 'Малыш уснул. Выключите свет и зажгите на столе свечу. Не ради романтики, а просто чтобы успокоить нервы, раздражённые за весь день, и глаза, уставшие от экранов и шума.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'Усталость от прикосновений 🔋', 'Весь день малыш карабкается на вас, просится на руки и играет с вашими волосами. Усталость от прикосновений (touched out) действительно существует. Вы имеете право хотя бы на 15 минут уединиться в комнате и почувствовать, что ваше тело принадлежит только вам.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'Верхом на папе 🐴', 'Малыш не успел выплеснуть всю энергию и отказывается ложиться спать. Позовите папу на помощь. Пока он катает малыша на спине, изображая лошадку, комнату наполняет смех, а накопившееся физическое напряжение и неуёмная энергия за считаные секунды выходят вместе с потом.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'Признание в сообществе 💬', 'Сегодня вы на всё реагировали криком и чувствуете себя самой нетерпеливой мамой на свете? Пожалуйста, помните, что вы не одиноки. Зайдите в сообщество Anacan и почувствуйте облегчение, прочитав, что другие мамы сегодня тоже вымотались до предела.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'Соперник в зеркале 🪞', 'Малыш стоит перед зеркалом, хмурится и строит сердитые и забавные гримасы. Так он проверяет, как разные эмоции выглядят на лице. Не мешая, с интересом понаблюдайте за репетицией этого маленького театрального актёра.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'Операция «Секретное питание» 🥣', 'Ещё вчера малыш любил яйца, а сегодня категорически отказывается их пробовать. Не вступайте в борьбу с его волей. Используйте хитрые рецепты полезных перекусов, в которых белковые продукты приобретают разные яркие и интересные формы, — и победа останется за вами.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'Подтверждение тишины 🤫', 'После шумного дня, когда малыш уснёт, измерьте тишину в комнате с помощью шумомера. Вид цифр, приближающихся к нулю, подействует на мозг мамы словно лучший расслабляющий массаж.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'Неожиданное «Я тебя люблю» 💖', 'Играя посреди комнаты, малыш вдруг смотрит на вас, подбегает и обнимает за шею. Ради этого стоили все бессонные ночи и усталость! Насладитесь глубоким и неповторимым умиротворением, которое дарит этот момент.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'Выключаем свет — пора спать 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите все дополнительные источники света и экраны планшетов. Мелатонин (гормон сна) активно вырабатывается только в тёмной обстановке без гаджетов.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'Потребность в клетчатке 💩', 'Малыш много бегает, но забывает пить воду. Следите за стулом при пользовании горшком. Если есть риск запора, отметьте это в приложении и сразу добавьте в меню овсянку и сливы с помощью инструмента «Контроль питания».'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'Опасные словечки 🤐', 'Малыш со смехом повторяет услышанное на улице или по телевизору плохое слово и с большим интересом ждёт вашей реакции. Ваше главное оружие — отсутствие реакции. Не смейтесь, не сердитесь, просто проигнорируйте. Вскоре он забудет это слово.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'Пусть малыш придумает финал сказки 🪄', 'Вы оба уже устали от классических книг. В этот раз в «Умных сказках» предложите малышу самому выбрать концовку истории. Спросите: «Как ты думаешь, кто помог герою?» — и перед сном дайте волю его воображению.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'Ледяная логика 🥶', 'Малыш открывает холодильник, требует формочку со льдом и не выпускает её из рук, хотя они уже мёрзнут. Так он на собственном опыте изучает понятия тепла и холода. Налейте в одну ёмкость тёплую, а в другую — ледяную воду и превратите это исследование в небольшой научный эксперимент.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'Пробежка с папой в парке 👨‍👧', 'Материнство — не круглосуточная смена 24/7. Подключите партнёра! Пусть сегодня малыш выплеснет свою неуёмную энергию с папой в парке, а вы тем временем насладитесь дома абсолютной тишиной.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'Концерт на кухне 🥄', 'Малыш достаёт кастрюли и деревянные ложки и устраивает концерт посреди кухни. Даже если у вас болит голова, помните: так развиваются его чувство ритма и творческие способности. Не спешите вмешиваться — позвольте этой безумной энергии несколько минут разноситься по комнате звуковыми волнами.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'Искусство на теле 🖍️', 'Вас насторожила внезапная тишина, и вы обнаружили, что малыш рисует фломастером произведение искусства на своих руках. Не сердитесь. Так он исследует возможности мелкой моторики, а кожу можно отмыть водой. Глубоко вдохните и снимите этот забавный момент на видео.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'Гипноз шёпотом 🤫', 'В кровати малыш так активен, что никак не может уснуть. Вместо того чтобы повышать голос, внезапно понизьте его и разговаривайте только шёпотом. Когда ребёнок сосредоточится, чтобы вас услышать, его мозг автоматически начнёт переключаться в режим сна.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'Сила маминого сообщества 💬', 'Вас изматывает мысль: «Этот ребёнок никогда не успокоится»? Присоединяйтесь к Сообществу Anacan. Прочитав похожие и даже более забавные истории других мам о детском упрямстве, вы поймёте, что не одиноки, и сможете вздохнуть с облегчением.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'Профессор философии 🤔', '«Почему ветер невидимый?», «Почему падают листья?» Глубокие вопросы с самого утра заставляют ваш мозг закипать. Не пытайтесь часами давать научные объяснения. В этом возрасте малыша вполне удовлетворят милые выдуманные ответы вроде: «Потому что деревья переодеваются».'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'Танец с тенями 🐰', 'Малыш убегает из кровати, говоря, что боится темноты. Выключите в комнате весь свет, включите фонарик и покажите руками на стене тени птиц и собак. Темнота, которой он боялся, за считаные секунды превратится для него в театр.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'Искусственный интеллект спешит на помощь 🤖', 'Не находите ответов на вопросы ребёнка или не понимаете его странное поведение? Обратитесь к Anacan AI. Он кратко и доступно, с точки зрения педиатрии, объяснит вам, как работает мозг ребёнка старше 3 лет, и поможет успокоиться.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'Тепло его дыхания 💖', 'Весь день малыш сводил вас с ума и упрямился по любому поводу. Но теперь он прижался к вашей груди в кровати, и комнату наполняет его размеренное дыхание. Именно в этом и заключается главная награда материнства. Прижмите его к себе и забудьте обо всей усталости.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'Гордость за обувь не на ту ногу 👟', 'Малыш надел обувь не на ту ногу, но ходит с таким гордым видом, будто покорил весь мир. Не вмешивайтесь и не пытайтесь всё исправить. Уверенность ребёнка в себе и его самостоятельность в миллион раз важнее эстетичного вида одежды.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'Вершина эмпатии 🩹', 'Малыш наклеивает пластырь на лапу игрушечного мишки и целует её, потому что она болит? Полюбуйтесь его большим и добрым сердцем. С гордостью отметьте эту глубокую эмпатию в Трекере развития как одну из самых прекрасных черт характера.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'Папина игровая площадка 👨‍👧', 'Ваше терпение на исходе? Закройте дверь в комнату и оставьте ребёнка наедине с папой. Пусть сегодня вечером он руководит всеми домашними играми, а вы отдохните.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'Смотри, что я умею! 🤸‍♂️', 'Малыш пытается привлечь ваше внимание, стоя на одной ноге или подпрыгивая? Ему нужно ваше одобрение. Отметьте этот навык равновесия в Трекере развития и похвалите ребёнка.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'Овощные сражения 🥦', 'Малыш отодвигает в сторону зелёные овощи на тарелке? Не боритесь с ним. Найдите среди полезных рецептов хитрые способы спрятать овощи в кексах или котлетах.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'Боится темноты? 👻', 'Ближе к 3.5 годам страх темноты возникает довольно часто. Поставьте в комнате небольшой ночник и создавайте в Умных сказках истории о смелых героях.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'Мамины беседы 💬', 'Вас беспокоит мысль: «Почему мой ребёнок до сих пор не освоил горшок полностью?» Присоединяйтесь к Сообществу Anacan — там вы увидите, что каждый ребёнок развивается в своём темпе.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'Искажает слова? 🗣️', 'Малыш намеренно заменяет некоторые звуки, смешно произносит слова и смеётся над этим? Так он исследует гибкость языка. Присоединяйтесь к нему и поиграйте в словесные игры.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'Первые дружеские чувства 👫', 'В парке малыш уже пытается играть вместе с другими детьми — не параллельно, а взаимодействуя с ними? Социализация официально началась! Наблюдайте за этим моментом на расстоянии, оставаясь рядом для подстраховки.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'Разведка погоды ⛅', 'На улице не совсем ясно: светит солнце, но при этом дует ветер? Инструмент погоды и подбора одежды мгновенно подскажет скорость ветра, которую не определить из окна, и подходящий наряд — отправляйтесь на прогулку, не теряя времени у двери в сомнениях.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'Командный массаж 💆‍♂️', 'Когда ребёнок уснёт, сделайте друг другу массаж плеч, чтобы вместе с партнёром снять накопившийся за день стресс. Вы не просто родители, живущие под одной крышей, а сплочённая команда поддержки.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'Резкие перепады эмоций 🤖', 'Ближе к 3 с половиной годам резкие перепады эмоций у ребёнка начали вас тревожить? Закройте пугающие и травмирующие форумы в интернете. Спросите у Anacan AI и получите спокойный, научно и психологически обоснованный ответ о возрастных кризисах.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'Чудо тёплой воды 🛀', 'Иногда ничего не помогает и ребёнок плачет буквально из-за всего. Посадите его в ванну с тёплой водой и добавьте немного пены. Волшебная способность воды снимать напряжение мгновенно принесёт спокойствие и в комнату, и в его нервную систему.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'Инженер гардероба 👗', 'Сегодня ребёнок хочет выйти на улицу в разных носках и футболке задом наперёд. Забудьте об общественных нормах соответствия. Свобода самостоятельно принимать и отстаивать решения — куда более важный жизненный урок, чем сочетание цветов. Позвольте ему это.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'Живой диктофон 🎙️', 'Сегодня утром ребёнок повторяет своей игрушке случайное и, возможно, неуместное слово, которое вчера услышал из вашего разговора с партнёром! Он — ваше живое зеркало. Особенно внимательно следите за тем, с какими эмоциями вы разговариваете рядом с ним: он копирует всё до мелочей.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'Весёлая папина сказка 📖', 'Сегодня вечером пусть в комнате звучит не ваш голос. Передайте книгу сказок папе, и пусть он намеренно рассказывает историю неправильно, смешно и нелепо. А вы со стороны наблюдайте, как ребёнок с удовольствием его поправляет и заливисто смеётся вместе с папой.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'Сила сообщества 💬', 'Мысль «Почему мой ребёнок такой упрямый?» не даёт вам покоя. Загляните в Сообщество Anacan. Прочитав о похожих нелепых кризисах, которые случаются дома у других мам, вы поймёте, что не одиноки и идёте совершенно нормальным путём.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'Маленький бизнесмен 🍅', 'Ребёнок собрал игрушки в углу комнаты и продаёт вам воображаемые помидоры за воображаемые деньги. Отнеситесь к этой игре в торговлю очень серьёзно. Купите воображаемый помидор и сделайте вид, будто едите его с аппетитом. Ролевые игры закладывают прочнейшую основу социального интеллекта и математического мышления.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'Кальциевая защита 🦴', 'Быстро растущим костям необходим кальций. Ребёнок не пьёт молоко? Обязательно воспользуйтесь инструментом контроля питания и подсчитайте, сколько сыра, йогурта или брокколи он съел сегодня.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'Побег из кровати 🏃‍♂️', '«Дай воды», «Найди мою игрушку»... В 3 года отговоркам, позволяющим не засыпать, нет конца. Включите таймер сна и твёрдо соблюдайте установленные границы.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'Огромная ноша 🎒', 'Ребёнок непременно хочет сам нести ваши тяжёлые сумки или большой зонт: тащит их по земле, но категорически отказывается от помощи. Позвольте ему испытать свои силы — он хочет почувствовать себя самым сильным героем в доме. Не мешайте его самостоятельности.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'Новая личность 🕷️', 'Утром ребёнок просыпается и совершенно серьёзно заявляет вам: «Я не ребёнок, я паук». Ближе к 40-му месяцу воображение выходит за любые рамки. Не спорьте: предложите ему роль паука, который завтракает, и присоединитесь к этому театру абсурда.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'Бесконечные отговорки 🦶', 'Уже почти уснув, ребёнок пытается встать с кровати под предлогом: «У меня палец на ноге чешется». Он уже овладел искусством откладывать сон. Будьте серьёзны: понарошку почешите ему ногу и решительно выключите свет. Границы устанавливаете вы.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'Условие с папиной шапкой 🧢', 'Ребёнок требует, чтобы перед его отходом ко сну папа обязательно надел зимнюю шапку. Пусть папа наденет её и начнёт издавать смешные звуки. Эта вечерняя нелепость не только рассмешит вас перед сном, но и мгновенно смягчит упрямство ребёнка.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'Упрямство, бросающее вызов физике 💧', 'Ребёнок рыдает, требуя «сухую воду»? Требуя невозможного, детский мозг на самом деле проверяет вашу решимость. Не ищите логики в происходящем — просто мгновенно переключите его внимание на другой яркий предмет.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'Список в вашем кармане 🛒', 'В повседневной суете закончился шампунь или влажные салфетки? Не пытайтесь удержать всё в голове — сразу добавьте это в список покупок и синхронизируйте его с партнёром.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'Потребность в тишине 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума с помощью шумомера и убавьте громкость телевизора в соседней комнате.'),
  ('602f2986-8e86-421e-ab71-94038d048ccf', 'Говорит как адвокат 🗣️', 'Малыш уже пытается торговаться с вами с помощью слов? Говорит: «Я ещё немного поиграю, а потом лягу спать»? Его речь прекрасно развивается, но не забывайте сохранять свои границы.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'Пазлы и логика 🧩', 'Малыш пытается собирать пазлы из 5-6 деталей? Так он осваивает геометрию и логику. Не мешайте этим повторяющимся, но полезным для обучения действиям.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'Поддержка папы 🫂', 'Обязательно по очереди вставайте к малышу по ночам. Иногда в темноте именно ритмичные поглаживания и запах папы мгновенно успокаивают ребёнка.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'Требование синего яблока 🍏', 'Едва открыв глаза, малыш с криком требует у вас синее яблоко. Не нужно объяснять, что такого в природе не бывает, и устраивать урок физики или биологии. Ответьте на его абсурдную логику столь же абсурдно, но действенно: «Синие яблоки ещё спят, давай разбудим красное».'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'Одеяльная одержимость 🛏️', 'Малыш уже почти уснул, но вдруг начинает плакать: «Одеяло касается моей левой ноги!» Внутренне улыбнитесь этой новой причуде трёх с половиной лет, придуманной, чтобы оттянуть сон. Молча поправьте одеяло и решительно полностью выключите свет в комнате.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'Цена подозрительной тишины 💄', 'Итог внезапных 10 минут тишины дома: вы заходите в комнату и видите, что малыш разрисовал вашей любимой помадой и своё лицо, и зеркало. Сердиться уже поздно.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'Волшебные руки папы ✈️', 'После целого дня с малышом на руках ваши руки уже отваливаются, а он по-прежнему полон энергии и отказывается ложиться. Позовите папу на помощь. Когда он поднимает ребёнка в воздух и играет с ним в самолётик, комнату наполняет смех, а вся накопившаяся неуёмная энергия за считаные секунды сходит на нет.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'Испытание бордюром 🧱', 'По дороге в парк малыш упорно хочет идти не по обычной дорожке, а по самому узкому и высокому краю бордюра, словно канатоходец. Так развиваются крупная моторика и равновесие! Держите его за руку для безопасности и позвольте покорить эту маленькую, но очень важную для него вершину.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'Прогулка с невидимой собакой 🐕', 'Посреди комнаты малыш опускает руку, гладит невидимую собаку и разговаривает с ней. Это самая невинная фаза развития воображения. Спросите: «Как зовут собаку?» — и поставьте в углу комнаты воображаемую миску с водой, став второстепенным актёром в этом великолепном спектакле.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'Гардеробный бунт 🕶️', 'Малыш пришёл завтракать в солнечных очках и зимней шапке и категорически отказывается их снимать. Забудьте об эстетике и о том, что скажут люди. Свобода самостоятельно принимать и отстаивать решения — гораздо более важная психологическая основа, чем уместность наряда.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'Тишина в цифрах 🤫', 'От домашнего шума у вас уже звенит в ушах. Когда малыш наконец уснёт, включите шумомер. Наблюдать на экране, как уровень шума опускается до 0-10 децибел, — лучший наглядный успокаивающий массаж для мозга уставшей мамы.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'Спаситель муравья 🐜', 'В парке малыш со слезами преградил дорогу, чтобы спасти муравья от верной гибели под чьей-то ногой? Восхититесь его огромной и милосердной способностью к сопереживанию.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'Я в умной сказке 🪄', 'Ваши голосовые связки устали от чтения классических книг. Включите умные сказки. Сделайте своего ребёнка главным героем, добавьте на фон успокаивающие звуки леса и создайте необычный, не требующий никаких усилий гипнотический сеанс для засыпания.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'Тихое утешение сообщества 💬', 'Вас внезапно душит мысль: «Я уже никогда не стану прежней — свободной и беззаботной»? Зайдите в сообщество Anacan. Почитайте о том, что другие мамы тоже переживают эти тяжёлые, но совершенно естественные чувства и что это один из этапов материнства, — и найдите утешение.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'Тишина в шкафу 🚪', 'В доме внезапно стало тихо, и вы нашли малыша в шкафу, где он прятался и играл сам с собой. Так он ищет личное пространство. Не вытаскивайте его оттуда сразу: ему тоже хочется побыть одному вдали от шума и дать мозгу отдохнуть.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa'::uuid, 'Тихий гнев 😤', 'Когда малыш не получает желаемого, то вместо плача скрещивает руки, отворачивается к стене и дуется на вас. Это новый и очень важный этап эмоциональной саморегуляции. Не давите на него: через 3 минуты он вернётся с улыбкой, словно ничего не произошло.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'Мера золотой тишины 🤫', 'От домашнего шума уже звенит в ушах. Когда малыш наконец уснёт, включите Шумомер. Наблюдение за цифрами на экране, близкими к нулю, за этой цифровой тишиной — лучший визуальный массаж для мозга уставшей мамы.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'Открытие нового языка 🗣️', 'Малыш придумывает сложные и необычные слова вроде Летучки-бегучки и Горячо-холодно. Его словарный запас расширяется с невероятной скоростью. Обязательно записывайте эти забавные выдуманные слова в Трекере развития — пусть они сохранятся там как памятный архив.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'Необычный спутник 🥄', 'Собираясь в парк, малыш вместо машинок настаивает на том, чтобы взять с собой найденный на кухне половник. Не мешайте! Сегодня в парке этот половник станет самой необычной, но самой полезной игрушкой для копания в песке.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'Кошки боятся воды 🐈', 'Чтобы не идти в ванну, малыш говорит: «Я кошка, а кошки не купаются». Примите его роль и продолжите игру: «А эта кошка хочет поиграть с мыльными пузырями?» Вовлеките малыша и преодолевайте сопротивление с помощью воображения.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'Профессиональный торг 🛒', 'В магазине малыш уже не плачет из-за конфет, а торгуется: «Если мы это купим, я съем суп». Поздравляем, ваш маленький адвокат растёт! Чтобы ничего не забыть, держите Список покупок открытым и не отвлекайтесь, пока ведёте с ним переговоры.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', 'Период «Смотри на меня!» 👀', 'Малыш прыгает с дивана и повторяет одно и то же движение ровно 50 раз, каждый раз ожидая вашего одобрения. Оторвитесь от телефона. Он прыгает не ради самого движения, а ради того любящего блеска одобрения в ваших глазах.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'Молчаливый собеседник 📝', 'Вас никто не понимает, а домашние заботы ужасно утомляют? Отбросьте натянутые улыбки. Напишите в Дневнике настроения, насколько опустошённой вы чувствуете себя сегодня на самом деле. Каждое перенесённое на экран слово снимет с ваших плеч часть тяжёлого груза.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'Сон на полу 🥱', 'Малыш упорно отказывался от дневного сна, но в итоге свернулся калачиком и уснул на ковре среди игрушек. Не будите его, перенося в кровать. Пусть спокойно спит посреди комнаты, а вы отдохните 1 час.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'Разведка погоды ⛅', 'На улице светит солнце, но малыш хочет надеть зимнюю куртку. Не спорьте. Откройте инструмент Погода и одежда и покажите ему на экране значок ребёнка в лёгкой одежде. Уловка «Смотри, телефон говорит, что сегодня тепло» всегда отлично работает.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'Сценарий в его руках 🪄', 'Классические сказки больше не привлекают внимание малыша. Откройте Умные сказки и спросите: «Куда теперь отправится этот волшебный поезд?» Пусть он сам придумает странную и совершенно абсурдную концовку, погрузится в фантазии и уснёт.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'Приём у стоматолога 🦷', 'Малыш берёт щётку и с серьёзным видом хочет осмотреть ваши зубы. Откройте рот и подчинитесь этому забавному доктору. Ролевые игры — один из самых эффективных и увлекательных способов развивать личность и преодолевать страхи.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'Не мусор, а сокровище 🍬', 'Вы выбросили старую обёртку от шоколада, которую малыш хранил несколько дней, но не играл с ней, и теперь он устроил настоящий скандал? То, что для вас мусор, для него может быть ценной частью коллекции. Чтобы успокоить малыша, сразу переключите его внимание на более интересный предмет.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'Победа без шампанского 🥂', 'Малыш уснул. Даже если шампанского нет, налейте в бокалы горячий чай, чокнитесь с партнёром и скажите: «Мы и сегодня справились с этим бурным хаосом». Вы — непоколебимая и неутомимая команда.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'Брокколи-детектив 🥦', 'Малыш обнаружил в супе тот единственный зелёный овощ и теперь отказывается есть? В Плане питания найдите самые искусные способы отвлечь его внимание: смешивайте овощи с цветными макаронами или измельчайте их в пюре.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'Ремикс из слов 🗣️', 'Он соединяет слова «вода» и «молоко», придумывает несуществующие слова вроде «молоководы» и смеётся. Он создаёт ремиксы из своего словарного запаса! Смейтесь вместе с ним над этими языковыми играми — именно благодаря таким экспериментам его мозг исследует границы языка.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'Внезапный взрыв любви 🫂', 'Утром малыш просит вас уйти, а перед сном крепко обнимает за шею и говорит: «Я люблю тебя больше всего на свете». Вот он, парадокс материнства! Вдохните его тёплый запах и позвольте всей усталости дня раствориться без следа.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'Мама, уйди! 💔', 'Когда малыш не получает желаемого, он смотрит на вас и говорит: «Ты мне не нужна, уходи!» Не принимайте это близко к сердцу. Он ещё не умеет справляться со своим гневом. Не воспринимайте его слова на свой счёт. Скажите: «Я здесь, поговорим, когда ты успокоишься» — и дайте ему пространство, чтобы прожить свои эмоции.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'Адвокат в супермаркете 🛒', 'Вместо того чтобы падать на пол из-за конфет, малыш начинает торговаться: «Если мы это купим, дома я съем суп». Поздравляем, ваш маленький адвокат растёт! А чтобы ничего не забыть, держите список покупок открытым и не упускайте главную цель, пока ведёте с ним переговоры.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'Цунами в ванной 🌊', 'Купание в ванной — уже не просто способ стать чистым, а игра в создание маленького цунами. Пусть вода брызжет во все стороны. Её волшебный притягательный эффект поможет выплеснуть накопившуюся за день упрямую негативную энергию и смыть её в канализацию.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'Право мамы полениться 🍕', 'Сегодня вам хочется на всё кричать? Дома полный беспорядок? Забудьте об уборке и не включайте плиту. Закажите пиццу или что-нибудь максимально простое. Откажитесь от иллюзии идеальной мамы: ваше психологическое здоровье гораздо ценнее домашней еды.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'Я сам налью! 💧', 'Он непременно хочет сам налить воду из большого кувшина в маленький стакан. Вода разливается по столу, а оттуда — на пол. Но только посмотрите на эти маленькие ручки, которые берут тряпку и пытаются всё вытереть. Совершая ошибки, малыш учится ответственности, а этот хаос и есть развитие.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'Знакомство с маленькими ножницами ✂️', 'Малыш пытается резать бумагу безопасными пластиковыми ножницами для детей? Это отличное упражнение для мелкой моторики! Обязательно отметьте это в трекере развития.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', 'Посмотри на меня! 👀', 'Когда вы смотрите в телефон или заняты другим делом, малыш подходит и поворачивает ваше лицо к себе? Ему нужно ваше безраздельное внимание. Установите зрительный контакт и покажите, что вы его слушаете.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'Папина очередь 👨‍🍼', 'Не берите все ночные пробуждения на себя. Будите и партнёра: быть командой — значит делить ответственность поровну.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'Что приготовить? 🍲', 'Закончились идеи для меню прикорма? Не теряйтесь в интернете — находите новые вкусные блюда в разделе «Полезные рецепты».'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'Персональная сказка 🪄', 'Создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: «Храбрый малыш, раскрасивший мир волшебными ножницами».'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'Давай я помогу! 🧹', 'Когда вы складываете одежду, малыш пытается забрать её у вас? Он уже чувствует себя большим. Дайте ему небольшое полотенце и позвольте помочь.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'Я расскажу тебе секрет 🤫', 'Уже лёжа в постели и почти закрыв глаза, малыш внезапно говорит: «Мама, я расскажу тебе секрет», — пытаясь отогнать сон. В искусстве откладывать сон дети официально готовы защищать докторскую. Улыбнитесь, скажите: «Расскажешь свой секрет во сне» — и решительно выключите свет.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'Только крем из печенья 🍪', 'Малыш слизывает крем из круглого печенья, а сухие половинки складывает на краю стола? Поздравляем, теперь вы официально знакомы с пищевой философией ребёнка в 3.5 года. В разделе «Полезные рецепты» вы найдёте более разумные, но не менее весёлые перекусы, которые привлекут его внимание.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'Не пой! 🛑', 'Вы начали подпевать детской песенке, звучащей на фоне, а малыш тут же закричал: «Не пой!» Единственный солист в комнате — он, а ваши вокальные попытки лишают его сцены. Не обижайтесь и уступите сцену этому маленькому эгоисту.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'Массаж плеч от папы 💆‍♂️', 'Сегодня вы долго были на ногах: бегали за малышом, собирали с пола игрушки — и теперь спина отваливается. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — опора семьи, а опоре обязательно нужны отдых и восстановление.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'Я сам! 🛑', 'Он непременно хочет сам завязать шнурки, но у него не получается, он злится и при этом агрессивно отвергает вашу помощь. Сделайте глубокий вдох. Для его будущего сохранить самооценку важнее, чем не выбиться из графика. Подождите.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', 'Трагедия «Он на меня посмотрел!» 👀', 'В парке он начал рыдать лишь потому, что другой ребёнок на него посмотрел? Для малыша, который только открывает для себя социальные границы, даже чужой взгляд может восприниматься как вторжение. Обнимите его и отвлеките словами: «Он просто смотрел на твою красивую футболку».'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'Спокойствие с Умными сказками 🪄', 'Он бегает по комнате и отказывается ложиться в кровать. Приглушите свет. Создайте в Умных сказках увлекательную историю и прочитайте её.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'Выстраивание игрушек в ряд 🚗', 'Он с миллиметровой точностью выстроил все свои машинки от одного конца комнаты до другого и не позволяет сдвинуть ни одну из них. Так проявляется стремление к визуальному порядку. Молча наблюдайте со стороны за работой маленького архитектора и ничего не нарушайте.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'Быть молчаливым читателем в Сообществе 💬', 'Вы очень устали и не хотите никому ничего объяснять или делиться переживаниями. Зайдите в Сообщество Anacan и побудьте просто читателем. Увидеть, как другие мамы справляются с такими же абсурдными кризисами, — это самая действенная молчаливая терапия.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'Кризис из-за ложки неправильного размера 🥄', 'Вы подали суп с большой ложкой — и едва не началась революция. «Я хотел маленькую ложку!» Хотя еда осталась прежней, в его логике физический размер ложки меняет вкус блюда. Не спорьте, просто замените ложку и поберегите силы.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', 'Одержимость «Укрой меня!» 🛏️', 'Он уже почти заснул, но край одеяла приоткрылся — и малыш кричит: «Укрой меня!» Для него жизненно важно, чтобы края одеяла лежали идеально ровно. Расправьте одеяло так, словно его только что погладили, и про себя улыбнитесь этим забавным ритуалам перед сном.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'Любовь к пластырям 🩹', 'Он обнаружил на теле невидимую ранку и настойчиво требует, чтобы вы заклеили её пластырем. Дело не в физической боли, а в потребности во внимании и материнской нежности. Наклейте маленький пластырь и поцелуйте это место — поверьте, ваш день будет спасён.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'Визуальное наслаждение тишиной 🤫', 'Домашний хаос наконец закончился, и малыш уснул. Не спешите мыть посуду! Откройте шумомер и, глядя на абсолютную тишину в комнате (0-10 децибел), в течение 15 минут почувствуйте, как отдыхает ваш мозг и как эта зримая тишина вас исцеляет.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'Песочная архитектура 🏰', 'В песочнице в парке он вырыл такую глубокую яму, будто ищет сокровища. Весь перемазался. Но не прерывайте этот момент открытия. Заранее выбрав подходящую по погоде одежду, которую не жалко испачкать, вы сможете без стресса наблюдать за происходящим.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'Вечерняя тренировка — прыжки на папе 🤸‍♂️', 'Он не успел выплеснуть энергию и не хочет ложиться спать. Пусть папа ляжет на диван, а ребёнок попрыгает на нём. Забавные звуки, которые будет издавать папа, наполнят комнату смехом, а вся лишняя энергия иссякнет за считаные секунды.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'Мамина забота о себе 🥗', 'Чтобы накормить малыша, вы придумали 3 разных меню, а сами опять остались голодной? В разделе плана питания выберите не только для детей, но и для мам питательный обед, богатый железом и кальцием, который готовится за 10 минут, и напомните себе, что вы тоже важны.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'Игра «Ты кто?» 🎭', 'Утром он смотрит на вас с очень серьёзным выражением лица и говорит: «Ты кто? Где моя мама?» Это пик развития воображения! Включитесь в игру: измените голос и скажите: «Я соседка, твоя мама скоро придёт», — а затем продолжите этот великолепный спектакль.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'Искусство из туалетной бумаги 🧻', 'Несколько минут тишины... А войдя в комнату, вы видите, что весь рулон туалетной бумаги размотан и раскидан по дому! Вместо того чтобы злиться, соберите бумагу и вместе слепите из неё снеговика или мяч. Победите хаос не криком, а творчеством.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'Слова любви, прошептанные на ушко 💖', 'Весь день он сводил вас с ума и упрямился по любому поводу. Но сейчас он так невинно спит в своей кроватке... Лягте рядом и прошепчите ему на ушко, как сильно вы его любите и что хорошего он сделал сегодня. Даже во сне дети чувствуют любящий голос мамы.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'Открытие стиральной машины 🧺', 'Он сидит перед стиральной машиной и так сосредоточенно смотрит на крутящееся бельё, будто это мультфильм. Это совершенно бесплатное и успокаивающее развлечение. Не мешайте ему, а сами воспользуйтесь моментом и отдохните.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'Попытки сбежать от сказки 🏃‍♂️', 'Пока вы читаете сказку, он при каждой возможности вскакивает с кровати и бежит за очередной игрушкой. Сдаваться сну он не собирается. Внезапно понизьте голос и начните читать шёпотом. Чтобы вас услышать, ему придётся вернуться в кровать, прислушаться — и вскоре он уснёт.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'Я уже большой и буду пить кофе! ☕', 'Он тянется к вашей чашке и решительно заявляет: «Я уже большой и тоже буду пить кофе!» Просто ему хочется стать частью вашего мира. Налейте в его маленькую чашку немного молока с какао, скажите: «Смотри, это твой детский кофе» — и чокнитесь с ним чашками.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'Погода и тактика многослойной одежды ⛅', 'С приближением весны погода становится переменчивой: утром холодно, а днём тепло. Инструмент «Погода и одежда» напомнит вам о принципе многослойности. Когда в парке станет теплее, снимайте по одному слою — так малыш не вспотеет, а вы избежите лишнего стресса.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'Игра «Украденный нос» 👃', 'Вы говорите: «Я забрала твой нос!» — и показываете большой палец, а он действительно верит и начинает плакать! В 3.5 года воображение ребёнка ещё не всегда позволяет отличить реальность от иллюзии. Сразу скажите: «А вот и нет, я вернула его на место», поцелуйте малыша в нос и превратите эту маленькую травму в улыбку.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'Молчаливый обмен взглядами с партнёром 🥂', 'Ребёнок наконец уснул. Вы с партнёром сидите рядом на диване, и у вас нет сил даже разговаривать. Вы просто молча смотрите друг на друга и улыбаетесь. Этот безмолвный обмен взглядами — прекрасный способ сказать: «Мы отлично справляемся с этим хаосом».'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'Искусственный интеллект и внезапные капризы 🤖', 'Ещё вчера ребёнок был спокойным, а сегодня агрессивно реагирует на всё подряд? Не ищите в интернете пугающие причины. Спросите у Anacan AI о психологических причинах этого скачка развития (mental leap) и успокойтесь, получив ответ, подтверждённый педиатрами.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', '«Я это нашёл!» — малыш-собственник 🔑', 'Он поднимает с пола пульт или папины ключи и заявляет: «Я это нашёл, значит, это моё!» Для него найти — значит стать владельцем. Не отбирайте вещь силой. Скажите: «Спасибо, что нашёл это для меня», переключите его внимание на другую игрушку и спокойно заберите находку.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'Мини-спа в ванной 🛀', 'Сегодня вечером наберите ванну не только для него, но и для себя. Когда ребёнок уснёт, наполните ванну тёплой водой, добавьте немного пены и зажгите всего одну свечу. Заприте дверь и хотя бы на 15 минут выйдите из роли мамы, чтобы снова побыть собой.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'Попытка стать парикмахером ✂️', 'Вы заходите в комнату и видите, как он пытается ножницами подстричь куклу. Для каждой мамы такая сцена — настоящий кошмар. Не сердитесь, спокойно заберите ножницы и сохраните эту парикмахерскую попытку как забавный кадр в детской фотосессии.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'Верни песню! 🎶', 'Он хочет снова услышать песню, которая играла по радио и уже закончилась. Вы объясняете, что это был прямой эфир и песня закончилась. Но он плачет и требует: «Верни её!» Детский мозг ещё не понимает, как устроен прямой эфир. Чтобы отвлечь малыша, начните сами петь эту песню смешным, необычным голосом.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'Лишнее в списке покупок 🛒', 'Перед походом в магазин вы открыли список покупок, а малыш подошёл сзади, нажал на экран телефона и добавил туда череду непонятных букв и шоколад. Да, дети осваивают цифровой мир невероятно быстро!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'Чай в тишине ☕', 'Он выстроил игрушки в ряд посреди комнаты и играет самостоятельно. Пожалуйста, не тратьте этот момент на уборку! Сядьте на диван, выпейте горячий кофе или чай и хотя бы 10 минут ни о чём не думайте — просто насладитесь тишиной.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'Тактика таймера перед сном ⏱️', 'Когда приходит время ложиться спать, он внезапно хочет пить, просится в туалет или начинает прощаться со стеной? Установите таймер. Введите правило: «Когда прозвенит звонок, все ложатся спать». Так вы без споров положите конец бесконечным прощаниям и этой искусной манипуляции.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'Настоящий художник выбирает стену 🖍️', 'Несколько секунд тишины обернулись неприятным сюрпризом. Вы заходите в комнату и видите, что малыш нарисовал фломастером на стене настоящее произведение искусства. Сделайте глубокий вдох. Его мелкая моторика развивается, а стену всё равно можно отмыть. Обязательно сфотографируйте этот шедевр, чтобы однажды вместе посмеяться.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Сила сообщества Anacan 💬', 'Мысль «Почему мой ребёнок такой упрямый?» не даёт вам покоя. Загляните в сообщество Anacan. Прочитав о таких же абсурдных кризисах в домах других мам, вы поймёте, что не одиноки и всё происходящее — совершенно нормальная часть вашего пути.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'Мама смотрит в стену 🛋️', 'В комнате шумно, малыш стучит игрушками друг о друга, а вы просто смотрите на пустую стену, полностью отключившись (zoned out). Это защитный механизм вашего мозга. Не корите себя за эти 5 минут оцепенения — они нужны вам, чтобы снова вернуться к жизни.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'Шокирующие вопросы в общественных местах 😳', 'Он громко спросил в автобусе или магазине: «Почему у этой тёти такой большой нос?» Тот самый момент, когда хочется провалиться сквозь землю! Вместо того чтобы заставлять его замолчать и стыдить, сразу переключите его внимание на какой-нибудь яркий предмет и дипломатично выйдите из ситуации.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'Нелогичные папины условия 🎲', 'Вечером малыш бегает по дому, лишь бы не надевать пижаму. И тут папа предлагает абсурдную игру: «А сможешь надеть эту пижаму с закрытыми глазами?» И — бум! Ребёнок сам того не замечает, как оказывается в пижаме. Остаётся только аплодировать этим нелогичным, но действенным папиным играм.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', 'Ностальгия «Я малыш!» 🍼', 'Он вдруг начал ползать, плакать и говорить: «Я малыш, обними меня»? Иногда взросление пугает и детей, поэтому им хочется вернуться в безопасные младенческие времена. Несколько минут подержите его на руках и приласкайте, как тогда.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'Суп из грязи 🍲', 'В парке малыш смешивает воду с землёй, протягивает вам грязь и говорит: «Мама, я сварил тебе суп». Никакого отвращения! Поневоле сделайте вид, что едите этот суп как самое вкусное блюдо на свете.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'Цифровое наслаждение тишиной 🤫', 'Домашний хаос наконец закончился, и малыш уснул. Откройте шумомер и следите на экране за уровнем тишины в комнате (0-10 desibel). Вид этих близких к нулю цифр действует на мозг уставшей мамы как самый дорогой спа-сеанс в мире.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'Царапина на банане 🍌', 'Малыш заметил на очищенном банане крошечную, буквально миллиметровую царапину и кричит: «Он испорчен!» Детское стремление к визуальному совершенству порой доходит до безумия. Отрежьте эту часть ножом и завершите мини-драму словами: «Я его спасла!»'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'Миссия «Запереть дверь» 🚪', 'Малыш с особым удовольствием запирает изнутри двери всех комнат и оставляет вас снаружи. Представление о личном пространстве переживает революцию. Позаботьтесь о том, чтобы он не прищемил пальцы, но не мешайте без серьёзной причины этой игре в обозначение собственной территории.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'Разные голоса в сказке 🪄', 'Сегодня вечером включите «Умные сказки», но читайте текст разными голосами. Говорите за медведя низким голосом, а за птицу — тоненьким, устроив в комнате маленький театр. Это нарушит монотонность и мгновенно увлечёт ребёнка сказкой, а оттуда приведёт его ко сну.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'Открытия шёпотом в темноте 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо прошепчите малышу на ухо о том, что произошло за день, или о черте его характера, которая нравится вам больше всего. Шёпот — самый волшебный способ помочь мозгу забыть о шуме и подготовиться ко сну.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'Зонт в доме ☂️', 'На улице солнечно, но малыш хочет ходить по дому с раскрытым зонтом. Его воображение не желает считаться с реальными условиями. Если дома достаточно места, позвольте ему устроить под зонтом маленький лагерь. Не подавляйте детскую логику общественными нормами.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'Испытание словом «Нет» в магазине 🛒', 'Прямо посреди магазина малыш попросил конфету, вы сказали: «Нет», и он расплакался. Несмотря на осуждающие взгляды окружающих, вы не изменили своего решения. Вы прекрасная мама! А чтобы ничего не забыть и поскорее выйти, сверяйтесь со списком покупок.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'Беспричинное «Зачем ты назвала моё имя?» 😤', 'Вы всего лишь сказали: «Иди, еда готова», а малыш рассердился и заплакал: «Зачем ты назвала моё имя?» В этом возрасте эмоции настолько запутанны, что дети порой обижаются даже на пустом месте. Ничего не объясняйте — через 2 минуты он сам прибежит есть.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'Искусственный интеллект и странные фобии 🤖', 'Малыш вдруг начал бояться красной машинки, с которой всегда играл? Если необъяснимые фобии вас тревожат, закройте пугающие интернет-форумы. Спросите у Anacan AI о странностях воображения в 3.5 года и получите научно обоснованный, успокаивающий ответ.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'Посмотреть фильм вдвоём... 🎬', 'Ребёнок уснул! Наконец-то вы с партнёром устроились на диване, чтобы посмотреть фильм, но уже на 10-й минуте оба крепко заснули. Такова ваша реальность. Эта трогательная картина, где вы спите, прислонившись друг к другу, — настоящее воплощение командной работы.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'Крошки в постели 🍞', 'Утром вы открываете глаза и обнаруживаете, что вся постель усыпана крошками от крекеров. Оказывается, малыш рано утром сам организовал себе завтрак. Вместо того чтобы ругаться, сохраните этот пример самостоятельного решения проблемы как забавное воспоминание в «Трекере развития».'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'Утренние прятки 🙈', 'Вы опаздываете на работу или в детский сад, а малыш прячется за шторой и говорит: «Найди меня!» Даже если нервы на пределе, крик лишь затянет процесс. На 2 минуты включитесь в игру со словами: «Интересно, где же мой чудесный малыш?», найдите его и выведите из укрытия.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'Сортировка еды по цвету 🍅', 'Малыш сортирует еду в тарелке по цвету и форме, а всё зелёное отодвигает в сторону. Откройте план питания. Узнайте, как превратить овощи в незаметное пюре и спрятать их во вкусных соусах, чтобы тайно одержать победу в этой игре.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'Папины выдуманные истории 📖', 'Сегодня вечером пусть в комнате звучит не ваш голос. Передайте книгу сказок папе и предложите ему намеренно пересказывать историю наоборот — смешно и абсурдно. А сами наблюдайте, как ребёнок с удовольствием его поправляет и заливисто смеётся над папиными выдумками.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'Выплеснуть гнев в дневник настроения 📝', 'Никто дома не замечает, насколько вы устали? Дневник настроения — ваш самый молчаливый и надёжный собеседник. Запишите туда все мелочи, которые сегодня сводили вас с ума, и, глядя на экран, почувствуйте, как проясняется голова и улетают тревоги.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'Ходить по дому в шапке 🧢', 'Малыш хочет носить дома зимнюю шапку. Настаивает и не снимает её. Забудьте об общественных нормах. Чтобы не подавлять его творческое начало и свободу выбора, позвольте ему провести день в этом необычном и забавном образе. Если температура в комнате комфортная, пусть ходит в шапке.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', 'Ударное «Ты меня не слышишь!» 😠', 'Пока вы смотрите в телефон или помешиваете еду, малыш подходит, поворачивает ваше лицо к себе и говорит: «Посмотри на меня!» И он прав. Ему нужно не просто ваше физическое присутствие, а безраздельное внимание. Отложите дела и всего 3 минуты слушайте его, не отводя глаз.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'Попытки познакомиться в парке 🤝', 'В парке малыш подходит к незнакомому ребёнку и представляется: «Меня зовут...» Социальные навыки формируются с удивительной скоростью. Сохраните эти смелые попытки общения в трекере развития как повод гордиться становлением его личности.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'Упрямый этап «Нет» 🛑', '«Хочешь воды?» — «Нет!» Но уже через 5 секунд малыш плачет и просит воду. Сейчас он проверяет последствия своих решений. Дети говорят «нет» даже тому, чего на самом деле хотят. Поставьте воду на стол и не заставляйте: закончив внутреннюю борьбу, малыш сам попьёт.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'Лёгкое засыпание с умными сказками 🪄', 'Вы уже выучили классические книги наизусть. Откройте умные сказки, сделайте главным героем своего ребёнка, а местом, которое предстоит покорить, — его комнату. Создайте необычный аудиосеанс для засыпания, который не потребует от вас никаких усилий, и отдохните сами.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'Театр теней в тёмной комнате 🐰', 'Малыш убегает из кровати, говоря, что боится темноты. Выключите в комнате весь свет, включите фонарик и покажите на стене тени птицы и собаки, сложив руки нужным образом. Темнота, которой он боялся, за считаные секунды превратится для него в театр.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'Сохраняем тишину с помощью шумомера 🤫', 'От домашнего шума у вас уже звенит в ушах. Когда малыш наконец уснёт, включите шумомер. Наблюдать за близкими к нулю показателями на экране, за этой цифровой тишиной, — лучший визуальный массаж для мозга уставшей мамы.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', 'Диктатура «Не садись!» 🪑', 'Вы хотите сесть на диван, но малыш подбегает и говорит: «Там будет сидеть мой мишка, встань!» Он пытается управлять всем домом. Не подавляя резко его волю, сохраните равновесие и мир в комнате словами: «Мишка сядет здесь, а я — рядом с ним».'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: Почему дети лгут? 🤥', '«Это не я разлил воду, это игрушка», — говорит малыш. Он лжёт или просто фантазирует? Не ищите пугающие ответы в интернете. Спросите Anacan AI, узнайте, что подобные фантазии ребёнка в 3.5 года — совершенно нормальный этап развития, и успокойтесь.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'Приступ смеха с партнёром 🥂', 'Ребёнок наконец уснул. Рассказывая партнёру об абсурдном случае, который весь день сводил вас с ума, вы вдруг оба начинаете хохотать. Да, этот смех — одна из самых приятных наград за родительство.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'Взять игрушки в ванну 🛀', 'Малыш не хочет купаться, но соглашается залезть в воду, только собрав в ванне все свои машинки и пластиковых мишек. Не мешайте ему. Эти игрушки в ванне — лучшие помощники, позволяющие ему расслабиться и ощутить успокаивающее действие воды.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'Любовь к макаронам 🍝', 'Сегодня малыш отказывается от мяса, которое любил ещё вчера, и весь день хочет есть только макароны. Не боритесь с его волей. Узнайте из полезных рецептов, как добавить к макаронам белковые продукты и овощи в виде незаметного соуса, и одержите победу.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'Танцы перед зеркалом 🪞', 'Малыш встаёт перед зеркалом, поёт песни и пробует разные танцевальные движения. Так он изучает ритм своего тела и наблюдает за тем, как выглядит! С радостью отметьте развитие осознания своего тела и чувства ритма в трекере развития.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'Колыбельный дуэт шёпотом 🌙', 'В кровати малыш так активен, что никак не может уснуть. Вместо того чтобы повышать голос, внезапно начните говорить тише и шёпотом запойте его любимую песню. Когда малыш сосредоточится, чтобы вас услышать, его мозг начнёт успокаиваться и постепенно переключится в режим сна.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'Расчёсывание — враг 🪮', 'Увидев расчёску, малыш с криком убегает из комнаты. Не вступайте в борьбу. Сначала дайте расчёску ему и позвольте причесать вас или куклу. Почувствовав, что контролирует ситуацию, малыш позволит вам поменяться ролями.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'Поддержка в сообществе Anacan 💬', 'Вас внезапно охватывает мысль: «Я уже никогда не стану прежней — свободной собой»? Поделитесь этим временным, но очень тяжёлым и глубоким переживанием с мамами в сообществе Anacan. Их опыт прохождения того же пути поможет вам получить утешение и поддержку.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'Водная терапия 🌊', 'Иногда ничего не помогает и малыш плачет буквально из-за всего. Посадите его в ванну с тёплой водой и добавьте немного пены. Волшебное расслабляющее действие воды мгновенно принесёт спокойствие и в комнату, и в его нервную систему.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'Время папиного массажа 💆‍♂️', 'Сегодня вы долго были на ногах, бегали за малышом и собирали игрушки с пола — теперь спина просто отваливается. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — опора дома, а опоре обязательно нужны отдых и восстановление.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'Гордость за футболку наизнанку 👕', 'Малыш надел футболку наизнанку и с гордостью демонстрирует её, словно покорил весь мир. Ребёнок, который выходит на люди в одежде наизнанку, умеет отстаивать собственные решения. Не вмешивайтесь ни на секунду — лучше восхититесь его уверенностью в себе.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'Проверка границ в магазине 🛒', 'У кассы в тележке обнаружились 3 разные шоколадки, которые вы не выбирали. Малыш проверяет ваши границы. Быстрым движением верните товары на место. А чтобы ничего не забыть, постоянно сверяйтесь со Списком покупок в приложении.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'Реальность остывшего кофе ☕', 'Налить кофе и спустя 3 часа выпить его ледяным — официальный закон материнства. Но сегодня сделайте исключение! Оставьте малыша наедине с любимым мультфильмом и выпейте кофе горячим. Вы не робот и имеете право на отдых.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'Цифровая тишина шумомера 🤫', 'Малыш наконец уснул! Вы не можете поверить в тишину, воцарившуюся дома. Включите шумомер и, глядя на показатель 0-10 децибел на экране, буквально ощутите, как ваш мозг понемногу восстанавливается.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'Я твоя мама! 👩‍👧', 'Игра со сменой ролей началась! Малыш командует вами: «Иди сюда, ложись в кровать, не плачь». С удовольствием поддержите этот лидерский опыт, молча исполняя роль его ребёнка. Такая игра развивает эмпатию.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'Операция «Скрытые витамины» 🥣', 'Ещё вчера малыш обожал это блюдо, а сегодня вы не можете уговорить его съесть ни кусочка. Не боритесь с его волей. Попробуйте полезные рецепты перекусов, в которых белковые продукты приобретают необычные, яркие и интересные формы, — и выйдите победителем.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'Моя игрушка заболела 🩺', 'Малыш берёт игрушечный стетоскоп, серьёзно осматривает плюшевого мишку и наклеивает ему пластырь. Через символическую игру он учится состраданию и осмысливает окружающий мир. Присоединитесь к игре, представившись пациентом в больнице.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'Мечты с умными сказками 🪄', 'Вы уже выучили классические книги наизусть. Откройте умные сказки, сделайте своего ребёнка главным героем, а его комнату — местом, которое предстоит покорить. Так вы создадите необычный аудиосеанс для засыпания, не требующий никаких усилий.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'Признания в дневнике настроения 📝', 'Вам кажется, что никто не замечает, как сильно вы устаёте дома? Дневник настроения — ваш самый тихий и надёжный собеседник. Запишите туда все детали, которые сегодня сводили вас с ума, и, глядя на экран, почувствуйте, как становится легче на душе, а тревоги улетучиваются.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'Погода и внезапные перемены ⛅', 'На улице непонятная погода: светит солнце, но при этом дует ветер? Пусть инструмент «Погода и одежда» мгновенно подскажет скорость ветра, которую не определить из окна, и подходящий комплект одежды. Так вы сможете выйти на прогулку без сомнений и не тратить время у двери.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'Нелогичные слёзы ☀️', 'Он рыдает, потому что солнце светит ему в глаза? Не ищите здесь логики. Для него это действительно глубокое огорчение: он злится, потому что не может управлять миром. Просто признайте его чувства, сказав: «Я задвинула штору и спрятала солнце».'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'Тоска по уединению 🚪', 'Шум буквально сверлит мозг, и вам хочется на всех кричать. Оставьте малыша в безопасном месте, зайдите в ванную и закройте дверь. Просто 5 минут смотрите на стену и ничего не делайте. Эта короткая пауза поможет вам восстановиться и вернуться к роли мамы.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'Правило босых ног 👣', 'Малышу нравится ходить босиком, ощущать ковёр, лежащие в комнате камешки или прохладную плитку. Стимуляция нервных окончаний на стопах очень важна для развития равновесия и нервной системы, поэтому, если малыш не мёрзнет, не мешайте ему ходить без носков.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'Папины странные звуки 🤡', 'Когда ваши приёмы уже не работают, странные звуки животных и смешные гримасы папы мгновенно спасают ситуацию. Во время вечерних кризисов сразу передавайте эстафету ему, а сами отдыхайте и наблюдайте со стороны.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'Сегодня готовлю я 🧑‍🍳', 'Когда вы раскатываете тесто, малыш обязательно подставляет стул и вмешивается в процесс? На самом деле он хочет не столько помочь, сколько оказаться в самом центре событий. Дайте ему маленький кусочек теста. На кухне будет беспорядок, зато его уверенность в себе и творческие способности будут расти.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'Записываем новые слова 📈', 'Малыш придумывает для предметов совершенно новые названия, которых нет ни в одном языке. И настойчиво требует, чтобы вы тоже использовали эти слова! Откройте трекер развития и обязательно сохраните эти забавные слова, чтобы однажды перечитать их и посмеяться.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'Подружиться с темнотой 🌙', 'Чтобы малышу было легче уснуть, за 1 час до сна выключите в комнате все дополнительные источники света и экраны планшетов. В тёмной обстановке без гаджетов мелатонин вырабатывается активнее, помогая организму перейти ко сну.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'Выключите свет и слушайте тишину 🤫', 'Он наконец уснул. Теперь вас тревожит даже самый тихий звук в доме. Приглушите свет, выключите телевизор и насладитесь этой редкой, восхитительной тишиной среди темноты. Так уходит усталость всего дня.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'Обиды без причины 😤', 'Вы просто сказали: «Иди, еда готова», а он скрестил руки, отвернулся к стене и обиделся на вас. В этом возрасте эмоции настолько запутанны, что дети порой обижаются буквально на пустом месте. Ничего не объясняйте — через 2 минуты он сам прибежит есть.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: Детские страхи 🤖', 'Малыш внезапно начал бояться красной машинки, с которой всегда играл? Если необъяснимые страхи вас тревожат, закройте пугающие форумы в интернете. Спросите у Anacan AI о причудах воображения в 3.5 года и получите научно обоснованный и успокаивающий ответ.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'Гипноз шёпотом 🌙', 'Малыш лежит в кровати, задирает ноги вверх и совершенно не хочет засыпать. Вместо крика внезапно понизьте голос и разговаривайте с ним только шёпотом. Когда ребёнок сосредоточится, чтобы вас расслышать, его мозг начнёт успокаиваться и постепенно переключится в режим сна.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'Отдых в сообществе Anacan 💬', 'Вы очень устали и не хотите никому ничего объяснять. Зайдите в сообщество Anacan и просто читайте. Когда вы видите, что другие мамы испытывают похожую усталость, появляется чувство «я не одна» — и это становится лучшей терапией.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'Шквал вопросов — Почему? 🌪️', 'Почему рыбы не ходят?, Куда ушло солнце? С самого утра мозг малыша ищет ответы на философские вопросы со скоростью 100 вопросов в час. Даже если вы устали, отвечайте коротко. Тайны Вселенной он открывает через ваш голос.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'Это моё! — Желание всем владеть 🧸', 'Малыш хватает любой случайный предмет в доме, прижимает его к себе и кричит: «Это моё!», не отдавая никому. Так он исследует границы собственности. Не обвиняйте его в эгоизме: переключите внимание на другую игру и заберите предмет.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'Порция для мамы 🥗', 'Вы придумали 3 разных блюда, чтобы накормить малыша, а сами снова остались голодны? В разделе с планом питания выберите не только детский вариант, но и питательный обед для мамы, богатый железом и кальцием, который можно приготовить за 10 минут. Позаботьтесь и о себе.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'Шампанское для двоих 🥂', 'После трудного дня налейте в бокалы обычный горячий чай. Сядьте с партнёром друг напротив друга на диване, скажите: «Мы пережили и этот хаос», — и чокнитесь бокалами. Вы одновременно и командиры, и одна команда.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'Хочу налить сам! 💧', 'Он непременно хочет сам перелить воду из большого кувшина в маленький стакан. Вода льётся на стол, а оттуда — на пол. Но посмотрите на его маленькие ручки, которые берут тряпку и пытаются всё вытереть. Он учится ответственности на своих ошибках — не сердитесь.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'Океан в ванне 🌊', 'Купание в ванне — уже не просто мытьё, а игра в создание волн. Пусть вода разлетается во все стороны. Её волшебное притяжение смоет всю накопившуюся за день упрямую, негативную энергию и унесёт её в канализацию.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'Список покупок — ничего не забыть 🛒', 'Идя в магазин, вы непременно забываете купить самое важное? Список покупок уже ждёт вас в приложении. Запишите туда всё необходимое, чтобы ваш партнёр точно купил нужное по дороге с работы, а вам не пришлось перегружать голову лишними заботами.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'Архитектура в парке 🏰', 'В парковой песочнице он роет такую глубокую яму, словно ищет сокровища. Весь перепачкался. Но не прерывайте этот момент открытия. Если заранее проверить погоду и выбрать одежду, которую не жалко испачкать, вы сможете спокойно наблюдать за этой картиной.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'Странная дружба с неодушевлёнными предметами 🗣️', 'Он совершенно серьёзно что-то рассказывает камню в парке или стулу дома и даже ругает их. Через символическую игру он осмысливает окружающий мир. Обязательно отмечайте такие необычные сценарии в трекере развития.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'Я в Умной сказке 🪄', 'Сегодня вечером назовите героя Умной сказки именем вашего ребёнка. Расскажите, как персонаж сказки тоже убрал свою комнату, а затем спокойно уснул. Так вы сможете привить ребёнку правила не криком, а мягко и ненавязчиво.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'Дневник настроения — время выдохнуть 📝', 'Возьмите телефон. Вместо того чтобы листать в соцсетях чужую жизнь, откройте Дневник настроения и сохраните на память самый забавный поступок ребёнка за сегодня. Такая цифровая терапия поможет расслабиться и вам.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'Верхом на папе 🐴', 'Он ещё не выплеснул всю энергию и отказывается ложиться. Позовите папу на помощь. Когда папа посадит ребёнка себе на спину и поскачет как лошадка, комнату наполнят раскаты смеха, а всё накопившееся физическое напряжение и неиссякаемая энергия за считаные секунды выйдут вместе с потом.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', 'Период «Посмотри на меня!» 👀', 'Он прыгает с дивана, повторяет одно и то же движение ровно 50 раз и каждый раз говорит: «Мама, посмотри на меня!» Оторвитесь от телефона. Он прыгает не ради самого движения, а ради искорки одобрения в ваших глазах. Подарите ему 5 минут безраздельного внимания, чтобы он им насытился.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', '0 децибел на шумомере 🤫', 'Он наконец уснул! Вы не можете поверить в тишину, окутавшую дом. Включите шумомер и, глядя на цифру 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает и как эта зримая тишина действует на вас подобно массажу.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'Свободный танец 🎶', 'Услышав любой ритм — в рекламе или даже в звуке автомобильного сигнала, — он тут же начинает танцевать. Посмотрите на жизнь так же радостно, как он! Присоединитесь к нему и несколько минут безудержно потанцуйте вместе — весь ваш стресс как рукой снимет.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'Трекер — гордость за развитие 📈', 'Он уже не малыш! Он полноценная личность со своими решениями, необычными вопросами и огромным сердцем. Вы прекрасно справляетесь!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'Границы на ковре 🗺️', 'Он придумал правило: из комнаты на кухню можно пройти, только наступая на красные линии ковра. Крупная моторика и внимание работают сообща. Не нарушайте это нелогичное правило: потанцуйте вместе с ним на линиях и заодно сделайте утреннюю зарядку.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'Театр под подушкой 🎪', 'Он лёг в кровать, но спрятал голову под подушку и разговаривает сам с собой. Полностью затемните комнату. Не вмешивайтесь: пусть в своём тёмном, безопасном убежище он разыгрывает придуманные истории и постепенно погружается в мир сна.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'Испытание макарониной в кармане 🍝', 'В кармане брюк, которые вы собирались положить в стиральную машину, нашлась засохшая макаронина? Для вас это мусор, а для него, возможно, запас на случай: «Вдруг я проголодаюсь по дороге». Не ругайте его. Отметьте эти первые проблески умения планировать в трекере развития как забавное воспоминание.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', 'Требование «Высуши воду!» 💧', 'Вместо того чтобы выпить воду из стакана, он кричит: «Она слишком мокрая, высуши её!» Добро пожаловать в абсурдный мир 3.5-летнего ребёнка. Попытки что-то объяснить лишь отнимут у вас силы. Скажите: «Хорошо, принесу другую, сухую воду» — и подайте ту же воду в стакане другого цвета.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', '«Я нашёл это в магазине» 🛒', 'У кассы в тележке обнаруживается пачка печенья, которую вы туда не клали. Малыш незаметно провёл свою разведку. Откройте список покупок и скажите: «Смотри, этого нет в нашем списке. Запишем в следующий раз», — переложив ответственность за правило на цифровой авторитет.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'Чаепитие наедине 🥂', 'После трудного дня налейте в стаканы обычный горячий чай. Сядьте с партнёром друг напротив друга на диване, чокнитесь стаканами и скажите: «Сегодня мы пережили и этот хаос. Мы отличная команда». Вы — нерушимый фундамент семьи.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'Операция «Спрятанные овощи» 🥦', 'Малыш находит в супе единственную крупинку или кусочек моркови и говорит: «Я это не ем». Откройте план питания. Узнайте, как превратить белковые продукты и овощи в разноцветные кексы, и перехитрите мозг этого упрямого поварёнка.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'Олимпиада по лазанию по мебели 🧗‍♂️', 'Малыш карабкается по краю дивана к окну. Для вас дом полон опасностей, а для него это спортзал. Вместо того чтобы сеять панику словами: «Осторожно, упадёшь!», направьте его потребность в движении, спокойно подсказав: «Поставь руку сюда».'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'Искусственный интеллект и спокойствие 🤖', 'Внезапное заикание или приступы гнева у ребёнка заставили вас искать в интернете страшные заболевания? Остановитесь! Спросите у Anacan AI, не связано ли это со скачком развития в 3 года, и получите успокаивающий ответ, подтверждённый педиатрами.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'Звуковые эффекты в комнате 🪄', 'Включите умные сказки. Читая историю, устройте в комнате звуковой театр: изобразите скрип двери, шум ветра и шёпот. Эти необычные звуки мгновенно перенесут внимание малыша в сказку, а оттуда — в глубокий сон.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'Побег от тени 👻', 'Во время прогулки малыш внезапно испугался своей тени и спрятался за вами. Не ищите логики — так работает воображение в 3.5 года. Скажите: «Давай прыгнем на тень!» — и сразу превратите пугающий объект в активную игру.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'Массаж плеч от папы 💆‍♂️', 'Сегодня вы долго были на ногах: бегали за малышом и собирали игрушки с пола, так что спина уже отваливается. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — двигатель семьи, а двигателю обязательно нужны отдых и восстановление.'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', 'Он сказал: «Ты плохая мама!» 💔', 'Малыш произнёс эту фразу, потому что вы не купили желанную машинку. У вас сжалось сердце. Но помните: он ещё не умеет правильно выражать эмоции и на самом деле хочет сказать: «Я разочарован». Просто обнимите его и примите его чувства.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'Чувство стиля 👗', 'Малыш хочет пойти в парк в летних сандалиях, надетых поверх зимних носков. Настаивает и не снимает. Забудьте об общественных нормах. Чтобы не подавлять его творческое начало, позвольте ему провести день в этом необычном и забавном образе — так он учится свободе.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'Соперник в зеркале 🪞', 'Малыш стоит перед зеркалом, хмурится и строит сердитые и забавные гримасы. Он проверяет, как разные эмоции отражаются на лице. Не издавая ни звука, с удовольствием наблюдайте со стороны за репетицией этого маленького театрального актёра.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'Мамин час уединения 🚪', 'От шума у вас раскалывается голова и хочется на всех кричать. Оставьте малыша в безопасном месте, зайдите в туалет и закройте дверь. Откройте дневник настроения и свободно опишите в нём всё своё истощение. Эта короткая терапия поможет вам перезагрузиться.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'Подружиться с темнотой 🐰', 'Малыш убегает из кровати, оправдываясь тем, что боится темноты. Выключите в комнате весь свет, включите фонарик и руками создавайте на стене тени птицы и собаки. Темнота, которой он боялся, за считаные секунды превратится для него в театр.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'Тактика погодной разведки ⛅', 'На улице солнечно, но дует ветер. Не позволяйте виду из окна ввести вас в заблуждение. Пусть инструмент погоды и подбора одежды сразу подскажет вам ощущаемую температуру и правильное сочетание слоёв, чтобы вы не теряли время в раздумьях у двери и отправились на полезную прогулку.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'Это не моя вина! 🤷‍♂️', 'Малыш нарочно разлил воду на пол, но свалил вину на игрушку, сказав: «Это она толкнула». Это не ложь, а защитный механизм детского мозга. Не спорьте. Скажите: «Давай и эту игрушку научим убирать за собой», — и мягко перехитрите его мозг.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'Океанский шторм в ванной 🌊', 'Купание в ванной — уже не просто гигиена, а игра в маленькое цунами. Пусть вода разбрызгивается вокруг. Её волшебный эффект, притягивающий и забирающий энергию, смоет всю накопившуюся за день упрямую негативную энергию малыша и унесёт её в канализацию.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'Тайный папин подкуп 🤫', 'Малыш не хочет чистить зубы. Папа незаметно подходит и говорит: «Если почистишь зубы, я покажу тебе волшебный камень, который лежит у меня в кармане». Иногда мамины правила стоит нарушать ради таких хитрых, необычных, но мгновенно срабатывающих папиных игр.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'Общение с балкона 👀', 'Малыш выходит на балкон, кричит и машет рукой каждому прохожему, а когда ему не отвечают — обижается. Потребность в общении сейчас на пике. Не затаскивайте его сразу домой. Скажите: «Они очень далеко и, возможно, тебя не услышали», — так вы проявите бережность к его чувствам и поддержите способность к эмпатии.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'Сеанс тихого чтения 📖', 'Сегодня вечером никто не разговаривает. Откройте умные сказки и вместо чтения вслух молча рассматривайте картинки под нежные звуки природы, доносящиеся из устройства. Зрительная память утомит малыша и поможет ему незаметно погрузиться в сон.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'Яйцо разрезали не так 🍳', 'Разрезанное пополам варёное яйцо становится причиной большой истерики. «Я хотел целое!» Внешний вид еды — одно из самых чувствительных мест для малышей. Изучайте полезные рецепты, чтобы научиться подавать продукты в подходящей форме и делать забавную нарезку.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'Юный детектив на природе 🔍', 'В парке малыш 20 минут неподвижно просидел, просто наблюдая за муравейником. Не торопите его. Если вы заранее проверили погоду с помощью помощника по погоде и одежде и тепло одели малыша, позвольте этому маленькому биологу исследовать мир.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'Мини-лаборатория в ванне 🛀', 'Малыш добавляет в воду мыло разных цветов и готовит волшебное зелье. Да, вся ванная будет залита водой. Зато он узнаёт, как растворяются и смешиваются разные вещества. Такие научные эксперименты помогают снять накопившееся за день напряжение и спокойно подготовиться ко сну.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'Уединение в шкафу 🚪', 'Посреди дома внезапно стало тихо. Вы нашли малыша играющим в одиночестве в тёмном платяном шкафу. Это не депрессия, а всего лишь момент эмоциональной перезагрузки. Слегка прикройте дверцу и позвольте ему насладиться роскошью личного пространства.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'Бунт против прикосновений 🔋', 'Вы физически истощены из-за малыша, который весь день карабкается по вам и тянет вас за волосы. Оставьте его в безопасном месте и ненадолго выйдите в другую комнату. Напишите в дневнике настроения: «Моё тело словно мне не принадлежит», — чтобы снять психологическое напряжение, вызванное синдромом touched out.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'Внутренний покой с шумомером 🤫', 'Наконец-то малыш уснул. Но звон в ушах всё ещё не проходит. Откройте в приложении шумомер. Смотрите на надпись «0 децибел» на экране и почувствуйте, как тишина в комнате проникает в ваш разум и восстанавливает вас.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'Похититель телефона 📱', 'Наливая себе чай, вы обнаружили, что телефон исчез, а малыш прячется за диваном и, подражая вам, говорит: «Алло». Он внимательно изучает ваши цифровые привычки. Забирая устройство, скажите в игровой форме: «Оказывается, мой телефон тоже хочет с тобой поговорить».'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'Политика «Одевай меня сам!» 👖', 'Малыш поднимает ноги вверх и говорит: «Я маленький, одень меня». Дети постоянно колеблются между самостоятельностью и зависимостью. Не одевайте его силой. Положите одежду рядом и немного схитрите: «Эти штаны супергероя ждут своего владельца».'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'Мистическая сила шёпота 🌙', 'Малыш придумывает отговорки, лишь бы не ложиться спать. Говорите как можно тише, только шёпотом. Чтобы понять вас, ему придётся сосредоточить всё внимание, и такая концентрация успокоит его мозг и поможет заснуть.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'Поддержка в сообществе Anacan 💬', 'Вас угнетает мысль: «Я никогда не стану идеальной»? Избавьтесь от иллюзии идеальных мам из Instagram. Зайдите в сообщество Anacan, прочитайте искренние признания мам, у которых дома полный беспорядок, а дети рисуют на стенах, и скажите себе: «Со мной всё совершенно нормально».'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'Логика динозавра 🦖', 'Утром малыш не отвечает ни на один вопрос, а только рычит. Сегодня он тираннозавр. Подстройтесь под придуманного им персонажа и спросите: «А тираннозавры едят кашу?» — так вы завершите утренний ритуал без единой слезинки.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'Выдуманные папины герои 🦸‍♂️', 'Сегодня вечером забудьте о сказках из книг. Пусть папа сочинит фантастическую историю, главным героем которой станет сам малыш. Фразы вроде «И тогда он достал свой меч и... почистил зубы!» рассмешат малыша и помогут подготовить его ко сну.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'Критика собственного рисунка 🖍️', 'Малыш показывает свои чёрные каракули, говорит: «Это был ты, но получилось плохо», — а затем рвёт рисунок. У него начинает развиваться способность критически оценивать свою работу! Не обесценивайте его чувства. Поддержите развитие, сказав: «Может быть, в следующем рисунке попробуешь добавить красный цвет?»'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', '«Не пой!» 🛑', 'Вы начали подпевать детской песенке, игравшей на фоне, а малыш тут же закричал: «Не пой!» Единственный солист в комнате — он, а ваши вокальные попытки отнимают у него сцену. Не обижайтесь, уступите сцену этому маленькому эгоисту.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'Я в умной сказке 🪄', 'Сегодня вечером в «Умных сказках» назовите главного героя именем вашего малыша. Расскажите, что персонаж сказки тоже убрал свою комнату, а потом спокойно уснул. Так вы сможете привить малышу правила не криком, а мягко и ненавязчиво.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'Режим сбился? ⏱️', 'Вечернее укладывание слишком затягивается? Посмотрите график таймера сна. Возможно, уже пришло время полностью отказаться от дневного сна и укладывать малыша вечером пораньше.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'Критик мультфильмов 📺', 'Малыш пересказывает вам просмотренный мультфильм на своём языке и серьёзно объясняет, кто куда пошёл. Слушайте его внимательно и с удивлением. Пусть его воображение разыграется, а сам он почувствует себя самым умным на свете.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'Молчаливая поддержка сообщества 💬', 'Вы очень устали и не хотите никому ничего объяснять или делиться переживаниями. Зайдите в Сообщество Anacan и просто почитайте. Увидеть, как другие мамы справляются с такими же абсурдными кризисами, — порой самое сильное молчаливое утешение.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'Побег из кровати 🏃‍♂️', '«Дай воды», «Найди мою игрушку»... У трёхлетки не заканчиваются отговорки, лишь бы не засыпать. Включите таймер сна, уверенно соблюдайте установленные границы и создайте спокойную атмосферу в комнате с помощью Белого шума.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'Маленький сказитель 🗣️', 'Малыш уже соединяет слова и придумывает воображаемые истории и фантастические сюжеты? Не упустите этот потрясающий речевой скачок: сразу сделайте аудиозапись и сохраните её навсегда в Альбоме малыша.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'Кальциевый щит 🦴', 'Кальций необходим быстро растущим костям. Малыш не пьёт молоко? С помощью трекера питания обязательно подсчитайте, сколько сыра, йогурта или брокколи он съел сегодня.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'Период «Это моё!» 🧸', 'Малыш никому не даёт свою игрушку? Это не эгоизм, а закономерный этап развития. Почитайте в Блогах о том, как научить его не делиться, а играть по очереди, и примените эти советы на практике.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'Утренняя революция 🛑', 'Малыш сегодня с отвращением отвергает еду, которую ещё вчера обожал? Это не отсутствие аппетита, а всего лишь попытка взять ситуацию под контроль. Обсудите с Anacan AI, как сохранять спокойствие во время кризисов, глубоко вдохните и никогда не устраивайте битву за столом.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'Папина площадка 👨‍👧', 'Материнство — это не круглосуточное дежурство. Подключайте партнёра! Пусть сегодня малыш выплеснет свою нескончаемую энергию с папой в парке, а вы насладитесь дома абсолютной тишиной.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'Мамина передышка ☕', 'Постоянно разговаривать с малышом и отвечать на вопросы утомительно. Найдите в разделе «Места для мам» кафе с детским уголком, выпейте горячий кофе, поделитесь переживаниями с другими мамами и немного передохните.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'Папина очередь читать сказку 📚', 'Сегодня вечерний ритуал укладывания полностью поручите папе. Пусть он читает сказку, а вы тем временем насладитесь абсолютной тишиной за дверью.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', '«Я сам!» 🛑', 'Малыш хочет всё делать сам и втрое растягивает процесс одевания? Смотрите не на беспорядок, а на растущую уверенность в себе. Когда терпение будет на исходе, почитайте в Блогах, как справляться с кризисами с помощью игры, и глубоко вдохните.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'Горячий чай и тишина 🍵', 'Таймер остановился, малыш уснул. Забудьте о домашних делах — всё может подождать. Приготовьте интересный напиток по одному из полезных рецептов и насладитесь временем наедине с собой.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'Утренние прятки 🙈', 'Вы опаздываете на работу или в детский сад, а малыш спрятался за занавеской и говорит: «Найди меня!» Как бы вы ни нервничали, крик лишь ещё больше затянет процесс. На 2 минуты включитесь в игру со словами: «Интересно, где же мой славный малыш?» — найдите его и выведите из укрытия.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'Крик тела 🩸', 'Не поддавайтесь беспричинной раздражительности и усталости. Загляните в Трекер менструации — ваше тело подаёт сигнал. Вместо того чтобы винить себя, отдохните и перекусите чем-нибудь богатым магнием из раздела Полезных рецептов.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'Утренняя философия 🤔', 'Почему птицы не падают? Почему дерево стало зелёным? Ранним утром научная конференция объявляется открытой. Если вы устали давать точные объяснения, спросите: «А как ты думаешь, почему?» — и послушайте эти удивительные выдуманные ответы.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'Договор с таймером перед сном ⏱️', 'Как только приходит время спать, малыш внезапно хочет пить, просится в туалет или начинает прощаться со стеной. Поставьте таймер. Введите правило: когда прозвенит будильник, все выключают свет. Так вы терпеливо положите конец бесконечным прощаниям и умелым манипуляциям.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'Кризис «Хочу!» в магазине 🛒', 'Малыш кричит у кассы, требуя сладости? Не обращайте внимания на осуждающие взгляды окружающих. Спокойно установите зрительный контакт, объясните правило и стойте на своём. Если этого нет в вашем списке, вы это не купите.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'Игра «Ты кто?» 🎭', 'Малыш смотрит на вас с очень серьёзным выражением лица и спрашивает: «Ты кто? Где моя мама?» Он играет с вами в актёров! Скажите: «Я соседка, твоя мама скоро придёт», измените голос и продолжайте этот великолепный спектакль.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'Внезапное «Я тебя люблю» 💖', 'Играя посреди комнаты, малыш внезапно смотрит на вас, подбегает и обнимает за шею. Ради этого стоили все бессонные ночи и усталость! Насладитесь глубоким, неповторимым умиротворением этого мгновения — и весь хаос тут же забудется.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'Не мусор, а искусство 🎨', 'Посреди комнаты малыш создал огромное произведение искусства из обрезков бумаги и ниток и не разрешает вам его выбросить. Отложите стремление к идеальной чистоте. Уважайте созданный им хаос — уборка может подождать до завтра.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'Умиротворение тишины 🤫', 'Малыш наконец уснул! Вы не можете поверить в тишину, окутавшую дом. Включите шумомер и, глядя на цифру 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает и как эта зримая тишина словно делает вам массаж.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'Закончите незавершённую фразу 🗣️', 'Забыв слово, малыш жестикулирует, хмурит брови и ждёт, пока вы догадаетесь. Его словарный запас растёт, просто мозг пока работает быстрее речи. Терпеливо закончите фразу и полюбуйтесь облегчением на его лице: «Да, именно это я и хотел сказать».'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'Игра на папиной спине 🐴', 'Малыш не успел выплеснуть всю энергию и отказывается ложиться. Позовите папу на помощь. Когда папа посадит ребёнка на спину и поскачет, словно лошадка, комнату наполнят раскаты смеха, а накопившееся физическое напряжение и неуёмная энергия исчезнут за считаные секунды вместе с потом.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'Энергетический батончик для мамы 🥑', 'Вы составили для малыша меню в 4 разных вариантах, но что поели сами? Выберите в Полезных рецептах особый богатый кальцием перекус, который готовится за 5 минут, и насладитесь им, даже если придётся есть стоя. Вы — двигатель этого дома, и вам нужно подзарядиться.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'Пробуждение в образе котёнка 🐾', 'Сегодня утром малыш — вовсе не человек. Он ходит на четвереньках, трётся о ваши ноги и общается исключительно мяуканьем. Это самое милое проявление воображения. Вместо того чтобы устанавливать правила, протяните ему воображаемую миску молока и насладитесь этой игрой.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'Музыкальный гипноз 🎶', 'Начались вечерние беспричинные бури и приступы плача. Выключите телевизор, приглушите свет и включите в комнате очень тихую классическую музыку. Её глубокое звучание волшебным образом изменит атмосферу и принесёт в комнату умиротворение.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'Завтрак, которым не делятся 🍳', 'Малыш ни за что не делится с вами едой из своей тарелки, но настойчиво требует яйцо из вашей. Дети всегда полностью доверяют выбору родителей. Не сопротивляйтесь: с любовью отдайте ему свой кусочек и улыбнитесь.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'Разговоры с неодушевлёнными предметами 🗣️', 'Малыш с совершенно серьёзным видом что-то рассказывает камню в парке или стулу дома и даже ругает их. Через символические игры он осмысливает окружающий мир. Обязательно отметьте эти особенные сценарии в Трекере развития — это признак высокой креативности!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'Признание в Дневнике настроения 📝', 'Возьмите телефон. Вместо того чтобы листать в социальных сетях чужую идеальную жизнь, откройте Дневник настроения и сохраните на будущее самый забавный поступок малыша за сегодня — момент, который рассмешил вас больше всего. Записывать это туда — самая настоящая терапия.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'Сортировка еды по цвету 🍅', 'Малыш сортирует еду на тарелке по цвету и форме, а всё зелёное отодвигает в сторону. Откройте план питания. Узнайте, как превратить овощи в незаметное пюре и спрятать их во вкусных соусах, чтобы незаметно выиграть в этой игре.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'Потребность в тишине 🤫', 'Малыш наконец уснул! Вы не можете поверить в воцарившуюся дома тишину. Включите шумомер и, глядя на цифру 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает, а эта зримая тишина словно делает вам массаж.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'Сокровища из карманов 🪨', 'Во время стирки вы нашли в кармане его брюк 2 камня, засохший лист и обломок веточки? То, что для вас мусор, для малыша — ценная коллекция, собранная во время исследования мира. Вместо того чтобы выбрасывать эти находки, сложите их в маленькую коробку с сокровищами.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'Миссия «Запереть дверь» 🚪', 'Малыш с особым удовольствием закрывает изнутри двери всех комнат, оставляя вас снаружи. Представление о личном пространстве переживает настоящую революцию. Примите меры, чтобы он не прищемил пальцы, но не мешайте всерьёз этой игре в обозначение собственной территории.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'Искусство из туалетной бумаги 🧻', 'Несколько минут тишины... А войдя в комнату, вы обнаруживаете, что вся туалетная бумага размотана и разбросана по дому! Вместо того чтобы сердиться, соберите её и вместе слепите снеговика или мяч. Победите хаос не криком, а творчеством.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'Исследование стиральной машины 🧺', 'Малыш сидит перед стиральной машиной и так сосредоточенно смотрит на вращающееся бельё, будто это мультфильм. Это совершенно бесплатное и успокаивающее развлечение. Не мешайте ему, а сами воспользуйтесь возможностью отдохнуть — хаос ненадолго взял паузу.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'Слова любви, прошептанные на ушко 💖', 'Весь день малыш сводил вас с ума и упрямился по любому поводу. Но сейчас он так невинно спит в своей кроватке... Лягте рядом и прошепчите ему на ушко, как сильно вы его любите и что хорошего он сегодня сделал. Даже во сне дети чувствуют наполненный любовью мамин голос.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', 'Ударное «Ты меня не слышишь!» 😠', 'Пока вы смотрите в телефон или помешиваете еду, малыш подходит и поворачивает ваше лицо к себе: «Посмотри на меня!» И он прав. Ему нужно не просто ваше физическое присутствие, а безраздельное внимание. Отложите дела и всего 3 минуты слушайте его, не отводя глаз.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'Попытки сбежать от сказки 🏃‍♂️', 'Пока вы читаете сказку, малыш при каждой возможности вскакивает с кровати и убегает под предлогом: «Принесу свою игрушку». Он не хочет сдаваться сну. Внезапно понизьте голос и начните читать шёпотом. Чтобы вас услышать, ему придётся вернуться в кровать и внимательно слушать.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'Погода и тактика многослойной одежды ⛅', 'Ближе к лету погода переменчива: утром холодно, а днём жарко. Инструмент погоды и одежды напомнит вам о принципе многослойности. Когда в парке станет теплее, снимайте с малыша по одному слою одежды, чтобы он не вспотел, а вы не нервничали.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'Искусственный интеллект и внезапные капризы 🤖', 'Ещё вчера ребёнок был спокойным, а сегодня агрессивно реагирует на всё? Не ищите в интернете пугающие причины. Спросите Anacan AI о психологических причинах этого скачка развития (mental leap) и избавьтесь от тревоги, получив ответ, одобренный педиатрами.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'Игра «Украденный нос» 👃', 'Вы говорите: «Я забрала твой нос!», показываете большой палец, а малыш верит и начинает плакать! В 3.5 года воображение иногда ещё не позволяет отличить реальность от иллюзии. Сразу скажите: «Ага, вернула!», поцелуйте его в носик и превратите эту маленькую травму в улыбку.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'Безмолвный обмен взглядами с партнёром 🥂', 'Ребёнок наконец уснул. Вы с партнёром сидите рядом на диване, и у вас нет сил даже разговаривать. Вы просто молча смотрите друг на друга и улыбаетесь. Этот безмолвный обмен взглядами — лучший способ сказать: «Мы прекрасно справляемся с этим хаосом».'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', '«Это нашёл я» — малыш-собственник 🔑', 'Подняв с пола пульт или папины ключи, малыш заявляет: «Это нашёл я, значит, это моё!» Для него найти означает завладеть. Не отбирайте вещь силой. Скажите: «Спасибо, что нашёл это для меня», переключите его внимание на другую игрушку и заберите находку.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'Концерт на кухне 🥄', 'Малыш достаёт кастрюли и деревянные ложки и устраивает концерт посреди кухни. Даже если у вас болит голова, помните: так развиваются его чувство ритма и творческие способности. Не спешите вмешиваться — позвольте волнам этой безумной энергии несколько минут разноситься по комнате.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'Мини-спа в ванной 🛀', 'Сегодня вечером устройте ванну не только малышу, но и себе. Когда ребёнок уснёт, наберите тёплую воду, добавьте немного пены и зажгите в ванной одну свечу. Заприте дверь и всего на 15 минут выйдите из роли мамы, снова став самой собой. Вы это заслужили.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'Признание в дневнике настроения', 'Возьмите телефон. Вместо того чтобы листать чужие жизни в социальных сетях, откройте Дневник настроения и запишите на память самый забавный поступок малыша за сегодня. Такая цифровая терапия поможет расслабиться и вам — взгляните на экран и почувствуйте, как тревоги улетучиваются.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'Верни песню! 🎶', 'Малыш хочет снова услышать песню, которая играла по радио и уже закончилась. Вы объясняете, что это был прямой эфир и песня закончилась. Но малыш плачет и требует: «Верни!» Детскому мозгу пока трудно понять логику прямого эфира. Чтобы отвлечь малыша, начните сами петь эту песню смешным, необычным голосом.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'Чай в тишине ☕', 'Малыш выстроил игрушки посреди комнаты и играет самостоятельно. Пожалуйста, не тратьте этот момент на уборку! Сядьте на диван, выпейте горячий кофе или чай и 10 минут просто наслаждайтесь тишиной, ни о чём не думая.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'Тактика таймера перед сном ⏱️', 'Когда приходит время ложиться спать, малыш внезапно хочет пить, просится в туалет или начинает прощаться со стеной? Установите таймер. Введите правило «когда звенит таймер, все ложатся спать» — так вы без споров завершите это бесконечное прощание и мягко пресечёте умелые попытки оттянуть сон.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Сила Сообщества Anacan 💬', 'Мысль «Почему мой ребёнок такой упрямый?» не даёт вам покоя. Загляните в Сообщество Anacan. Прочитав о похожих абсурдных кризисах в домах других мам, вы поймёте, что не одиноки и всё происходящее совершенно нормально.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'Настоящий художник выбирает стену 🖍️', 'Несколько секунд тишины обернулись неприятным сюрпризом. Вы входите в комнату и видите, что малыш нарисовал фломастером произведение искусства прямо на стене. Сделайте глубокий вдох. Его мелкая моторика развивается, а стену всё равно можно отмыть. Обязательно сфотографируйте этот шедевр, чтобы посмеяться над ним в будущем.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'Приглашение в темноту 🌙', 'Малыш беспокоится, когда в спальне выключают свет? Поставьте в углу комнаты небольшой ночник тёплого цвета — оранжевого или красного. При этом остальная часть комнаты должна оставаться полностью тёмной, чтобы поддерживать выработку мелатонина и глубокий сон.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'Попытка стать парикмахером ✂️', 'Войдя в комнату, вы видите, как малыш с ножницами в руках пытается подстричь куклу. Такой момент — страшный сон любой мамы. Спокойно заберите ножницы и сохраните эту парикмахерскую попытку в «Фотосессии малыша» как забавное воспоминание.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'Обязательная вылазка на природу ⛅', 'В четырёх стенах энергия малыша превращается в агрессию, а каждое предложение начинается со слова «нет». Независимо от погоды и одежды, подготовьтесь как следует и обязательно выведите его на улицу. Контакт с землёй поможет его нервной системе быстро перезагрузиться.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'Это моё! — Присваивание всего подряд 🧸', 'Малыш обнимает любой случайный предмет в доме, кричит: «Это моё!» — и никому его не отдаёт. Так он исследует границы собственности. Не обвиняйте его в эгоизме: переключите внимание на другую игру и заберите предмет.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'Не мусор, а искусство 🎨', 'Малыш создал посреди комнаты большое произведение искусства из мелких обрывков бумаги и нарезанных ниток и не разрешает вам его выбросить. Отложите стремление к идеальной чистоте. Уважайте созданный им хаос — уборка может подождать до завтра.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'Верхом на папе 🐴', 'Малыш не успел выплеснуть всю энергию и отказывается ложиться спать. Позовите папу на помощь. Когда папа посадит ребёнка себе на спину и поскачет, комнату наполнят взрывы смеха, а накопившееся физическое напряжение и неуёмная энергия исчезнут за считанные секунды вместе с капельками пота.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'Мир сказок 🪄', 'Отложите классические сказки. Откройте умные сказки. Создайте особенную сказку.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'Поддержка Сообщества 💬', 'Вы очень устали и не хотите никому ничего объяснять или делиться переживаниями. Зайдите в Сообщество Anacan и просто почитайте. Увидеть, как другие мамы справляются с такими же абсурдными кризисами, — самая сильная безмолвная поддержка.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'Утренний диктатор за работой 👑', '«Не садись туда, там будет сидеть мой мишка!» За завтраком малыш управляет всем столом. Не подавляя резко его волю, скажите: «Хорошо, пусть мишка сидит там, а я сяду здесь» — так вы сохраните равновесие и мир в комнате.'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'Бунт против дневного сна 🥱', 'Малыш не хочет ложиться и плачет? Не заставляйте его. Приглушите свет в комнате и объявите «тихий час для листания книг». Так вы создадите новый ритуал, который позволит вам обоим отдохнуть, пусть и по-разному.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'Пусть он сам напишет сценарий 🪄', 'Вам обоим надоели классические книги, и в комнате царит скучная атмосфера? Откройте «Умные сказки» и сегодня вечером позвольте малышу направлять сюжет. Спросите: «Куда теперь отправится эта летающая машина?» — и пусть он засыпает, покоряя мир в своём воображении.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'Соперник в зеркале 🪞', 'Стоит перед зеркалом, хмурится, изображает злость и строит странные гримасы? Так малыш проверяет, как разные эмоции выглядят на его лице. Не издавая ни звука, с удовольствием наблюдайте со стороны за репетицией этого маленького театрального актёра.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'Шёпот у стены 🤫', 'Лёг в кровать, отвернулся к стене и шёпотом делится с кем-то своими переживаниями? Как же это мило! Выключите свет, послушайте, как этот шёпот постепенно растворяется во сне, и отдохните.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'Скандал из-за не того стакана? 🥤', 'В комнате разразилась настоящая буря из-за того, что вы налили воду в жёлтый стакан? Не принимайте близко к сердцу — сегодня утром малыш просто проверяет границы. Сразу перелейте воду в синий стакан, восстановите мир и поберегите силы на остаток дня.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'Вражда с пылесосом 🌪️', 'Когда вы пылесосите, малыш плачет, преграждает вам путь и просит не убирать его пыль? Чувство собственности дошло до абсурда. Выключите пылесос и устройте 5-минутную церемонию прощания с пылью. Поверьте, так этот хаос закончится быстрее.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'Снова спор из-за одежды 🧥', 'Вы собираетесь на улицу, а малыш хочет надеть резиновые сапоги и футболку с коротким рукавом? Не спорьте. Откройте «Погоду и одежду» и покажите, что телефон не разрешает так одеваться. Переложите ответственность за правило на экран и отойдите в сторону — малыш спокойно наденет кофту.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'Мечта о чашке чая ☕', 'Вы так устали, что, пока малыш играл, тайком убежали на кухню и закрыли дверь? Вы имеете на это полное право. Откройте дневник настроения и напишите всего два слова: «Сегодня выжила». Иногда маме просто необходимы эти 5 минут передышки.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'Поймай облако, пусть не уходит! ☁️', 'Малыш смотрит в окно и плачет из-за того, что облако уплывает? Не тратьте время на научные объяснения о ветре. Скажите: «Оно отправилось поздороваться с другими детьми». Добавьте немного юмора и добрых выдумок в эту необычную детскую философию — и день будет спасён.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'Борьба с папой на диване 🤼‍♂️', 'Малыш убежал и спрятался, лишь бы не ложиться спать? Передайте эстафету папе. Пусть они понарошку поборются у стены. Эта шумная, активная игра с папой заберёт последние запасы упрямой энергии и поможет малышу сдаться сну.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'Устали от идеальных мам из интернета? 📵', 'Не расстраивайтесь, когда открываете Инстаграм и видите у всех идеальных детей! Закройте приложение и зайдите в Сообщество Anacan. Увидев, что в других домах такой же беспорядок, а дети шумят не меньше ваших, глубоко вдохните: вы не одна!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'Я сам это приготовлю! 🍳', 'Малыш непременно захотел сам взбить яйцо, и половина содержимого миски оказалась на столе? Позвольте ему насладиться своим гордым взглядом шеф-повара. Кухню всё равно придётся мыть, зато не стоит мешать развитию его самостоятельности и уверенности в себе.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c'::uuid, 'Тайный запас макарон 🍝', 'При стирке брюк вы нашли в кармане засохшую макаронину? Это не жадность, а детское стратегическое планирование. С серьёзным видом выбросьте её в мусор, но в душе улыбнитесь этому маленькому разведчику и хранителю запасов. Они растут!'),
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc', 'Цифра тишины на экране 🤫', 'Наконец-то малыш уснул. В доме стало так тихо, что звенит в ушах? Откройте в приложении шумомер. Надпись «0 децибел» станет лучшим в мире визуальным массажем для вашего уставшего от шума мозга.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'Бирка на кофте колется! 🏷️', 'Малыш отказывается надевать кофту, потому что маленькая бирка сзади колется, словно иголка? Сенсорная чувствительность в 3.5 года способна свести с ума. Не спорьте: возьмите ножницы, срежьте бирку под корень и за секунду завершите этот мини-кризис.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'Это был мой камень! 🪨', 'Малыш рыдает из-за того, что вы выбросили грязный камень, принесённый из парка? Оказывается, это был его лучший друг. Срочно найдите другой блестящий предмет и скажите: «Смотри, камень прислал тебе это на память». Такая выдуманная история поможет ловко спасти ситуацию.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'Моя сказка — мои правила 📖', 'Вы ошиблись в слове, читая сказку, и малыш тут же вас поправил? Значит, он уже выучил её наизусть! Закройте книгу и скажите: «Тогда сегодня ты почитаешь мне». Пусть работает его воображение, а вы просто полежите и послушайте его голос.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'Суповой детектив за работой 🥕', 'Опустил ложку в суп, нашёл единственный кусочек лука и отложил его в сторону? Ювелирная точность! Скорее загляните в раздел «Полезные рецепты» и узнайте, как с завтрашнего дня измельчать овощи в блендере и прятать их в соусах, чтобы незаметно одержать победу.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'Тишина на двоих 🥂', 'Ребёнок уснул, дома наведен порядок. Сядьте с партнёром рядом на диване и даже не включайте телевизор. Просто обменяйтесь взглядами: «Мы и с этим справились, мы выжили». Поверьте, это и есть самый романтичный и настоящий момент родительства.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'То самое страшное «Хочу!» в магазине 🛒', 'Кричит из-за шоколадки прямо перед кассой? Не сдавайтесь, несмотря на взгляды людей в очереди. Откройте список покупок и скажите: «Здесь этого нет, касса не пропустит». Внешний авторитет всегда кажется детям убедительнее.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'Зачем ты со мной заговорила? 😤', 'Рассердился только потому, что вы сказали: «Доброе утро»? Период беспричинных обид идёт полным ходом. Не давите, налейте себе чаю и спокойно выпейте. Будьте уверены: через 2 минуты малыш прибежит и обнимет вас за колени. Просто его чувства сейчас так запутаны!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'Ребёнок на четвереньках 🐾', 'Сегодня утром малыш выбрался из кровати не как ребёнок, а на четвереньках, изображая собаку? Не раздражайтесь и не читайте нотаций. Скажите: «Молодец, мой умный пёсик!» — и подайте завтрак. Включиться в ролевую игру гораздо менее энергозатратно, чем спорить и упрямиться.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'Внезапный крик среди ночи 😭', 'Малыш проснулся ночью, плачет с закрытыми глазами и не слышит вас? Судя по этим признакам, это ночной ужас. Постарайтесь не будить его, просто оставайтесь рядом, возьмите за руку и погладьте. Он сам успокоится и снова погрузится в глубокий сон.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'Моё тело мне не принадлежит 🔋', 'Малыш весь день цепляется за ваши ноги и просится на руки? Вы физически истощены. Это усталость от прикосновений (touched out). Оставьте его в комнате с игрушками и на 5 минут укройтесь в ванной, чтобы просто побыть в одиночестве. Вы имеете на это право.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'Я сам открою дверь! 🚪', 'Вы открыли дверь, когда выходили из дома, а малыш расплакался и потребовал закрыть её обратно? Ощущение контроля — важнейшая психологическая потребность в этом возрасте. Лучше потратить 1 минуту и позволить ему сделать всё самому, чем получить 30-минутную истерику на улице. Заодно вы укрепите его уверенность в себе.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'Наводнение в ванной 🌊', 'Купание — лишь предлог, а на самом деле малыш устроил в ванной океан и играет с волнами? Пусть играет. Шум воды и брызги помогут выплеснуть его неуёмную, упрямую энергию. Вечером он ляжет в кровать без всякого сопротивления.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'Ответ AI на необычные вопросы 🤖', 'Вопрос «Мама, куда ночью уходит моя тень?» застал вас врасплох? Не выдумывайте ответ. Откройте Anacan AI и попросите самый сказочный, милый и при этом научный ответ для ребёнка 3.5 лет, а затем прочитайте его малышу. Почувствуйте себя великим философом и мамой, которая знает всё.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'Гордость за футболку наизнанку 👕', 'Малыш надел футболку наизнанку и решительно не позволяет её поправить? Это его дело! Уверенность в его глазах, говорящих «Я сам справился», важнее правильно надетой одежды. Пусть весь день с гордостью ходит так — это его выбор.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'Засыпаем под шёпот 🤫', 'Малыш встаёт с кровати, бегает по комнате и не хочет спать? Не кричите. Внезапно начните говорить очень тихо, почти шёпотом. Чтобы понять вас, ему придётся так сильно сосредоточиться, что мозг устанет и автоматически переключится в режим сна. Попробуйте!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'Идеальный момент тишины 🛋️', 'Малыш так увлечённо собирает пазлы, что в доме внезапно стало тихо? Не ищите подвоха — сразу налейте себе кофе. Потратьте эти редкие золотые минуты не на уборку или стирку, а на отдых для души. Вы не робот.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'Мини-лаборатория в ванной 🛀', 'Малыш добавляет в воду разноцветное мыло и готовит волшебное зелье. Да, в ванной будет беспорядок. Но так он узнаёт о растворителях и смешивании веществ. Эти научные эксперименты помогут снять накопившуюся за день усталость и лучше всего подготовят его к спокойному сну.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'Бунт против прикосновений 🔋', 'Вы физически истощены из-за ребёнка, который весь день карабкается по вам и тянет вас за волосы. Оставьте его в безопасном месте и сразу перейдите в другую комнату. Запишите в дневнике настроения «Моё тело мне не принадлежит», чтобы сбросить психологический груз синдрома touched out.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'Самоизоляция в шкафу 🚪', 'Посреди домашнего шума внезапно наступила тишина. Вы нашли малыша в платяном шкафу, где он в одиночестве играет в темноте. Это не депрессия, а просто момент эмоциональной перезагрузки. Слегка прикройте дверцу и позвольте ему насладиться роскошью личного пространства.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'Похититель телефона 📱', 'Наливая себе чай, вы заметили, что телефон исчез, а потом услышали, как малыш за диваном, подражая вам, говорит «Алло». Он сканирует ваши цифровые привычки.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', 'Политика «Оденься сам!» 👖', 'Он поднимает ноги вверх и говорит: «Я малыш, одевай меня». Дети постоянно мечутся между самостоятельностью и зависимостью. Не одевайте его силой. Положите одежду рядом и схитрите, сказав: «Эти штаны супергероя ждут своего хозяина».'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'Внутренний покой с шумомером 🤫', 'Он наконец уснул. Но звон в ушах всё не проходит. Откройте в приложении шумомер. Глядя на надпись «0 децибел» на экране, наглядно убедитесь, как тишина в комнате проникает в ваш мозг и помогает вам восстановиться.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'Поддержка в сообществе Anacan 💬', 'Вас душит мысль: «Я никогда не стану идеальной»? Забудьте об иллюзии идеальных мам из Instagram. Зайдите в Сообщество Anacan, почитайте искренние признания мам, у которых дома полный беспорядок, а дети рисуют на стенах, и скажите себе: «Я совершенно нормальная».'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'Мистическая сила шёпота 🌙', 'Он придумывает отговорки, лишь бы не ложиться спать. Понизьте голос и говорите только шёпотом. Чтобы понять вас, ему придётся сосредоточить всё внимание, а эта концентрация словно загипнотизирует его мозг и поможет уснуть.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'Логика динозавра 🦖', 'Утром он не отвечает ни на один вопрос, а только рычит. Сегодня он — тираннозавр. Подыграйте придуманному им образу и спросите: «А тираннозавры едят кашу?» — так вы завершите утренний ритуал без единой слезинки.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'Выдуманные папины герои 🦸‍♂️', 'Сегодня вечером забудьте сказки из книг. Пусть папа сочинит фантастическую историю, главным героем которой будет сам ребёнок. Фразы вроде «И тогда он достал свой меч и... почистил зубы!» рассмешат ребёнка и помогут подготовить его ко сну.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'Критика собственного рисунка 🖍️', 'Он показывает свои чёрные каракули, говорит: «Это был ты, но получилось плохо», рвёт рисунок и выбрасывает. У него появляется способность критически оценивать себя! Не обесценивайте его чувства. Поддержите развитие, предложив: «Может быть, в следующем рисунке попробуешь ещё и красный цвет?»'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', '«Это я нашёл» в магазине 🛒', 'У кассы в тележке внезапно обнаруживается пачка печенья, которую вы туда не клали. Малыш незаметно провёл разведку. Откройте список покупок и переложите ответственность за правило на цифровой авторитет: «Смотри, этого нет в нашем списке. Давай запишем на следующий раз».'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'Олимпиада по лазанию по мебели 🧗‍♂️', 'Он карабкается по краю дивана к окну. Для вас дом полон опасностей, а для него это спортивный зал. Вместо того чтобы сеять панику словами «Осторожно, упадёшь!», правильно направьте его потребность в движении, спокойно подсказав: «Поставь руку сюда».'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'Операция «Скрытые овощи» 🥦', 'Он находит в супе единственную рисинку или кусочек моркови и заявляет: «Я это не ем». Откройте план питания. Узнайте, как превратить белковые продукты и овощи в разноцветные кексы, и перехитрите мозг этого упрямого кулинара.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'Чай для двоих 🥂', 'После трудного дня налейте в стаканы обычный горячий чай. Сядьте с партнёром лицом друг к другу на диване, чокнитесь стаканами и скажите: «Мы пережили и этот хаос — мы отличная команда». Вы — нерушимый фундамент вашей семьи.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'Страх собственной тени 👻', 'Во время прогулки он внезапно испугался собственной тени и спрятался за вами. Не ищите здесь логики — так работает воображение в 3.5 года. Скажите: «Давай попрыгаем на тени!» — и сразу превратите пугающий объект в подвижную игру.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'Искусственный интеллект и спокойствие 🤖', 'Внезапное заикание или приступы гнева у ребёнка заставили вас искать в интернете страшные заболевания? Остановитесь! Спросите у Anacan AI, не связан ли этот период со скачком развития в 3 года, и получите успокаивающий ответ, подтверждённый педиатрами.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'Звуковые эффекты в комнате 🪄', 'Включите умные сказки. Читая историю, устройте в комнате звуковой театр: изображайте скрип двери, шум ветра и шипение. Эти необычные звуковые волны мгновенно перенесут его внимание в сказку, а оттуда — в глубокий сон.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'Серединка хлеба — моя! 🍞', 'Он съедает только середину ломтика хлеба, а корочки протягивает вам? Не спорьте из-за корочек. С завтрашнего дня вырезайте хлеб металлическими формочками для печенья в виде животных. Интересный дизайн мгновенно решит эту гастрономическую дилемму.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'Папа в режиме полёта ✈️', 'Малыш не успел выплеснуть энергию дома и не хочет ложиться спать. Позовите папу на диван. Когда он поднимет ребёнка в воздух и поиграет с ним в самолётик, звонкий смех за считаные секунды снимет всё накопившееся физическое напряжение. Мяч на стороне папы.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'Изобретение нового языка 🗣️', 'Малыш придумывает совершенно необычные поэтичные фразы, наделяя предметы эмоциями: «Моя игрушка загрустила», «Небо заплакало». Его словарный запас и эмоциональный интеллект развиваются стремительно. Сразу сохраните эту милую детскую философию, сняв её на видео в детской фотосессии.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'Маленький шеф на кухне 🧑‍🍳', 'Когда вы готовите кекс, малыш непременно хочет поставить рядом стул и сам насыпать муку. Если разрешить, кухня превратится в поле боя. Дайте ему пустую миску, воду и немного муки и скажите: «Замеси тесто для своего кекса». Будет хаос, зато его потребность в самостоятельности будет полностью удовлетворена.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', 'Бунт «Ты меня корми!» 🥣', 'Хотя малыш умеет есть самостоятельно, он упрямо требует, чтобы вы его кормили, а затем отталкивает ложку и плачет. Это возраст противоречий. Не пытайтесь кормить его и не бойтесь, что он останется голодным. Поставьте перед ним тарелку, скажите: «Проголодаешься — поешь» и выйдите из-за стола. Он поест сам.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'Запас сил для мамы 🥗', 'Вы придумывали разные блюда, чтобы накормить малыша, а сами снова перекусили на ходу чем-то сухим? Среди полезных рецептов выберите не только детское блюдо, но и питательный обед для мамы, богатый железом и кальцием, который готовится за 10 минут. Позаботьтесь и о себе.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'Игра «Моя игрушка заболела» 🩺', 'Малыш берёт игрушечный стетоскоп, серьёзно осматривает своего мишку и наклеивает ему пластырь. Через сюжетно-ролевые игры он учится проявлять сострадание и заботу. Притворитесь пациентом в больнице, прилягте и позвольте ему спокойно осматривать вас в течение 5 минут.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'Лёгкое засыпание с умными сказками 🪄', 'Вы уже выучили классические книги наизусть. Откройте умные сказки и без особых усилий устройте необычный сеанс перед сном: сделайте главным героем своего ребёнка, а местом, которое ему предстоит покорить, — его комнату.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'Просто обнимите 🫂', 'Не нужны ни игры, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, глубоко вдохните его чудесный запах и в темноте прошепчите ему, как он вам дорог и как сильно вы его любите.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'Разговоры с неодушевлёнными предметами 🗣️', 'Малыш совершенно серьёзно что-то рассказывает камню в парке или стулу дома и даже ругает их. Через символические игры он осмысливает окружающий мир.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'Утренние прятки 🙈', 'Вы опаздываете на работу или в детский сад, а малыш прячется за шторой и говорит: «Найди меня!» Даже если нервы на пределе, крик лишь затянет процесс. На 2 минуты включитесь в игру со словами: «Интересно, где же мой чудесный малыш?», найдите его и выведите из укрытия.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'Дипломатия на детской площадке 🤝', 'Малыш толкает другого ребёнка у горки, чтобы прокатиться самому? Умение делиться — пока ещё сложное и не до конца понятное для него правило. Вместо того чтобы стыдить или наказывать, просто напомните порядок словами: «Сейчас его очередь».'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'Почему солнце смотрит на меня?! ☀️', 'Малыш открывает утром глаза, спрашивает: «Почему солнце светит прямо мне в глаза?» — и начинает рыдать? Не ищите логики и не пытайтесь объяснить природные явления: он просто злится, потому что не может управлять миром. Задёрните штору, скажите: «Я спрятала для тебя солнце» — и мгновенно решите эту абсурдную проблему.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'Моя машинка ещё не уснула! 🚗', 'Малыш отказывается ложиться в кровать и твердит: «Моя машинка ещё не хочет спать»? Дети часто переносят собственное нежелание спать и сопротивление на свои игрушки. Не спорьте, откройте умные сказки и придумайте историю о машинках. Как только машинка уснёт, малыш тоже сам закроет глаза. Попробуйте и убедитесь!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'Срежьте корочку с хлеба! 🍞', 'Малыш ест только мягкую часть тоста и решительно отказывается от корочек? В этом возрасте у детей особое визуальное восприятие еды. Научитесь вырезать из хлеба фигурки милых животных. Такой дизайн мгновенно прекратит этот спор.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'Прелесть молчаливого взгляда 🥂', 'Ребёнок уснул, дома наведен порядок. Сядьте рядом с партнёром на диван и даже не включайте телевизор. Просто обменяйтесь взглядами, которые говорят: «Мы пережили и этот день». Поверьте, это и есть самый романтичный и настоящий момент уставшего родительства.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'Трагедия невидимого пятна 👕', 'Малыш нашёл на рубашке пятно, которое можно увидеть лишь под микроскопом, и отказался её надевать? Сделайте вид, что вытираете пятно влажной салфеткой, и скажите: «Я волшебством заставила его исчезнуть». Дети всегда верят в мамино волшебство — попробуйте и убедитесь.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'Театр теней в тёмной комнате 🐰', 'Боится темноты и не хочет ложиться спать? Полностью выключите свет в комнате и включите небольшой фонарик. Покажите на стене руками тени собаки и птицы. Превратите пугающую темноту в игровую площадку — и малыш уснёт в считаные минуты.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'Динозавры не едят кашу! 🦖', 'Утром не отвечает ни на один вопрос, а только рычит? Сегодня он тираннозавр. Подыграйте придуманному образу, спросив: «А тираннозавры завтракают?» — и малыш сядет за стол без слёз.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'Сегодня у меня закончились силы 🛑', 'Всё навалилось разом, и вы повысили голос. А теперь вас мучает чувство вины. Вы не робот. Откройте дневник настроения и напишите: «Сегодня я действительно очень устала». Такое признание поможет вам гораздо больше, чем попытки заставить себя улыбаться через силу.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'Игра «Кто вы?» 🎭', 'Утром малыш посмотрел на вас как на незнакомку и спросил: «Кто вы? Где моя мама?» Это новая ролевая игра. Ответьте: «Я соседка, а твоя мама скоро придёт». Пусть с самого утра комната наполнится смехом — это сбережёт гораздо больше сил, чем упрямые споры.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'Уложить спать без чтения сказки 🪄', 'Сегодня вечером совсем нет сил читать сказку? Включите «Умные сказки». Оставьте фоном лишь шёпот леса и шум ветра. Слушая в темноте звуки природы, вы оба отдохнёте от шума. Зрительное напряжение исчезнет мгновенно.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'Сокровище, забытое в стиральной машине 🍝', 'При стирке в кармане брюк обнаружились засохшие макароны или камешек? Это не жадность, а детская страсть к исследованиям. С серьёзным видом выбросьте находку, но в душе улыбнитесь своему маленькому запасливому исследователю. Отметьте это в трекере развития как забавный момент.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'Дайте воду в другом стакане! 🥤', 'В комнате разразилась буря из-за того, что вы налили воду в жёлтый стакан? Не усугубляйте ситуацию — малыш просто проверяет границы. Сразу перелейте воду в тот стакан, который он хочет, восстановите мир в комнате и поберегите силы на оставшуюся часть дня.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'Соревновательная тактика для ухода из парка 🌳', 'Пора возвращаться из парка, но началась истерика. Увести малыша силой не получится. Скажите: «Посмотрим, кто быстрее дойдёт до машины как пингвин?» — и сразу переключите его внимание на забавное соревнование. Он непременно захочет победить.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'Борьба с папой на диване 🤼‍♂️', 'Малыш убежал и спрятался, лишь бы не ложиться спать? Передайте эстафету папе. Пусть они понарошку поборются на диване. Эта шумная и активная игра заберёт остатки неуёмной энергии, и малыш легко сдастся сну.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'Эффект музыкального гипноза 🎶', 'Попробуйте усмирить беспричинные вечерние бури с помощью лёгкой классической музыки. Выключите телевизор. Часто этот простой приём помогает заглушить окружающий шум глубокими звуками и каким-то чудом приносит в комнату тишину.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'Слова, которые малыш придумал сам 🗣️', 'Малыш произносит необычные фразы вроде «Небо плачет» или «Машина обиделась». Его словарный запас растёт как на дрожжах, и он играет со словами. Откройте трекер развития и сохраните эту милую поэтичную философию — спустя годы вы перечитаете её и от души посмеётесь.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'Без чувства вины за экранную паузу 📺', 'Сегодня у вас было много дел, поэтому малыш долго смотрел телевизор? Вас гложет чувство вины? Невозможно быть идеальной каждый день. Иногда экран — самая безобидная няня, спасающая нас от большого хаоса. Не вините себя.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'Появление странных страхов 🤖', 'Малыш внезапно начал бояться сливного отверстия в ванной? Не ищите в интернете симптомы болезней. Спросите Anacan AI и узнайте, что это совершенно нормальная и временная фобия, связанная с особенностями воображения в этом возрасте. Это поможет вам перестать паниковать.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'Я сам буду есть! 🥣', 'Хотя малыш уже умеет есть самостоятельно, он настойчиво требует, чтобы вы его кормили, а когда вы протягиваете ложку, отталкивает её и плачет. Он и сам не знает, чего хочет. Поставьте перед ним тарелку, скажите: «Проголодаешься — поешь» — и отойдите от стола. Когда малыш проголодается, он поест сам.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'Уделите немного времени и себе 💆‍♂️', 'Когда малыш уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. От дневной суеты ваша шея наверняка затекла. Вы не просто родители, живущие под одной крышей, а самая близкая психологическая поддержка друг для друга.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Мамы в Instagram и реальность 📱', 'Открыв Instagram и увидев у всех идеальных детей, не падайте духом! Закройте приложение и зайдите в Сообщество Anacan. Увидев, что в домах у других такой же беспорядок, а их дети такие же шумные, скажите себе: «Я совершенно нормальная!»'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'Просто вдохните его запах 🫂', 'Сегодня он и правда свёл вас с ума, высосал всю энергию? Но в кровати он спит таким невинным... Выключите свет, не читайте сказку. Лягте рядом, глубоко вдохните этот чистый детский запах и поблагодарите жизнь за ещё один день.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'Проблема «не хочу выходить из дома» ⛅', 'Четыре стены душат вас, а малыш плачет на диване и не хочет выходить на улицу? Откройте раздел «Погода и одежда», подберите подходящий комплект и всё же отведите его в парк, даже если придётся настоять. Как только свежий воздух коснётся его лица, вся агрессия улетучится. Мы в вас верим!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'Закон несоприкасающихся продуктов 🚫', 'За завтраком разразилась революция из-за того, что помидор коснулся огурца? Добро пожаловать в официальную пищевую философию возраста 3.5 лет. Не ищите логики: узнайте в разделе «Полезные рецепты», как весело разделить тарелку на изолированные зоны, и мирно уладьте этот абсурдный кризис.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'Дипломатический торг перед сном 🤝', 'Чтобы не ложиться в кровать, малыш официально торгуется с вами: «Сделаю два глотка воды, обними меня один раз — и потом я усну». Улыбнитесь этой искусной манипуляции. Примите условие, решительно выключите свет и тут же закройте сделку.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'Игра «Пол — это лава» 🌋', 'Пол — это лава, скорее на диван! Воображение превратило дом в джунгли. Отложите свои дела и хотя бы на 2 минуты войдите в его мир, спасаясь от лавы вместе с ним. Иногда подчиниться детским правилам — лучший способ снять стресс.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'Сокровища из мусорного ведра 🗑️', 'Вместо купленной в магазине игрушки малыш весь день обнимает пузырчатую плёнку, в которую она была завёрнута, и играет с ней? Детский мозг любит не готовые сценарии, а свободу. С гордостью отмечайте такие необычные моменты творчества в «Трекере развития».'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'Умиротворяющие минуты вечера 🛀', 'За весь день от бесконечных «почему» у вас уже голова кругом. Посадите малыша в ванну с тёплой водой и добавьте немного пены. А сами сядьте рядом и просто сосредоточьтесь на звуке воды. Её волшебное действие смоет детское упрямство и успокоит ваши нервы.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'Ты меня не слышишь! 😤', '«Послушай меня!» — говорит малыш и руками поворачивает ваше лицо к себе. Ему нужно не просто ваше физическое присутствие, а 100% вашего внимания. Всего на 3 минуты отложите телефон или дело, которым заняты, и выслушайте его, не отводя глаз. Это поможет предотвратить хныканье, которое иначе может длиться часами.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'Полуночная философия 🦉', 'Стоит лечь в кровать, как малыш задаёт глубокие вопросы вроде: «Мама, почему облака не падают вниз?» Его цель не в том, чтобы изучать науку, а в том, чтобы поговорить с вами и отсрочить сон. Дайте короткий выдуманный ответ вроде «Потому что они спят наверху», включите нежную мелодию из «Умных сказок» и решительно установите сонную тишину.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'Тот самый шокирующий вопрос в магазине 😳', 'Стоя в очереди к кассе, малыш громко спросил: «А почему у этой тёти такие волосы?» Не стыдите и не заставляйте его замолчать. Сразу переключите внимание на «Список покупок» в приложении: «Давай проверим, купили ли мы яблоки?» — и дипломатично выйдите из ситуации.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'Зачем вы постирали ту футболку?! 👕', 'Из-за того, что вы отправили в стирку любимую, уже выцветшую футболку, дома объявлен траур? Привязанность детей к вещам порой не поддаётся логике. Не спорьте: сразу откройте «Фотосессию малыша», сфотографируйте его сердитым и превратите ситуацию в повод для смеха. Уловка «Давай посмотрим, какой ты сердитый на экране» мгновенно отвлекает внимание — попробуйте!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'Выключите свет — театр теней начинается 🐰', 'Малыш боится темноты и не хочет один выходить в коридор? Полностью выключите свет в комнате и зажгите маленький фонарик. Покажите руками на стене тени собаки и птицы, превратив темноту из страшного места в игровую площадку. И малыш уснёт в мгновение ока.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'Вам тоже нужно побыть offline ☕', 'Малыш так увлечённо играет в комнате с игрушками, что в доме внезапно воцарилась тишина? Пожалуйста, не тратьте этот момент на уборку или складывание белья! Лягте на диван, запишите в «Дневнике настроения»: «Всего 5 минут покоя» — и выпейте кофе, пока он горячий. Вы тоже человек в этом доме.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'Это не я разлил, это мишка! 🧸', 'Малыш нарочно пролил воду на пол и сваливает вину на игрушку? Он не врёт, а просто открыл для себя защитный механизм возраста 3.5 лет. Не спорьте. Скажите: «Тогда давай научим мишку убирать за собой» — и дайте малышу полотенце. Так он научится ответственности, а его самолюбие не пострадает.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'Упрямство, бросающее вызов физике 💧', 'Малыш разлил воду на стол и, плача, требует, чтобы вы собрали её обратно в стакан! Да, в комнате сейчас нет логики — есть только разочарование из-за необратимой ошибки. Не пытайтесь объяснять. Дайте малышу полотенце, скажите: «Давай заставим эту воду исчезнуть» — и превратите всё в игру.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'Offline-убежище для мамы 🚪', 'От шума у вас уже звенит в ушах. Оставьте малыша в безопасном месте (или с папой), зайдите в туалет и закройте дверь. Просто 5 минут смотрите на стену, ничего не делайте и даже не берите телефон. Эта короткая тишина — самое мощное средство, которое поможет вам восстановиться и вернуться к роли мамы.'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'По звонку — спать ⏱️', 'Укладывание всё затягивается и затягивается. Вода, туалет, попрощаться со стеной... Установите таймер на телефоне и введите правило: как только звучит сигнал, все выключают свет. Услышав его, малыш отправится в кровать без возражений.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'Ребёнок на четвереньках 🐾', 'Сегодня утром малыш выполз из кровати не как ребёнок, а как собачка? Не сердитесь и не читайте нотаций. Скажите: «Молодец, мой умница Бобик!» — и дайте ему завтрак. Включиться в ролевую игру гораздо менее утомительно, чем спорить и упрямиться.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'Моё тело мне не принадлежит 🔋', 'Малыш весь день цепляется за ваши ноги и просится на руки? Вы физически истощены и устали от постоянных прикосновений. Оставьте его в комнате с игрушками, на 5 минут уйдите в ванную и закройте дверь. Просто побудьте в одиночестве.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'Внезапный крик посреди ночи 😭', 'Малыш ночью проснулся с плачем, не открывает глаза и словно не слышит вас? По характеру плача это похоже на ночной ужас. Не пытайтесь его разбудить — просто оставайтесь рядом, держите за руку и гладьте. Вскоре он сам успокоится и снова погрузится в глубокий сон.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'Кухонная катастрофа с помощником 🧑‍🍳', 'Пока вы раскатывали тесто, малыш подставил стул и непременно захотел сам насыпать муку? Не позволите — расплачется. Дайте ему небольшую пластиковую миску и немного муки. На кухне будет беспорядок, но его серьёзное выражение лица настоящего повара того стоит.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'Я сам открою дверь! 🚪', 'Вы собрались выйти из дома и открыли дверь, а малыш расплакался, заставил её закрыть и открыл сам? В этом возрасте ощущение контроля — важнейшая психологическая потребность. Лучше потерять 1 минуту сейчас, чем получить 30-минутную истерику на улице.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'Забыть всё посреди магазина 🛒', 'Остановились посреди магазина с мыслью: «Что же я собиралась купить?» Мозг мамы и правда перегружен. Откройте в приложении «Список покупок» и доверьтесь этой цифровой памяти — она всегда поможет выбраться из хаоса.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'Потоп в ванной 🌊', 'Купание — лишь предлог, а на самом деле малыш устроил в ванной океан и играет с волнами? Пусть играет. Шум воды и брызги помогут выплеснуть его неиссякаемую энергию. Вечером он ляжет спать без сопротивления.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'Момент идеальной тишины 🛋️', 'Малыш так увлёкся пазлами, что в доме внезапно воцарилась тишина? Не ищите подвоха — сразу налейте себе кофе. Потратьте эти редкие, драгоценные минуты не на уборку или стирку, а на отдых: просто посмотрите в потолок. Вы не робот.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'Бирка на футболке колется! 🏷️', 'Малыш отказывается надевать футболку, потому что маленькая бирка сзади колется как иголка? Сенсорная чувствительность в этом возрасте может свести с ума. Не спорьте: возьмите ножницы, срежьте бирку под корень и за секунду завершите этот мини-кризис.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'Засыпаем под шёпот 🤫', 'Малыш встаёт с кровати, бегает по комнате и не хочет спать? Не кричите. Внезапно начните говорить очень тихо, почти шёпотом. Чтобы понять вас, ему придётся так сильно сосредоточиться, что мозг устанет и автоматически переключится в режим сна. Попробуйте!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', '«Это игрушка разлила!» 🤷‍♂️', 'Малыш намеренно разлил воду, а потом показал пальцем на машинку и сказал: «Это она толкнула»? Это не ложь, а защитный механизм. Скажите: «Давай научим машинку убирать за собой» — и умело переключите его внимание.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'Цифра тишины на экране 🤫', 'Наконец-то малыш уснул. В доме стало так тихо, что у вас звенит в ушах? Откройте в приложении шумомер. Вид надписи «0 децибел» станет лучшим визуальным массажем для вашего уставшего от шума мозга.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'Операция «Невидимые овощи» 🥦', 'Малыш нашёл в супе единственный кусочек моркови и заявил: «Я это не буду»? Знакомая картина! Измельчите овощи в пюре и добавьте в соусы — посмотрим, как он теперь их найдёт! Перехитрите этого кулинарного сыщика.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'Гордость наизнанку 👕', 'Малыш надел футболку наизнанку и категорически не позволяет её поправить? Это его выбор! Уверенность в глазах, говорящих «Я сам справился», важнее правильно надетой одежды. Пусть весь день с гордостью ходит так — это его свободный выбор.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'Когда ваш голос не помогает, приходит папа 🤡', 'Малыш больше не реагирует на ваши слова и упрямится? Но стоило папе издать странные звериные звуки и скорчить смешную рожицу, как он тут же рассмеялся? Иногда этот нелогичный мужской юмор действительно спасает ситуацию. Просто наблюдайте со стороны.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'Притяжение к полу 🍝', 'Малыш нарочно бросает еду на пол и смотрит ей вслед? Не кричите: на самом деле он хочет не позлить вас, а проверить, как работает сила притяжения. Спокойно уберите тарелку, а воспитательную беседу проведёте позже.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'Зови меня Бэтменом! 🦇', 'Проснувшись утром, малыш отказывается от своего имени и требует называть его по-другому? Подыграйте! На 5 минут превратите напряжённую обстановку в комедию, сказав: «Пожалуйста, Бэтмен, ешь свою кашу».'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'Беда с резинкой на пижаме 👖', 'Малыш кричит, что пижама ему жмёт, хотя она с него спадает? Это разыгралась сенсорная чувствительность. Скажите: «Подожди, я прочитаю волшебное заклинание, и она станет шире», — и понарошку растяните пижаму. Он поверит!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'Если я закрою глаза, то исчезну 👀', 'Малыш старается не моргать и держится, пока глаза не начинают слезиться? Детский мозг порой придумывает необъяснимые страхи. Превратите этот нелепый страх в игру, сказав: «Смотри, я закрыла глаза и всё ещё здесь».'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'Не трогай меня, мне жарко 🛑', 'Малыш внезапно отказался вас обнимать? Не обижайтесь! Он проверяет свои личные границы и осознаёт, что его тело принадлежит только ему. Это признак самостоятельности — с гордостью наблюдайте со стороны.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'Сон под креслом 🛋️', 'Малыш отказался от своей кровати, свернулся калачиком под креслом и уснул? Не вытаскивайте его силой и не будите. Пусть наслаждается сном в необычном и уютном укрытии, а вы тем временем отдохните.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'Подушка лежит неровно! 🛏️', 'Малыш плачет, требуя выровнять подушку с точностью до миллиметра? Это стремление к совершенству. Подчинитесь правилам, поправьте подушку так, словно измерили всё линейкой, и решительно выключите свет.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'Паника из-за тишины в доме 🚪', 'В доме внезапно стало слишком тихо? Отправившись на поиски, вы наверняка обнаружите малыша за дверью, погружённого в свои мечты. Не волнуйтесь: он отдыхает от шума и перезагружается. Дайте ему это время.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'Беда: крекер сломался 🍪', 'Малыш устроил конец света из-за того, что крекер разломился пополам? Склеить его обратно не получится. Подключите математику и умение делиться, сказав: «Смотри, теперь их два: один мне, другой тебе».'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'Мороженое осталось во сне 🍦', 'Малыш ел во сне мороженое и рассердился на вас за то, что вы его разбудили? Сон и реальность перепутались. Обнимите его сердитую мордашку и улыбнитесь — возвращение в реальность займёт 2 минуты.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'Цвет стакана для воды 🚰', 'Малыш ночью просит воды, но только не в красном стакане? Не ищите среди ночи логику и не читайте ему нотаций. Сразу замените стакан, а силы приберегите до утра — как и мир в доме.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', 'Психоз «У меня в ботинке камешек» 👟', 'Малыш уже 10 раз просил снять обувь и проверить её, но никакого камешка там нет! Знакомый сценарий? Незаметно возьмите в руку чёрную крупинку, скажите: «Смотри, я нашла, мы спасены!» — и продолжайте прогулку.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'Почему каша горячая? 🥣', 'Если каша не горячая, малыш её не ест, а теперь плачет, потому что она горячая? Безвыходная ситуация! Нарочно бросьте в кашу цветной кубик льда — он моментально заинтересуется и успокоится.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'Плач за закрытой дверью 🚪', 'Малыш закрыл дверь, плачет один в своей комнате и не хочет вас видеть? Не пытайтесь обнять его силой. Иногда детям тоже хочется пережить свои эмоции в одиночестве — дайте ему время и личное пространство.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'Злость на волка из книги 🐺', 'Малыш бьёт кулаком изображённого в книге волка и ругает его? У него потрясающее воображение! Не разрушая его представлений, поддержите уверенность малыша в себе словами: «Ты защитил меня, ты такой смелый».'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'Не надевай на меня носки! 🧦', 'Малыш решительно отвергает всё, что вы делаете? Прекрасно! Положите одежду на диван и устройте соревнование: «Кто оденется первым?» Он сам оденется за считаные секунды.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'Философия под столом 🤔', 'Залезает под стол и оттуда рассказывает вам разные выдумки? Пусть маленький философ побудет в своём воображаемом мире, а вы воспользуйтесь этим временем и отдохните.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'Одеяло шумит 🛌', 'Не может уснуть из-за шороха одеяла! Странные отговорки достигли пика. Накройте малыша лёгким пледом — увидев, что у вас на всё есть решение, он сдастся.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'Бунт против купания 🛀', 'Не хочет залезать в воду? Положите в ванну ёмкости разных цветов или даже пластиковые кухонные принадлежности. И вода внезапно превратится из пугающего места в центр развлечений.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'Я папа 👔', 'С утра надевает большие папины туфли и собирается на работу? Не спешите его останавливать! Проводите до двери — увидев лифт, малыш со смехом вернётся обратно.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', 'Любовь к 0 децибелам 🤫', 'Наконец-то уснул! Откройте в приложении Шумомер и наблюдайте за абсолютной тишиной, опустившейся до самого низа экрана. Эта визуальная тишина подействует на ваш уставший мозг как настоящий спа-массаж.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'Дерево сбросило лист 🍂', 'Обижается на дерево и ругает его из-за лежащего на земле листа? Его связь с природой такая искренняя и забавная!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'Моя тень идёт впереди меня 👻', 'Плачет на улице, потому что тень идёт впереди него? Возьмите малыша на руки и скажите: «Смотри, наши тени соединились». Вместо объяснения законов физики просто дайте ему почувствовать себя в безопасности.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'Странные папины шутки 🤡', 'Не сердитесь, если перед сном папа рассмешил и разбудил малыша. Этот весёлый смех поможет ребёнку полностью сбросить накопившийся за день стресс — пусть немного пошумят.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'Чтобы яйцо не плакало 🍳', 'Ему стало жалко яйцо, когда вы его разбили, и теперь он отказывается есть? Его эмпатия безгранична. Спасите ситуацию милой выдумкой: скажите, что теперь яйцо будет жить в его мышцах.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'Игра в шёпот 🤫', 'Не хочет спать и убегает? Резко понизьте голос и начните говорить очень тихим шёпотом. Чтобы вас услышать, малыш сосредоточится, его мозг устанет, и через 5 минут он сдастся сну.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'Сигналы тела 🩸', 'Не поддавайтесь беспричинному раздражению и усталости. Загляните в Трекер менструации — ваше тело подаёт сигнал. Вместо того чтобы винить себя, отдохните и перекусите чем-нибудь богатым магнием из раздела Здоровых рецептов.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'Только красная еда 🍅', 'Сегодня день причуд! Хочет только всё красное? Загляните в план питания и предложите сегодня красные помидоры и клубнику. Пусть это необычное желание исполнится — не спорьте.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'Моя игрушка заболела 🩺', 'Уложил своего мишку в больницу? Притворитесь больной и вы! Лягте на диван и позвольте ему 10 минут понарошку вас обследовать — заодно отдохнёт ваша спина.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'Настойчивое «Спи со мной» 🫂', 'Настаивает, чтобы вы спали рядом? Нарушьте правила хотя бы на один день: глубоко вдыхая родной запах малыша, усните вместе с ним. Это терапия любовью для вас обоих.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'Искусственный интеллект, помоги мне 🤖', 'Бесконечные философские вопросы ребёнка вас утомили? Напишите Anacan AI — он мгновенно подготовит за вас самые научные, терпеливые и милые ответы, понятные 4-летнему ребёнку.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'Не узнал себя в зеркале 🪞', 'Смотрит на себя в зеркале, меняет выражение лица и сердится на самого себя? Так формируются его личность и эмоции. Просто молча понаблюдайте со стороны за этой актёрской игрой.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'Ответ ИИ на странные вопросы 🤖', 'Растерялись, услышав вопрос: «Мама, куда ночью уходит моя тень?» Ничего не выдумывайте. Откройте ИИ Anacan, получите самый сказочный, милый и научный ответ для этого возраста и прочитайте его малышу. Вы почувствуете себя великим философом.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'Запишите свой гнев 📝', 'Никто не замечает, как сильно вы устаете дома, и это доводит вас до точки кипения? Откройте дневник настроения. Запишите туда все, что сегодня выводило вас из себя. Признать и описать свои эмоции гораздо полезнее, чем натянуто улыбаться.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'Долгие разговоры с неодушевленными предметами 🗣️', 'Он совершенно серьезно что-то рассказывает камню в парке или стулу дома? Через игру малыш познает правила и окружающий мир.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'Давайте сегодня просто обнимемся 🫂', 'Не нужны ни игры, ни шумные книжки. Сегодня просто прижмите малыша к груди, глубоко вдохните этот чистый детский запах и прошепчите в темноте, как он вам дорог. Этого будет достаточно вам обоим.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'Не угадывайте погоду по виду из окна ⛅', 'На улице солнечно, но дует ветер? Если инструмент погоды и одежды советует одеться многослойно, доверьтесь ему. Вместо того чтобы сомневаться и ворчать у двери, выберите подходящий комплект и спокойно отправляйтесь на прогулку.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'Свою еду вам не отдаст 🍳', 'Он не делится с вами едой из своей тарелки, но настойчиво просит попробовать из вашей? Дети безоговорочно доверяют выбору родителей. Не сопротивляйтесь: с любовью отдайте ему кусочек и просто улыбнитесь этому забавному эгоизму.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'Моя сказка — мои правила 📖', 'Вы ошиблись в слове, читая сказку, а малыш тут же вас поправил? Значит, он уже выучил ее наизусть! Закройте книгу и скажите: «Тогда сегодня ты почитаешь мне». Пусть работает его воображение, а вы просто прилягте и слушайте этот милый голосок.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'Построить башню, а потом разрушить 🧱', 'Он с большим старанием строит башню из кубиков, а затем со смехом разрушает ее одним движением? Вам может быть жаль его труда, но так малыш изучает физику и причинно-следственные связи. Эти разрушения создают новые связи в его мозге — не сердитесь.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'А где мой обед? 🥗', 'Приготовили малышу особую тарелку с овощами, а сами жуете хлеб? Стоп! Приготовьте тот простой салат для мам из плана питания, который занимает всего 5 минут, и не забывайте наконец заряжать главный двигатель этого дома — себя. Вы важны.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'Выключите свет, чтобы пришел сон 🌙', 'За 1 час до сна выключите в комнате все яркие источники света и телевизор. По мере того как в комнате будет становиться темнее, малыш начнет автоматически зевать. Так вы незаметно и естественно запустите выработку мелатонина — гормона сна — и облегчите себе задачу.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'Я знаю и вас научу ☝️', 'Малыш с очень серьезным и умным выражением лица объясняет вам то, что вы и так знаете? Так он проверяет свои знания. Прикусите губу, чтобы не рассмеяться, но выслушайте его со всей серьезностью и скажите: «Правда? Большое спасибо!»'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'Папа неправильно рассказывает сказку 📖', 'Сегодня вечером не вы будете читать вслух. Передайте книгу сказок папе. Пусть он намеренно рассказывает все наоборот — смешно и абсурдно. А вы с удовольствием наблюдайте со стороны, как малышу нравится поправлять его и заливаться смехом.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'Забудьте об уборке, пусть игрушки полежат 🎨', 'Малыш создал посреди комнаты великое произведение из разных кусочков и не позволяет вам его убрать? Оставьте стремление к идеальной чистоте. Не трогайте созданный им хаос — уборка вполне может подождать до завтра. Дом — не музей.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'Он пересказывает вам мультфильм 📺', 'Малыш пересказывает просмотренный мультфильм, выстраивая совершенно иную логику, и серьезно объясняет, кто и куда пошел? Внимательно слушайте его так, словно верите каждому слову. Пусть он почувствует себя самым умным и сильным на свете.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'Это ужасное «хочу!» в магазине 🛒', 'Малыш кричит и требует шоколад прямо перед кассой? Не сдавайтесь, несмотря на взгляды людей в очереди. Откройте список покупок и скажите: «Этого здесь нет, касса не сможет это считать». Внешний авторитет всегда кажется детям убедительнее.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'Смойте всю усталость водой 🛀', 'Иногда ничего не помогает, и малыш плачет по любому поводу. Посадите его в ванну с теплой водой. Ее почти волшебная способность снимать напряжение мгновенно принесет глубокое спокойствие и всей комнате, и нервной системе малыша. Попробуйте и убедитесь сами.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'Я — герой сказки! 🪄', 'В персонализированных сказках замените имя главного героя на имя ребёнка. Когда малыш увидит, как быстро и послушно герой ложится спать, он вдохновится и захочет сделать так же.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'Не растеряйтесь посреди магазина 🛒', 'Зашли в магазин и забыли, что хотели купить? Если не вести электронный список покупок, в этой суете легко всё забыть. Всегда полагайтесь на свою цифровую память.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'Считаем звёзды перед сном 🌟', 'Малыш смотрит на потолок спальни и считает воображаемые звёзды? Пусть считает. Скорее всего, ещё до десятой выдуманной звезды он задремлет и погрузится в глубокий сон.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'Мои руки стали ногами 🤸‍♂️', 'Пытается ходить на руках и падает? Развитие двигательных навыков идёт полным ходом! Устройте ему небольшую полосу препятствий в безопасном месте дома, чтобы он мог выплеснуть энергию.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'Папа бесшумно приходит на помощь 👨‍🍼', 'Когда вы уже без сил после чтения сказки, папа тихонько входит в комнату, гладит малыша и жестом предлагает вам пойти отдохнуть. Это один из тех моментов, когда родительство становится настоящей командной работой.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'Вы неправильно очистили банан 🍌', 'Король отговорок! Случилась настоящая трагедия, потому что банан очистили вы. Дайте новый банан и позвольте малышу очистить его так, как он хочет, даже если он разломит его пополам, — не мешайте его самостоятельности.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'Бунт из-за жары 🧥', 'Малыш снимает и бросает куртку прямо посреди улицы, а вы боитесь, что он замёрзнет? Не спорьте: когда ему действительно станет холодно, он сам придёт и попросит куртку. Позвольте ему ощутить последствия своего выбора.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'Я — стул 🪑', 'Малыш изображает какой-нибудь предмет и стоит неподвижно? Понарошку положите на него игрушку и скажите: «Какой замечательный стул!» Ему очень понравится эта необычная роль, и он спокойно постоит на месте.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'Что скажет мне сообщество? 💬', 'Вам кажется, что вы всё делаете неправильно? Загляните в Сообщество Anacan, почитайте истории других мам об их неугомонных детях, глубоко вдохните и порадуйтесь тому, какой у вас малыш!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'Полностью затемните комнату 🌙', 'Малыш не может заснуть из-за света, проникающего из коридора? Ему нужны идеальные условия. Плотно закройте дверь и полностью затемните комнату — пусть мелатонин естественным образом поможет ему уснуть.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'Беда из-за невидимого пятна 👕', 'Малыш ищет пятно на брюках, хотя там ничего нет? Снова эти зрительные причуды. Сделайте вид, что протираете это место влажной салфеткой, и скажите: «Всё, исчезло!» Детское воображение легко принимает такую игру.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'Сядьте подальше 🛑', 'Малыш требует, чтобы вы сидели не рядом с кроватью, а подальше, у двери? Не обижайтесь! Это большой шаг на пути к самостоятельности, и в глубине души вам стоит порадоваться.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'Птичка за окном — моя 🐦', 'Малыш хочет принести домой птичку со двора и плачет? Его любовь к природе не знает границ. Скажите, что дома птичку ждёт её мама, — и кризис мгновенно сменится спокойствием.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'Начинаются ночные страхи 👻', 'Малыш боится чудовища под кроватью? Налейте воду в пустой флакон с распылителем и опрыскайте комнату волшебным средством от чудовищ. Страх исчезнет за считаные секунды.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'Пусть зубы чистит мой палец 🪥', 'Малыш отказывается от зубной щётки и непременно хочет чистить зубы пальцем? Не спорьте: можно ненадолго провести процедуру чистым пальцем с небольшим количеством зубной пасты. Не раздувайте из этого проблему.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'Тайное шоколадное удовольствие 🍫', 'Пока ребёнок смотрит телевизор, вы тайком от него едите шоколад на кухне? Приятного аппетита! Чтобы выдержать столько кризисов, вам нужен этот самый естественный источник энергии. Не вините себя.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'Свобода носить футболку задом наперёд 👕', 'Малыш надел футболку задом наперёд и гордо ходит в ней? Не поправляйте! Его уверенность в себе сейчас на высоте — просто наблюдайте за этим свободолюбивым будущим лидером и гордитесь им.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'Безмолвный обмен взглядами 🥂', 'Малыш уснул, а вы с партнёром сидите на диване и молча смотрите друг на друга. Не произносите ни слова. На самом деле эта тишина — самый романтичный способ сказать: «Мы и с этим справились».'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'Меня толкнул ветер 💨', 'Малыш разозлился на ветер и хочет его ударить? Если бы вы заранее заглянули в прогноз погоды и рекомендации по одежде, возможно, вообще не вышли бы из дома. А теперь просто посмейтесь над этой комедией и бегите домой.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'Искусство на полу 🎨', 'Малыш выложил посреди комнаты картину из сухих макарон и гордо смотрит на вас? Забудьте об уборке и улыбнитесь ему.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'Папина усыпляющая сказка 📖', 'Ваш голос устал и вам не хочется читать сказку? Передайте эстафету папе. Его необычный низкий голос и придуманные им абсурдные детали убаюкают малыша ещё быстрее.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'Расчёска делает мне больно 🪮', 'Расчёсывание волос сравнимо со смертной казнью? Слегка смочите волосы водой из пульверизатора, а внимание малыша переключите на забавные гримасы, которые вы корчите перед зеркалом. Пока он отвлёкся, быстро расчешите волосы.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'Моё тело мне не принадлежит 🔋', 'После того как малыш весь день карабкался по вам, вы уже не чувствуете своего тела? Оставьте его одного в безопасной комнате на 5 минут, просто закройте дверь, прикройте глаза и глубоко вдохните. Вам нужно восстановиться.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'Не называй меня ребёнком! 😤', 'Малыш заявляет: «Я уже взрослый!» — и устанавливает для вас правила в своей комнате? Он пытается доказать, что уже вырос. Обратитесь к нему как ко взрослому: «Хорошо, юная леди/молодой человек» — и завоюйте его уважение.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'Моя цифровая терапия 🤫', 'Весь дом уснул, а в вашей голове по-прежнему шумно? Откройте шумомер. Попробуйте: вид надписи «0 децибел» успокоит вас лучше, чем сеанс у психолога.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'Укладываем игрушки спать 🧸', 'Сам малыш не ложится, зато по очереди укладывает игрушки в кровать и укрывает их? Такая ролевая игра на самом деле постепенно психологически готовит его ко сну. Не вмешивайтесь.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'Почему дверь открыли вы? 🚪', 'Малыш плачет из-за того, что дверь открыли вы, заставляет закрыть её и хочет открыть сам? Пусть это займёт 1 минуту — зато вы мирно предотвратите 20-минутный домашний бунт с криками.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'Только зелёное! 🥦', 'Малыш ищет на тарелке только зелёные продукты? Загляните в план питания, узнайте, как приготовить из зелени и овощей симпатичные зелёные шарики, и удовлетворите эту необычную страсть.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'Куда исчезло небо? ☁️', 'Неожиданный философский вопрос малыша в туманную погоду поставил вас в тупик? Скажите, что облака укрыли небо, чтобы оно не замёрзло. Его мозг ещё не готов к научному объяснению — сейчас ему просто нужна сказка.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'Побег посреди магазина 🛒', 'Перед кассой малыш внезапно убегает и прячется за стеллажами? Ведите список покупок в цифровом формате, чтобы в такие моменты паники не забыть, что вы ещё не купили, и не вернуться домой с пустыми руками.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'Игра в шёпот 🤫', 'Малыш носится с криками и не хочет спать? Внезапно замолчите, а затем начните говорить очень тихим шёпотом. Чтобы услышать вас, он сосредоточится и вскоре захочет спать.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'Я не идеальная мама 🛑', 'Сегодня всё пошло наперекосяк и вы накричали? Не загоняйте себя в угол. Просто напишите в дневнике настроения: «Сегодня был плохой день, но я хорошая мама, и завтра попробую снова».'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'Герой, придуманный папой 🦸‍♂️', 'Нет голоса и сил читать книгу? Передайте эстафету папе. Пусть он расскажет выдуманную и совершенно нелогичную историю, главным героем которой будет сам ребёнок. А вы просто прилягте на диван и слушайте доносящийся из комнаты смех.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'Упрямство с носками наизнанку 🧦', 'Надел носок пяткой вверх и ни за что не разрешает поправить? Пусть так и остаётся. Его гордость оттого, что он справился сам, в миллион раз важнее правильно надетого носка.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'Предлог сделать ещё глоток воды 💧', 'Только начинает засыпать — и вдруг вскакивает с кровати со словами, что очень хочет пить? Дело не в воде, а в желании провести с вами ещё немного времени. Заранее поставьте у кровати непроливайку с водой, чтобы предотвратить эту знаменитую манипуляцию.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'Я устала, но молчу 📝', 'Никто не замечает, сколько нервов вы сегодня потратили, а необходимость всем улыбаться уже душит? Откройте дневник настроения. Выплесните на экран всю накопившуюся злость и раздражение. Такая цифровая эмоциональная разрядка поможет вам прийти в себя быстрее, чем разговор с психологом.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'Битва за куртку 🧥', 'На улице светит солнце, но малыш не хочет надевать куртку. Не обманывайтесь видом из окна: покажите ему реальную температуру в инструменте «Погода и одежда» и изображение ребёнка, одетого в несколько слоёв. Пусть правила диктует телефон.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'Почему птичка на меня не посмотрела? 🐦', 'Разрыдался из-за того, что голубь в парке улетел? Не ищите здесь логики. Для малыша это действительно большое разочарование. С любовью признайте его чувства, сказав: «Он будет очень по тебе скучать».'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'Пусть в сказке будет моё имя 🪄', 'Надоели герои классических книг? В умных сказках замените имя главного героя именем ребёнка. Услышав, как он сам храбро укладывается спать, малыш без возражений отдастся сну.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'Сегодня я машина 🚗', 'Утром заявляет: «Я не ребёнок, я машина»? Не устанавливайте правила. Скажите: «Тогда давай заправим тебя бензином — кашей, чтобы ты мог быстро ездить». Такие забавные ролевые игры гораздо проще крика.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'Торт из песка 🏖️', 'В парке смешал воду с землёй, перепачкался в грязи и приготовил вам торт? Забудьте о чистоте. Это развивает мелкую моторику и творческие способности.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'Игра в гляделки 👀', 'Не хочет спать и нарочно смотрит на вас широко раскрытыми глазами? Сыграйте в игру «Кто первым закроет глаза, тот проиграл». Глаза начнут слезиться, малыш всё равно устанет и через 2 минуты автоматически их закроет. Попробуйте и убедитесь!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'Спрятанные в кровати игрушки 🧸', 'Легли в кровать, а под вами оказались 3 твёрдые машинки? Малыш спит, охраняя их. Не волнуйтесь: через 10 минут после того, как он уснёт, вы незаметно уберёте эти колючие предметы и обеспечите ему спокойный сон.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'Тихая поддержка в сообществе 💬', 'Вы очень устали и не хотите даже делиться с кем-то своими переживаниями? Зайдите в сообщество Anacan и просто почитайте. Увидев, как другие мамы справляются с такими же абсурдными кризисами, вы почувствуете самую сильную безмолвную поддержку.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'Кризис из-за неправильной ложки 🥄', 'Чуть не случилась революция из-за того, что вы подали суп с большой ложкой? Ближе к 4 годам физический размер предмета в представлении ребёнка меняет вкус еды, даже если сама еда осталась прежней. Не спорьте, сразу замените ложку и поберегите силы.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'Молча опуститься на диван 🥂', 'Ребёнок уснул, дома прибрано. Сядьте рядом с партнёром на диван и даже не включайте телевизор. Просто обменяйтесь взглядами, говорящими: «Мы и с этим справились, мы выжили». Поверьте, это и есть самый романтичный и настоящий момент родительства.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'Любовь к зелёному цвету 🥦', 'Ищет на тарелке только зелёные продукты, а всё остальное отодвигает? Загляните в полезные рецепты и узнайте, как приготовить из зелени и овощей симпатичные зелёные шарики.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'Почему дверь закрыли вы? 🚪', 'Устроил истерику из-за того, что при выходе из дома дверь закрыли вы, и потребовал снова её открыть? Ощущение контроля — одна из важнейших потребностей малыша. Лучше потратить на это 1 минуту, но предотвратить 30-минутный приступ плача на улице.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'Кто этот ребёнок в зеркале? 🪞', 'Стоит перед зеркалом, хмурит брови и строит сердитые и забавные гримасы? Так малыш узнаёт, как эмоции отражаются на лице. Понаблюдайте со стороны и без лишнего шума насладитесь репетицией этого маленького актёра.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'Выключите свет и найдите тень 🔦', 'Боится темноты и не хочет ложиться спать? Полностью выключите свет в комнате и включите маленький фонарик. Покажите руками на стене тени собаки и птицы. Превратите пугающую темноту в театр — так малышу будет легче уснуть.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'Шедевр на стене 🖍️', 'После нескольких секунд подозрительной тишины вы застали малыша за созданием шедевра фломастером прямо на стене? Сделайте глубокий вдох. Его мелкая моторика развивается, а стену всё равно можно отмыть. Обязательно сфотографируйте этот шедевр, прежде чем стирать его.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'Верхом на папе 🐴', 'Малыш не успел выплеснуть всю энергию и отказывается ложиться спать? Позовите папу на помощь. Когда он посадит ребёнка себе на спину и поскачет, комнату наполнят раскаты смеха, а накопившееся физическое напряжение исчезнет вместе с потом за считаные секунды.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'Пятиминутное спасение в туалете 🚪', 'От шума раскалывается голова и вам хочется на всех кричать? Оставьте малыша в безопасном месте, зайдите в туалет и закройте дверь. Просто 5 минут смотрите на стену и ничего не делайте. Эта короткая пауза в тишине поможет вам снова прийти в себя.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'Каша слишком круглая 🥣', 'Малыш сердится из-за формы еды и отказывается есть? Не ищите логики, просто перемешайте кашу ложкой и скажите: Смотри, я всё исправила. Искусство иллюзии ещё не раз пригодится вам в материнстве.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'Слёзы без всякой логики 😭', 'По дороге из парка случилась настоящая катастрофа из-за того, что малыш не успел пнуть камешек? Здесь нет логики — он просто устал. Не спорьте, возьмите его на руки, признайте его чувства и переключите внимание на что-нибудь другое.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'Секреты сказки шёпотом 🤫', 'Придумывает отговорки, лишь бы не ложиться спать? Говорите как можно тише, только шёпотом. Чтобы понять вас, малышу придётся сосредоточить всё внимание, и вскоре его мозг настроится на сон.'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'Почему ты заглушаешь мой голос? 🎶', 'Вы начали подпевать детской песенке, звучащей на фоне, а малыш тут же закричал: Не пой!? Единственный солист в комнате — он, а ваши вокальные попытки отнимают у него сцену. Не обижайтесь и уступите её этому маленькому эгоисту.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'Сам выбирает себе одежду 👗', 'Красные брюки, кроссовки и зимняя шапка... И малыш настаивает, что именно так пойдёт в парк. Не думайте о том, что скажут окружающие. Позвольте ему выйти в выбранном наряде — возможность решать самостоятельно сейчас важнее эстетики.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'Соглашение о сне по таймеру ⏱️', 'Как только приходит время спать, малыш внезапно хочет пить или начинает прощаться со стеной? Поставьте таймер. Введите правило: когда прозвенит сигнал, все ложатся спать. Детям всегда легче подчиниться такому внешнему авторитету.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'Почему Луна ещё не ушла? 🌙', 'Увидев утром Луну в небе, малыш спросил: Почему Луна ещё не легла спать? Не перегружайте его научными терминами. Откройте Anacan AI, найдите подходящую для этого возраста добрую астрономическую сказку и прочитайте её малышу, чтобы удовлетворить его любопытство.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'Ест только хлебную корочку 🍞', 'Малыш съедает только корочку, а мякиш оставляет? Вам наверняка знакомы подобные парадоксы детского питания. Не воюйте с корочками. Узнайте в плане питания, как вырезать хлеб формочками, создавая для малыша новые варианты корочек.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'Темнота для выработки мелатонина 🌌', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите все телевизоры и экраны телефонов в комнате. Мелатонин (гормон сна) активно вырабатывается только в темноте — доверьтесь естественному процессу.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'Почему игрушки не спят? 🧸', 'Сам малыш не спит, но по очереди укладывает все свои игрушки в кровать и укрывает их? Эта ролевая игра постепенно и психологически подготавливает его ко сну, поэтому не вмешивайтесь.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'Просто вдохните его запах 🫂', 'Сегодня малыш действительно свёл вас с ума и вытянул все силы? Но в кровати он спит таким невинным... Выключите свет. Лягте рядом, глубоко вдохните чистый детский запах и прошепчите ему в темноте о своей любви.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'Сказка под шум дождя 🌧️', 'Нет голоса и сил читать сказку? Включите в «Умных сказках» только звуки дождя и леса в качестве фона. Такая тишина природы порой убаюкивает быстрее самой лучшей сказки.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'Не держи меня за руку! 🚶‍♂️', 'Малыш отпускает вашу руку и хочет идти самостоятельно? Если вокруг безопасно, позвольте ему испытать свою самостоятельность, а сами с гордостью идите всего в двух шагах позади.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'Корочки хлеба — враги 🍞', 'Малыш съедает мякиш, а корочки решительно выбрасывает? Не воюйте с ними. Возьмите формочки в виде животных, вырежьте фигурки без корочек и позвольте малышу насладиться кулинарным дизайном.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'Не хочет выходить из дома ⛅', 'Четыре стены уже давят на вас, а малыш плачет и не хочет идти на улицу? Доверьтесь инструменту с рекомендациями по погоде и одежде и всё-таки выведите его погулять. Стоит ему вдохнуть свежий воздух, как вся накопившаяся дома агрессия исчезнет за секунду.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'Пижамная борьба с папой 🤼‍♂️', 'Не хочет спать? Пусть папа в шуточной борьбе одержит над ним победу у стены. Малыш выплеснет остатки энергии, вспотеет и сам побежит в кровать.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'Поддержка сообщества 💬', 'Когда терпение заканчивается, загляните в Сообщество Anacan. Увидев, что другие мамы переживают такой же хаос, вы почувствуете огромное облегчение и поймёте: «Я не одна».'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'И с этим мы справились! 🚀', 'Весь дом уснул. Вы готовы к новым приключениям следующего месяца — вы уже настоящий мастер. Выключите свет и поблагодарите себя за все маленькие чудеса, которые сотворили сегодня.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'Эта тень моя 👻', 'Малыш объявил свою тень собственностью, разговаривает с ней и отдаёт ей указания? Его воображение безгранично.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'Трещины на асфальте — это закон 🛣️', 'На улице малыш странно двигается, лишь бы не наступить на линии между камнями? Крупная моторика и внимание работают одновременно. Не торопите его: возьмите за руку и тоже перепрыгивайте через эти линии.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'Страх отверстия, куда утекает вода 🛁', 'Малыш боится сливного отверстия, когда вода уходит из ванны? Так причудливо работает его воображение. Поставьте туда игрушечный пластиковый кораблик и скажите: «Смотри, это защитник, он ничего не даст утянуть». Страх тут же сменится игрой.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'Концерт, начинающийся в 6 утра 🎤', 'Едва открыв глаза, малыш во весь голос поёт придуманную песню? Не гасите эту безумную энергию словами: «Тише, соседи проснутся». Лучше присоединитесь. Ребёнок, начинающий утро с песни, в течение дня бывает менее агрессивным.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'Танец тишины на отметке 0 децибел 🤫', 'Наконец в комнате темно, и малыш спит. В доме воцарилась такая тишина, что даже уши закладывает. Откройте в приложении «Шумомер». Наблюдать, как показатель на экране опускается до 0 децибел, — настоящий цифровой массаж для вашего распухшего от шума мозга.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'Моя игрушка на тебя обиделась 🧸', 'После вашего крика малыш подошёл и сказал: «Мой Мишка на тебя обиделся»? Так он переносит свои чувства на предметы и рассказывает о них вам. Очень серьёзно извинитесь перед Мишкой и обнимите его. Вы увидите, как малышу станет легче.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'Почему чай испаряется? ☕', 'Малыш смотрит на пар над вашей чашкой, требует объяснений или пугается? Не можете дать научное объяснение? Попросите Anacan AI придумать милый и философский ответ для 4-летнего ребёнка: «Он улетает, чтобы присоединиться к облакам».'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'Тайное нападение на список 🛒', 'Перед походом в магазин вы открыли в приложении список покупок и обнаружили там 5 шоколадок? Да, малыш уже давно научился проникать в ваш телефон и копировать действия взрослых в цифровом мире.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'Драма из-за целого яблока 🍏', 'Вы разрезали яблоко на дольки, и комнату огласил отчаянный крик? Малыш плачет: «Я хотел целое!» Не ищите логики. Сложите дольки вместе, скажите: «Смотри, я всё починила!» — и дипломатично выйдите из этой бессмысленной драмы.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'Растерянность посреди магазина 🛒', 'Зашли в магазин и забыли, что хотели купить? Если не вести список покупок в цифровом виде, в этой суматохе всё вылетит из головы. Всегда полагайтесь на цифровую память в приложении, чтобы не вернуться домой с пустыми руками.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'Ты со мной не играешь! 😤', 'Пока вы помешиваете еду, малыш подходит, поворачивает ваше лицо к себе руками и словно говорит: «Посмотри на меня!» И он прав. Ему нужно не просто ваше физическое присутствие, а безраздельное внимание. Отложите дела и всего 2 минуты слушайте его, не отводя глаз.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'Комната со звуками дождя 🌧️', 'Не хочется говорить и нет сил читать сказку? В умных сказках включите в качестве фона только звуки дождя и леса. Это монотонное спокойствие природы иногда убаюкивает быстрее самой лучшей истории.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'Называться придуманным именем 🦇', 'Проснулся утром, отказался от своего имени и потребовал: «Зови меня Бэтменом»? Подыграйте! В течение 5 минут говорите: «Пожалуйста, Бэтмен, съешь кашу» — и напряжение в комнате мгновенно превратится в комедию.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Усталость от мам из Instagram 📱', 'Не расстраивайтесь, увидев в Instagram чужих идеальных детей! Закройте это приложение и зайдите в Сообщество Anacan. Убедитесь, что у других дома такой же беспорядок, как у вас, глубоко вдохните и помните: вы не одиноки.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'Смыть водой весь стресс 🛀', 'Иногда ничего не помогает и малыш плачет из-за всего подряд. Посадите его в ванну с тёплой водой. Её удивительный успокаивающий эффект мгновенно принесёт глубокое умиротворение и всей комнате, и нервной системе малыша.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'Уходи, я тебя не хочу 💔', 'Вы отказали в просьбе, и малыш сказал: «Ты плохая мама, уходи!»? Сердце сжалось. Но он пока не умеет облекать свой гнев в слова и на самом деле говорит: «Я расстроен». Не принимайте это на свой счёт, просто обнимите его с любовью.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'Чаепитие с невидимым другом 🫖', 'Малыш наливает чай в пустоту в углу комнаты и смеётся? Начался этап воображаемых друзей!'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'Сказка, которую папа читает неправильно 📖', 'Сегодня вечером передайте книгу сказок папе. Пусть он намеренно рассказывает историю наоборот, смешно и абсурдно. А вы с удовольствием наблюдайте со стороны, как малыш радуется, поправляя его, и хохочет.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'Догонялки ранним утром 🏃‍♂️', 'В 7 утра малыш носится по диванам? Не кричите. Отложите дела на 2 минуты, начните прыгать и присоединитесь к нему. Погружение в детский мир фантазий — на удивление хороший способ снять стресс и для вас.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'Паника из-за внезапного заикания 🤖', 'Внезапное заикание у ребёнка заставило вас искать в интернете возможные заболевания? Остановитесь! Спросите у Anacan AI и узнайте, что это связано со скачком развития в 4 года, чтобы перестать паниковать.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'Цифра тишины на экране 📉', 'Наконец-то малыш уснул. В доме стало так тихо, что у вас звенит в ушах? Откройте в приложении шумомер. Надпись «0 децибел» станет лучшим визуальным массажем в мире для вашего уставшего от шума мозга.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'Скандал из-за очищенного вами банана 🍌', 'В комнате разразилась настоящая революция из-за того, что вы очистили банан? Золотое правило этого возраста: малыш должен решать всё сам. Приклеить кожуру обратно не получится, поэтому дайте новый банан и позвольте очистить его самостоятельно, как хочется, чтобы не задеть стремление к независимости.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'Канатоходец на краю тротуара 🧱', 'По дороге в парк малыш не хочет идти по ровной дорожке и непременно выбирает самый узкий край тротуара? Подстрахуйте его, придерживая за руку, и позвольте покорить эту маленькую вершину. Так одновременно прекрасно развиваются равновесие и уверенность в себе.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'Уделять время себе — не эгоизм 🥗', 'Вы придумали разные блюда, чтобы накормить малыша, но что поели сами? Приготовьте тот самый простой салат для мам за 5 минут из раздела полезных рецептов и наконец не забудьте восполнить собственные силы.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'Молчаливый взгляд друг на друга 🥂', 'Ребёнок уснул. Вы с партнёром сидите на диване и молча смотрите друг на друга. Ничего не говорите. На самом деле эта тишина — самый романтичный и искренний способ сказать: «Мы и с этим справились. Мы отличная команда».'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'Отказ от куртки 🧥', 'Не хочет надевать зимнюю куртку, потому что на улице светит солнце? Откройте раздел с погодой и одеждой и покажите на телефоне значок ребёнка в зимней одежде. Перенесите правило на цифровой экран и отойдите в сторону — малыш спокойно оденется.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'Разговор по душам шёпотом в темноте 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо прошепчите ему на ухо о том, что произошло за день, или о черте его характера, которая вам особенно нравится. Шёпот — один из самых волшебных способов подготовить мозг ко сну.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', 'Ложь «Это не я» 🤥', 'Намеренно разлил воду, а потом показал пальцем на машинку и сказал: «Это она толкнула»? Это не ложь, а защитный механизм. Скажите: «Давай научим машинку убирать за собой» — и ловко переключите его внимание.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'Дипломатия на горке 🤝', 'Толкнул другого ребёнка на горке, чтобы прокатиться самому? Не ругайте и не бейте малыша из-за чувства неловкости. Мягко, но твёрдо напомните правило: «Сейчас его очередь, потом — твоя». Так он научится соблюдать социальные нормы.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'Чтобы яйцо не плакало 🍳', 'Ему стало жалко яйцо, когда вы его разбили, и теперь он отказывается есть? Его эмпатия не знает границ. Быстро спасите ситуацию милой выдумкой: «Теперь оно поселится в твоих мышцах и сделает тебя сильнее».')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1'::uuid, 'Правильное расположение подушек 🛏️', 'Плачет, потому что подушка лежит не идеально ровно? У него появились особые ритуалы перед сном. Примите его правила, поправьте подушку, будто вымеряя её линейкой, уверенно выключите свет и дайте малышу почувствовать себя в безопасности.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'Верни мусор, который я выбросил! 🗑️', 'Случилась настоящая катастрофа, потому что вы выбросили старую обёртку от шоколада, которую он хранил? Для вас это мусор, а для него — сокровище. Переключите его внимание на другую яркую игрушку.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'Домашний диктатор за столом 👑', 'За завтраком командует: «Сядь не туда, а сюда» — и руководит всеми за столом? Не подавляя его волю, с лёгкой улыбкой скажите: «Хорошо, пусть будет по-твоему», чтобы сохранить равновесие и мир в доме.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'Ничего никому не объяснять 📝', 'Никто не замечает, как сильно вы устаёте дома, и это доводит вас до предела? Откройте дневник настроения. Запишите туда всё, что сегодня вывело вас из себя. Признать свои эмоции и изложить их на бумаге будет гораздо полезнее.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'Час тихого чтения 📖', 'Сегодня вечером читать не будем. Включите спокойную фоновую музыку из умных сказок и просто молча рассматривайте картинки. Мозг утомится от зрительной активности, и малыш уснёт, а вам не придётся произнести ни слова.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'Испытание у кассы супермаркета 🛒', 'Кричит и требует шоколад прямо у кассы? Не сдавайтесь, несмотря на взгляды людей в очереди. Откройте список покупок и скажите: «Здесь шоколада нет, касса его не пропустит». Если вы будете непреклонны, малыш тоже отступит.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'Есть ртом, а не руками 🐶', 'Хочет есть из тарелки, как кошка, не используя руки? Не запрещайте. На кухне всё равно придётся убирать — пусть 5 минут побудет кошкой. Такая забавная ролевая игра — самый весёлый способ справиться с отсутствием аппетита.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'Массаж плеч от папы 💆‍♂️', 'Сегодня вы долго были на ногах, бегали за малышом и собирали с пола игрушки, поэтому спина просто отваливается. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — двигатель этого дома, и вам обязательно нужно восстановиться.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'Полная темнота в комнате 🌌', 'Не может уснуть из-за света, проникающего из коридора? Он стремится к идеальным условиям. Плотно закройте дверь и полностью затемните комнату — пусть мелатонин сделает свою естественную работу и поможет малышу быстро уснуть.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'Кризис «Это моё!» 🧸', 'Прижимает к себе домашний пульт и заявляет: «Это моё!»? Он проверяет границы собственности. Не называйте его эгоистом. Скажите: «Спасибо, что нашёл его для меня», переключите внимание на другую игру и заберите пульт.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'Смысл незаконченных фраз 🗣️', 'Забыв слово, показывает жестами и ждёт, что вы догадаетесь? Терпеливо закончите за него фразу и посмотрите, какое облегчение появится на его лице. Именно так, с вашей поддержкой, он расширяет словарный запас и обретает уверенность в себе.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'Катастрофическая помощь на кухне 🧑‍🍳', 'Пока вы раскатываете тесто, малыш подставляет стул и непременно хочет сам насыпать муку? Если не разрешить, расплачется. Дайте ему маленькую пластиковую миску и немного муки. На кухне будет беспорядок, зато его самолюбие будет удовлетворено.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'Луна бежит за нами 🌕', 'По дороге домой малыш смотрит вечером из окна машины и говорит, что Луна следует за вами? Он думает, что Вселенная вращается вокруг него. Не разрушайте эту фантазию, а включитесь в игру, спросив: «Интересно, куда это она едет вместе с нами?»'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'Любовь к грязной футболке 👕', 'Малыш уже 3 дня носит одну и ту же футболку и не разрешает её стирать? В этом возрасте некоторые вещи дают детям чувство безопасности. Не спорьте. Заберите футболку, придумав сказку: «Я отправила её в волшебное приключение в стиральной машине, и она вернётся ещё сильнее». Малыш поверит в эту маленькую иллюзию.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'Траур по муравью 🐜', 'Малыш увидел в парке муравья, замер на месте и плачет, потому что тот заблудился? Его сочувствие не знает границ. Скажите, что мама муравья сейчас придёт и заберёт его.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'Белый шум на болотах 🌊', 'Вместо того чтобы спать, малыш скачет по всей комнате? Включите в шумомере громкий звук морских волн или белый шум. Эта монотонная частота смоет безумную энергию в его мозге, и через 10 минут глаза начнут закрываться.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'Катастрофическая помощь с веником 🧹', 'Пока вы убираетесь, малыш приходит со словами «Я сам!» и разносит мусор по всей комнате? Если не разрешить, разразится буря. Дайте ему влажную салфетку и скажите: «Ты отвечаешь только за этот угол стола». Так и вы сделаете своё дело, и его самолюбие останется довольно.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'Время смотреть на пустую стену 🛋️', 'Малыш самостоятельно играет в комнате? Ради всего святого, не тратьте этот момент на мытьё посуды! Сядьте на диван, возьмите чай и просто смотрите на стену. Да, ни о чём не думая. Запишите в дневник настроения 5 минут покоя. Вам это необходимо.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', 'Драма «У меня сломались волосы!» 🪮', 'Увидев расчёску, малыш говорит, что у него болят волосы, и убегает? Его пугает сенсорная чувствительность. Отвлеките внимание. Дайте ему зеркало и предложите: «Давай посмотрим, кто смешнее покажет язык в зеркале?» Пока он занят, расчешите волосы за считаные секунды — и готово.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'Внезапный приступ философии 🤔', 'Малыш неожиданно задал научный вопрос: «Почему на дне моря темно?» Не паникуйте! Откройте Anacan AI, получите самый понятный для этого возраста сказочный ответ, одобренный педиатром и психологом, и прочитайте его малышу. Вы — мама, которая всегда всё знает!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'Догонялки в тёмной комнате 🔦', 'Пора спать, но энергия малыша никак не иссякнет? Выключите в комнате весь свет. Возьмите маленький фонарик и поиграйте в игру «Посмотрим, кого поймает свет на стене». Игра в темноте ускорит выработку мелатонина и поможет малышу устать.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'Страдания из-за невидимой ранки 🩹', 'На пальце ничего нет, но малыш плачет, говорит, что поранился, и просит пластырь? Дело не в физической боли — ему нужны ваши сочувствие и забота. Наклейте пластырь, поцелуйте пальчик и скажите: «Я вылечила его волшебным поцелуем». И ваш день будет спасён.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'Закрытая дверь и личное пространство 🚪', 'Малыш зашёл в свою комнату, закрыл за собой дверь и сказал: «Не заходи»? Не обижайтесь. Он просто хочет отгородиться от шума и хаоса и немного отдохнуть. Если всё безопасно, позвольте ему насладиться личным пространством. Он взрослеет!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'Бесконечные ночные отговорки 🚰', 'Глаза уже закрываются, но малыш вдруг вскакивает со словами: «У меня чешется нога», «Я хочу воды»? Он настоящий профессор по откладыванию сна. Установите таймер. Скажите, что, когда телефон зазвонит, все отговорки отправятся спать. Передайте полномочия телефону, а сами отойдите в сторону.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'Это не моё имя 📛', 'Малыш говорит: «Не называй меня по имени, я Человек-паук»? Это поиск собственной личности. Подыграйте! Подайте завтрак со словами: «Прошу, господин Паук». В ваших силах за секунду превратить напряжение в комнате в комедию.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'Шантаж списком в магазине 🛒', 'У кассы малыш внезапно потребовал конфету? Совершенно не обращайте внимания на осуждающие взгляды окружающих. Откройте список покупок, скажите: «Этого нет в списке, поэтому касса нам это не продаст», — и твёрдо стойте на своём.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'Краски вышли за пределы бумаги 🖍️', 'Вы вошли в комнату и увидели на стене новую фреску? Сделайте глубокий вдох. Малыш вышел за границы бумаги и проверяет свою моторику в более крупном масштабе. Прежде чем стирать шедевр, обязательно сфотографируйте его, чтобы в будущем показать ребёнку и вместе посмеяться.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'Экранное подтверждение тишины 📉', 'Наконец-то малыш уснул. В ушах всё ещё звенят крики? Откройте шумомер. Наблюдение за тем, как линия опускается до 0 desibel, станет лучшим визуальным массажем в мире для вашего уставшего и перегруженного мозга.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'Папина выдуманная сказка 🦸‍♂️', 'Нет сил говорить и не хочется читать книгу? Поручите сказку папе. Пусть он сочинит нелепую и забавную историю, главным героем которой будет сам ребёнок. А вы прилягте у стены, отдохните и посмотрите, как малыш хохочет над папиным рассказом.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'Эта еда неправильной формы 🥒', 'Малыш отодвинул тарелку, потому что вы нарезали огурец не кружочками, а полосками? Его представления об эстетике еды активно формируются. Узнайте, как замаскировать тот же овощ, превратив его в забавные фигурки. Вы победите в этой дизайнерской игре.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'Побег в ванную ради уединения 🛀', 'Малыш весь день цепляется за ваши ноги, и от постоянных прикосновений тело словно онемело? Сенсорная перегрузка от прикосновений реальна. Оставьте его в комнате, зайдите в ванную на 5 минут, закройте дверь и просто подышите. Вам необходимо восстановиться.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'Песни собственного сочинения 🎤', 'Солнце ещё не взошло, а малыш уже скачет и громко поёт песню из бессмысленных слов? Не кричите и не заставляйте его замолчать. Ребёнок, начинающий утро с песни, выплёскивает свою агрессию. Присоединитесь к этой безумной энергии хотя бы на 1 минуту — сон как рукой снимет.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Безупречные мамы из Instagram 📱', 'Открыли Instagram, увидели у всех идеальный порядок дома и послушных детей и сразу приуныли? Удалите это приложение! Присоединяйтесь к Сообществу Anacan. Читайте истории настоящих мам, у которых дома такой же беспорядок, а дети такие же упрямые, как у вас, и выдохните.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'Сон, пришедший с шёпотом 🤫', 'Малыш убегает из кровати и скачет из стороны в сторону? Внезапно понизьте голос почти до полной тишины. Начните говорить очень тихим шёпотом. Чтобы понять вас, ему придётся сосредоточиться, и уже через 5 минут мозг устанет и переключится в режим сна. Попробуйте!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'Игрушка, найденная в холодильнике 🧊', 'Открыли холодильник и нашли внутри резиновую машинку? Это игра, в которой малыш тренирует память и проверяет, что происходит с предметом в необычном месте. Не сердитесь: эта забавная нелепость — часть его развития.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'Не хочет выходить из дома ⛅', 'Дома всё вверх дном, а малыш лежит на диване, плачет и твердит, что никуда не пойдёт? Откройте раздел погоды и одежды, проверьте, сколько градусов на улице, подберите подходящий комплект и всё же отведите его в парк. Как только свежий воздух коснётся его лица, вся агрессия улетучится.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'Когда малыш становится героем сказки 🪄', 'Откройте умные сказки. Замените имя главного героя на имя своего ребёнка. Читайте о том, как этот герой смело и послушно отправился спать. Услышав себя в этой истории, малыш закроет глаза без всяких возражений.'),
  ('139226ae-9370-42b4-954a-012623528599', 'Непонятный плач посреди ночи 😭', 'Малыш проснулся посреди ночи, плачет с закрытыми глазами и не слышит вас? Проверьте с помощью анализа плача: скорее всего, это ночной страх. Постарайтесь не будить его, просто оставайтесь рядом и держите за руку. Он сам успокоится и снова уснёт.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'Мамин тайный шоколадный час 🍫', 'Тайком от малыша едите шоколад, спрятавшись за шкафом? Приятного аппетита! Эта глюкоза — ваше естественное право и заслуженная поддержка, помогающая выдерживать бесконечные «почему», крики и восстанавливать силы. Никогда не вините себя за это.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'Догонялки с тенью 🏃‍♂️', 'Во время прогулки малыш внезапно побежал, пытаясь поймать собственную тень? Воображение пока опережает его логику. Не останавливайте его — попробуйте поймать свою тень и присоединитесь к этой безумной и весёлой игре прямо посреди улицы. Жизнь не настолько длинна, чтобы относиться к ней слишком серьёзно.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'Синдром перепутанной обуви 👟', 'Малыш надел правый ботинок на левую ногу, а левый — на правую и не позволяет исправить? Пусть так и остаётся! Его гордость от того, что он сам обулся, и чувство самостоятельности в миллион раз ценнее того, правильно ли надета обувь.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'Выплеснуть гнев в цифровой дневник 📝', 'Никто не замечает, как сильно вы сегодня устали, а необходимость улыбаться буквально душит? Откройте дневник настроения. Выплесните на экран всю накопившуюся горечь и усталость. Фраза «Я выгорела» поможет вам восстановиться быстрее, чем притворное совершенство.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'Массаж плеч от папы 💆‍♂️', 'Сегодня вы долго были на ногах, и теперь от беготни за малышом и собирания игрушек с пола у вас разламывается спина. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — двигатель этого дома, а двигателю обязательно нужны отдых и восстановление.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'Требование высушить воду 💧', 'Вместо того чтобы выпить воду из стакана, малыш кричит: «Она слишком мокрая, высуши её»? Не ищите логики: перелейте воду в стакан другого цвета и скажите: «Я принесла сухую воду». Искусство иллюзии — ваше главное оружие в материнстве.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'Обязательная прогулка на природе ⛅', 'В четырёх стенах его энергия превращается в агрессию, а каждое предложение начинается со слова «нет»? Оденьте малыша по погоде и обязательно выведите на улицу. Прикосновение к земле поможет его нервной системе быстро перезагрузиться.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'Автоматический сон по звонку ⏱️', 'Как только приходит время спать, малыш вдруг хочет в туалет? Поставьте таймер. Введите правило: «Когда звенит звонок, все выключают свет» — и без споров положите конец бесконечным прощаниям и умелым попыткам оттянуть сон.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'Прятки за дверью 🙈', 'Вы опаздываете в детский сад, а малыш спрятался за занавеской и говорит: «Найди меня!»? Крик только затянет процесс. Скажите: «Интересно, где же мой малыш?», включитесь в игру на 2 минуты и со смехом выведите его из укрытия.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'Звуковые эффекты в умной сказке 🪄', 'Включите умные сказки. Во время чтения изобразите скрип двери, шум ветра и шёпот, устроив в комнате настоящий звуковой театр. Эти необычные звуки мгновенно погрузят малыша в мир сказки.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'Передышка с экраном без чувства вины 📺', 'Сегодня у вас было много дел, поэтому малыш слишком долго смотрел телевизор? Вас мучает чувство вины? Невозможно быть идеальной каждый день. Иногда экран — самая безобидная няня, спасающая нас от большого хаоса. Расслабьтесь.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'Художник, разорвавший свою работу 🖍️', 'Малышу не понравилась нарисованная линия, и он со словами «Плохо получилось» разорвал и выбросил лист? Так проявляются самокритика и стремление к совершенству! Скажите: «Давай в следующий раз попробуем другой цвет» — и превратите его разочарование в исследование.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'Ластиться, как кошка 🐾', 'Сегодня утром малыш ходит на четвереньках, трётся о ваши ноги и только мяукает? Вместо того чтобы читать ему нотации, протяните воображаемую миску с молоком. Играть всегда проще и веселее, чем ругать.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'Мини-лаборатория в ванной 🛀', 'Малыш добавляет в воду разноцветное мыло и готовит зелье? Да, в ванной будет беспорядок. Зато он узнаёт, как растворяются разные вещества. Такое научное исследование поможет снять вечернее напряжение и подготовит его к спокойному сну.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'Спектакль «Кто вы?» 🎭', 'Малыш смотрит на вас как на незнакомку и спрашивает: «Кто вы? Где моя мама?» Это новая ролевая игра. Скажите: «Я тётя-врач, пришла послушать твоё сердце» — и пощекочите его. Пусть с самого утра комната наполнится смехом.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'Искусство из туалетной бумаги 🧻', 'Вы вошли в комнату и увидели, что вся туалетная бумага размотана по дому? Вместо того чтобы сердиться, соберите её вместе и сделайте большой шар. Побеждайте хаос не криком, а творчеством и смехом.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'Наслаждение тишиной 🤫', 'Наконец-то малыш уснул. В доме стало так тихо, что у вас звенит в ушах? Откройте в приложении шумомер. Надпись «0 децибел» станет лучшим визуальным массажем в мире для вашего уставшего от шума мозга.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'Стакан не того цвета 🥤', 'В комнате разразилась буря из-за того, что вы налили воду в жёлтый стакан? Не усложняйте: сегодня утром малыш просто проверяет границы. Тут же перелейте воду в синий стакан, восстановите мир и поберегите свои силы.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'Просто прижать к груди 🫂', 'Сегодня малыш действительно свёл вас с ума и высосал все силы? Но в кровати он спит так невинно... Выключите свет, не читайте сказку. Лягте рядом, глубоко вдохните этот чистый детский запах и поблагодарите жизнь.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'Истории других мам 💬', 'Не расстраивайтесь, увидев в Instagram чужих идеальных детей! Закройте это приложение и зайдите в Сообщество Anacan. Увидев, что в домах других мам такой же беспорядок, как у вас, глубоко вдохните.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', 'Самостоятельность: «Не держи меня за руку!» 🚶‍♂️', 'Малыш вырывает руку и хочет идти сам? Если вы находитесь в безопасном месте, позвольте ему проверить свою самостоятельность. Просто идите в двух шагах позади и с гордостью наблюдайте за этим маленьким свободолюбивым бунтарём.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'Почему вы сами почистили банан?! 🍌', 'В комнате разразилась революция из-за того, что вы сами почистили банан? Золотое правило этого возраста: малыш должен всё решать сам. Приклеить кожуру обратно не получится, поэтому сразу дайте новый банан и позвольте малышу почистить его так, как хочется. Споры лишь отнимут у вас время.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'Тишина вдвоём 🥂', 'Ребёнок уснул, дома порядок. Сядьте с партнёром рядом на диване и даже не включайте телевизор. Просто обменяйтесь взглядами: «Мы и с этим справились, мы выжили». Вот он — самый романтичный и по-настоящему командный момент родительства.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'Маленький домик под столом ⛺', 'Малыш забрался под обеденный стол, устроил там домик и хочет обедать только в нём? Проявите гибкость. Передайте суп в это тёмное убежище. Смена обстановки способна пробудить аппетит даже у самого привередливого ребёнка, превратив еду в приключение.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'Вы со мной не играете! 😠', 'Пока вы смотрели в телефон, малыш подошёл, повернул ваше лицо к себе руками и потребовал: «Смотрите на меня!»? Он прав. Ему нужно не просто ваше физическое присутствие, а безраздельное внимание. Отложите телефон, 3 минуты поддерживайте зрительный контакт — и малыш сразу успокоится.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'Канатоходец на краю тротуара 🧱', 'По дороге в парк малыш хочет идти не по ровной дорожке, а непременно по самому узкому краю тротуара? Подстрахуйте его за руку и позвольте покорить эту маленькую вершину. Так одновременно прекрасно развиваются равновесие и уверенность в себе — не мешайте малышу.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'Звуковые эффекты в комнате 🪄', 'Сегодня вечером вы устали читать? Включите «Умные сказки». Пока звучит история, устройте в комнате звуковой театр: изображайте скрип двери, шум ветра и шёпот. Эти необычные звуки мгновенно увлекут малыша в мир сказки.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'Соревновательный способ уйти из парка 🌳', 'Пора уходить из парка, а у малыша началась истерика. Уводить его силой не поможет. Скажите: «Посмотрим, кто быстрее допрыгает до машины, как зайчик?» — и сразу переключите внимание на забавное соревнование. Малыш непременно включится в игру.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'Просто вдохните его запах 🫂', 'Сегодня малыш действительно сводил вас с ума и вытянул все силы? Но во сне он такой невинный... Выключите свет. Лягте рядом, глубоко вдохните этот чистый детский запах и прошепчите малышу, как он вам дорог.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'Дайте воду в другом стакане! 🥤', 'В комнате разразилась буря из-за того, что вы налили воду в жёлтый стакан? «Я хотел синий!» — говорит малыш. Не усложняйте: он просто проверяет границы. Сразу перелейте воду в синий стакан, восстановите мир и поберегите свои силы.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'Динозавры не едят кашу! 🦖', 'Утром малыш не отвечает ни на один вопрос, а только рычит? Сегодня он — тираннозавр. Подыграйте придуманному образу и спросите: «А тираннозавры едят завтрак?» Так малыш мирно сядет за стол без слёз.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'Ступор посреди магазина 🛒', 'Зашли в магазин и забыли, что хотели купить? Мамина голова и правда перегружена. Откройте в приложении «Список покупок» и доверьтесь этой цифровой памяти — она всегда поможет вам не вернуться домой с пустыми руками.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'Выключите свет — пусть приходит сон 🌙', 'Чтобы малыш быстрее заснул, за 1 час до сна выключите телевизор и уберите все телефоны и другие экраны. В темноте мелатонин вырабатывается активнее — позвольте естественному процессу сделать свою работу.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'Это не мусор, а произведение искусства 🎨', 'Малыш создал посреди комнаты грандиозное произведение искусства из сухих макарон и обрывков бумаги? Отложите стремление к идеальной чистоте. Это прекрасное занятие для развития крупной моторики, достойное отметки в «Трекере развития». Дом — не музей.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'Цифра тишины на экране 📉', 'Наконец-то малыш уснул. В доме стало так тихо, что у вас звенит в ушах? Откройте в приложении «Шумомер». Вид надписи «0 децибел» станет лучшим визуальным массажем для вашего уставшего от шума мозга.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'Заканчивайте незавершённые фразы 🗣️', 'Забыв слово, малыш показывает его жестами и ждёт, пока вы догадаетесь? Его словарный запас растёт, но мысли пока опережают речь. Терпеливо закончите фразу и полюбуйтесь облегчением на лице малыша: «Да-а, именно это я и хотел сказать!»'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'Борьба с папой на диване 🤼‍♂️', 'Малыш убежал и спрятался, лишь бы не ложиться спать? Передайте эстафету папе. Пусть они понарошку поборются на диване. Эта шумная, активная игра с папой выплеснет последние остатки неукротимой энергии, и малыш легко сдастся сну.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'Искусство прятать овощи 🥦', 'Нашёл в супе ту единственную морковку и заявил: «Я это не буду»? Измельчите овощи в пюре и добавьте в соусы — посмотрим, как он теперь их найдёт! Ловко перехитрите этого маленького кулинарного эксперта.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'Я хочу летать! 🕊️', 'Прыгает с дивана, машет руками и сердится на вас из-за того, что не взлетает? Объяснять ему законы физики пока рано. Скажите: «Ты не летаешь, потому что твои крылья ещё растут» — и предложите попрыгать на что-нибудь мягкое.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'Критика собственного рисунка 🖍️', 'Ему не понравилась нарисованная линия, и он со словами «Плохо получилось» порвал и выбросил лист? У него формируются самокритичность и стремление к совершенству! Скажите: «Давай в следующий раз попробуем другой цвет» — и превратите его разочарование в новое открытие, поддержав малыша.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'Тихое утешение в сообществе 💬', 'Вы так устали, что даже не хотите ни с кем делиться переживаниями? Зайдите в Сообщество Anacan и просто почитайте. Увидев, как другие мамы справляются с такими же абсурдными кризисами, вы почувствуете сильную безмолвную поддержку.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'Океанский шторм в ванне 🌊', 'Купание — лишь предлог, а на самом деле он устроил в ванне целый океан и играет с волнами? Пусть играет. Шум и брызги воды помогут выплеснуть его неиссякаемую упрямую энергию. А вечером он ляжет спать без всякого сопротивления.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'Внезапная утренняя философия 🤔', 'Вдруг задал научный вопрос: «Почему ветер не видно?» Не паникуйте! Откройте Anacan AI, получите самый милый, понятный для его возраста сказочный ответ, одобренный педиатром и психологом, и прочитайте малышу. Вы — мама, которая всегда всё знает!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'Просто спокойно полежать 🛋️', 'Он сам собирает пазл, и дома внезапно стало тихо? Ради всего святого, не тратьте этот момент на уборку! Лягте на диван. Вам тоже нужно зарядить батарейку, чтобы выдержать такой темп до вечера. Обязательно отдохните.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'Сокровища из карманов 🪨', 'Во время стирки вы нашли в кармане его брюк засохший лист или камешек? Это не жадность, а детская тяга к исследованиям. С серьёзным видом выбросьте находку, но в душе улыбнитесь своему маленькому собирателю — он познаёт мир.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', 'Скандал «Это моё!» 🧸', 'Прижимает к себе пульт и заявляет: «Это моё!»? Он проверяет границы собственности. Не называйте его эгоистом. Скажите: «Спасибо, что нашёл его для меня», переключите внимание на другую игру и осторожно заберите пульт.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'Звонок прозвенел — пора спать ⏱️', 'Укладывание спать затягивается всё дольше. Вода, туалет, прощание со стеной... Установите таймер на телефоне. Введите правило: когда раздаётся звонок, все выключают свет. Подчиниться внешнему авторитету детям всегда проще.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'Не отчитывайтесь ни перед кем 🛑', 'Сегодня ваше терпение лопнуло и вы повысили голос? Не наказывайте себя. Запишите в дневнике настроения: «Я хорошая мама, просто сегодня я очень устала». Будьте добрее к себе — никто не ждёт от вас совершенства.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'Энергетический заряд для мамы 🥗', 'Вы придумали разные блюда, чтобы накормить малыша, но что поели сами? Найдите среди полезных рецептов простой салат для мам, который готовится всего за 5 минут.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'Горячий чай в тишине ☕', 'Малыш наконец уснул. Посмотрите на разбросанные посреди комнаты игрушки и глубоко вдохните. Не убирайте их сейчас! Налейте себе горячего чая, сядьте на диван и просто насладитесь покоем, который дарит вам эта тишина.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'Долгие разговоры с неодушевлёнными предметами 🗣️', 'Он совершенно серьёзно что-то рассказывает камню в парке или стулу дома? Через игру малыш усваивает правила и познаёт мир.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'Отказ надевать куртку 🧥', 'Не хочет надевать зимнюю куртку, потому что на улице светит солнце? Не обманывайтесь видом из окна. Откройте раздел «Погода и одежда» и покажите на телефоне значок ребёнка в зимней одежде. Пусть правило озвучит цифровой экран, а вы останетесь в стороне.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'Прятки под кроватью 🛏️', 'Хочет спать не в кровати, а непременно под ней? Такие маленькие закрытые пространства дают детям чувство защищённости, словно в утробе матери. Разрешите малышу, а когда он уснёт, осторожно переложите его наверх. Берегите свои силы.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'Уложить спать без сказки 🪄', 'Сегодня вечером у вас нет сил читать сказку? Включите «Умные сказки». Оставьте фоном только звуки шепчущего леса и ветра. Слушая в темноте звуки природы, вы оба отдохнёте от шума. Зрительная усталость пройдёт вмиг.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'Выплеснуть гнев на бумагу 📝', 'Никто не замечает, как сильно вы устаёте дома, и вас это выводит из себя? Откройте дневник настроения. Запишите туда всё, что сегодня довело вас до белого каления. Признать свои эмоции и описать их будет гораздо полезнее, чем натягивать на лицо улыбку.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'Я знаю — сейчас и вас научу ☝️', 'Малыш с очень серьёзным и умным видом объясняет вам то, что вы и так знаете? Он проверяет свои знания. Прикусите губу, чтобы не рассмеяться, но выслушайте его со всей серьёзностью и скажите: «Правда? Большое спасибо». Потешьте его самолюбие.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'Потоп в ванной 🌊', 'Купание — лишь предлог, а на самом деле малыш устроил в ванной океан и играет с волнами? Пусть играет. Шум и плеск воды помогут выплеснуть его нескончаемую упрямую энергию. Вечером он ляжет спать без всякого сопротивления.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'Малыш помогает вам на кухне 🧑‍🍳', 'Пока вы раскатывали тесто, малыш подставил стул и непременно захотел сам насыпать муку? Не разрешите — расплачется. Дайте ему небольшую пластиковую миску и немного муки. На кухне будет беспорядок, но его серьёзное выражение лица настоящего повара того стоит.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'Застыть посреди магазина 🛒', 'Вы остановились посреди магазина и задумались: «Что же я хотела купить?» Голова мамы и правда переполнена заботами. Откройте в приложении список покупок и доверьтесь этой цифровой памяти — она всегда выручит вас в таком хаосе.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'Бирка на футболке колется! 🏷️', 'Малыш отказывается это надевать, потому что маленькая бирка сзади колется, как иголка? Сенсорная чувствительность в этом возрасте порой сводит с ума. Не спорьте, просто возьмите ножницы, срежьте бирку под корень и за секунду положите конец этому мини-кризису.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'Минута идеальной тишины 🛋️', 'Малыш так увлечённо собирает пазлы, что в доме внезапно стало тихо? Не ищите подвоха — сразу налейте себе кофе. Потратьте эти редкие золотые минуты не на уборку или стирку, а на отдых: расслабьтесь и просто посмотрите в потолок. Вы не робот.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'Внезапный крик посреди ночи 😭', 'Малыш проснулся ночью, плачет с закрытыми глазами и не слышит вас? Судя по характеру плача, это ночной ужас. Не пытайтесь его разбудить — просто побудьте рядом, возьмите за руку и погладьте. Он сам успокоится и снова погрузится в глубокий сон.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Вам письмо от Anacan 💌', 'Овощи, спрятанные в полезных блюдах, слёзы, излитые в дневнике настроения, и минуты полного истощения... За эти 4 года вы освоили самую сложную профессию в мире. Теперь вы героиня, которой уже не нужно ни одно приложение: вы умеете управлять хаосом, доверяя собственной интуиции. Мы были лишь вашим незримым проводником, а всю главную работу проделали вы!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', '1460-й день: Мы справились! 🚀', 'Утром вы просыпаетесь и смотрите на малыша... Ему уже исполнилось 4 года! Ровно 1460 дней вы растили этого маленького человека, справляясь с бессонными ночами, кризисами и упрямством. За эти годы вы вырастили не только ребёнка, но и новую себя — сильную, несокрушимую маму. Сегодня никаких правил: просто обнимите малыша и с гордостью посмотрите на это чудо, которое создали вы сами.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'Последнее уведомление, последняя тишина 🌌', 'Малыш уснул. Выключите свет. Это последнее уведомление, которое вы получаете от приложения. На протяжении 1460 дней, когда вы уставали, плакали и чувствовали себя загнанной в угол, мы старались понять вас и молча быть рядом. Теперь отложите телефон. Вы прекрасны. Вы достаточно хорошая мама. Следующую удивительную историю вы напишете сами. Для нас было честью пройти этот путь вместе с вами. До встречи, Anacan! ❤️'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'Ледяная нелогичность 🥶', 'Требует обязательно бросить в горячий чай лёд, вместо того чтобы подуть на него? Так малыш изучает противоположность горячего и холодного. Дайте ему лёд и позвольте понаблюдать, как он тает. Пусть завтрак немного задержится — зато малыш совершит своё научное открытие.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'Комната сказок под шум дождя 🌧️', 'Пропал голос и нет сил читать сказку? В умных сказках включите в качестве фона только звуки дождя и леса. Порой это монотонное спокойствие природы убаюкивает и погружает в сон быстрее самой лучшей и увлекательной истории.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'Сердится на себя в зеркале 🪞', 'Стоит перед зеркалом, издаёт разные звуки и строит рожицы? Это признак развития самосознания. Малыш изучает своё тело и проверяет, как его эмоции выглядят со стороны. Просто тихонько понаблюдайте.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'Бунт против прикосновений 🔋', 'Весь день цепляется за ваши ноги и просится на руки? Вы физически истощены и устали от постоянных прикосновений. Оставьте малыша в комнате с игрушками, на 5 минут зайдите в ванную и закройте дверь. Просто побудьте немного в одиночестве.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'Спор на детской площадке 🤝', 'Толкнул другого ребёнка на горке, чтобы прокатиться самому? Все смотрят на вас. Не бейте малыша из-за чувства стыда. Мягко, но твёрдо напомните ему правило: «Сейчас его очередь, а потом прокатимся мы». Так это работает.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'Утренние догонялки 🏃‍♂️', 'В 7 утра бегает по диванам? Не кричите. Отложите дела на 2 минуты и присоединитесь к нему, весело прыгая. Погружение в мир детской фантазии может показаться странным, но это очень эффективный способ снять стресс и для вас.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'Научное решение ночных страхов 🔦', 'Боится теней в спальне? Не оставляйте комнату в полной темноте — включите небольшой ночник с тёплым светом. Он не нарушит выработку мелатонина, но даст малышу ощущение безопасности и поможет справиться со страхом.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'Внезапное «Я тебя люблю» 💖', 'Посреди игры малыш вдруг смотрит на вас, подбегает и обнимает за шею. Ради этого стоили все бессонные ночи и усталость! Насладитесь глубоким, неповторимым умиротворением этого мгновения и забудьте о хаосе вокруг.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'Мистическая сила шёпота 🤫', 'Убегает из кровати и скачет по всей комнате? Внезапно понизьте голос до предела. Начните говорить очень тихим шёпотом. Чтобы понять вас, малышу придётся сосредоточиться, и уже через 5 минут его мозг устанет и переключится в режим сна. Попробуйте!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Иллюзия мам из Instagram 📱', 'Открыли Instagram, увидели у всех идеальный порядок и послушных детей и расстроились? Удалите это приложение! Присоединяйтесь к сообществу Anacan. Читайте истории реальных мам, у которых дома такой же беспорядок, а дети так же упрямятся.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'Папина сказка, навевающая сон 📖', 'Голос устал и нет сил читать сказку? Передайте эстафету папе. Его непривычный низкий голос и придуманные им нелепые детали заворожат малыша и убаюкают быстрее, чем ваш знакомый голос.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', 'Спектакль «Ты кто?» 🎭', 'Утром малыш посмотрел на вас как на незнакомку и спросил: «Ты кто? Где моя мама?» Это новая ролевая игра. Ответьте: «Я ваша соседка, а мама скоро придёт». Пусть с утра комната наполнится смехом — это сбережёт гораздо больше сил, чем споры и упрямство.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'Свою еду вам не отдаст 🍳', 'Не даёт вам еду из своей тарелки, но настойчиво просит попробовать из вашей? Дети безоговорочно доверяют выбору родителей. Не сопротивляйтесь: с любовью поделитесь кусочком и просто улыбнитесь этому забавному эгоизму.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'Я хочу летать! 🕊️', 'Прыгает с дивана, машет руками и сердится на вас за то, что не может взлететь? Объяснять законы физики пока рано. Скажите: «Ты пока не летаешь, потому что твои крылья ещё растут», — и предложите прыгнуть на что-нибудь мягкое.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'Похититель телефона 📱', 'Налили себе чай и обнаружили, что телефон исчез, а малыш прячется за диваном и, подражая вам, говорит: «Алло»? Он копирует ваши цифровые привычки. Забирая устройство, с улыбкой скажите: «Кажется, мой телефон тоже хочет с тобой поговорить».'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'Тишина вдвоём 🥂', 'Малыш уснул, дома всё убрано. Сядьте рядом с партнёром на диван и даже не включайте телевизор. Просто обменяйтесь взглядами, говорящими: «Мы и с этим справились. Мы выжили». Поверьте, это и есть самый настоящий момент единения уставших родителей.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'Запишите свои чувства 📝', 'Вас никто не понимает? Не замечает вашей усталости? Дневник настроения — лучший собеседник, которому можно доверить самое сокровенное. Запишите в него всё, что вас тревожит: стресс, боль и одиночество — и вы увидите, как быстро вам станет легче.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('1af46170-3a5b-41ea-bb18-ce899698f996'::uuid, 'İlk gününüz kutlu olsun! 🥳', 'Bebeğinizin uyku ve beslenme düzenini takip etmek için Anacan uygulamasındaki zamanlayıcıyı kullanmaya başlayın.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'Bebeğiniz uyurken siz de dinlenin! 😴', 'Bugün nasıl hissettiğinizi Duygu Günlüğü''ne yazmayı unutmayın.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'Ağız sütü ilk aşıdır! 🤱', 'Beslenme düzeninizi uygulamadaki Beslenme Takibi aracıyla kolayca kaydedin.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'Sütünüzün az olduğunu düşünüp üzülmeyin! 🥛', 'Bebeğinizin midesi henüz kiraz büyüklüğündedir. Günlük beslenme istatistiklerinizi uygulamadan takip edebilirsiniz.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'Kendinize zaman ayırın. 💆‍♀', '️ Rahim kaslarınız iyileşiyor. Bugünkü duygularınızı Duygu Günlüğü''ne kaydederek rahatlayın.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'Bebeğinizin cildindeki beyaz tabaka onu korur. 👶 Endişelenmeyin.', 'Bezini değiştirirken Anacan''a kaydetmeyi ve normal değerleri kontrol etmeyi unutmayın!'),
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c', 'Bebeğinizin emme refleksi çok güçlü! 🍼', 'Her beslenme anını zamanlayıcıyla takip ederek yeterince doyduğundan emin olun.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'Nedensiz yere duygusallaşıyor musunuz? 😢', 'Bu tamamen doğaldır! Duygularınızı Anacan AI veya Topluluğumuzda paylaşabilir ve destek alabilirsiniz.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'Bebeğinizi uyuturken zorlanıyor musunuz? 🎶', 'Uygulamamızdaki Beyaz Gürültü aracını açın; bebeğiniz anne karnındaymış gibi derin bir uykuya dalsın.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'Göbek bağı kuru ve temiz kalmalıdır. ⏱️', 'Göbek bağı ıslanırsa mutlaka kurulanmalı ve doktor tarafından önerilen antiseptik solüsyon her gün kullanılmalıdır.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'Annelerin vitamin açısından zengin beslenmesi çok önemlidir! 🥗', 'Sağlıklı tarifler bölümüne göz atın ve gücünüzü yeniden kazanın.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'Bebeğiniz sizi kokunuzdan ve sesinizden tanır! 👃', 'Bu nedenle odadan ayrıldığınızda bebeğiniz huzursuz olabilir ve kendini güvende hissetmeyebilir.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', '“Kucağa alışır” efsanesine inanmayın! 🤗', 'Bebeğinize bol bol sarılın. Bu, hem aranızdaki bağı güçlendirecek hem de sütünüzü artıracaktır.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'Gece ve gündüz kavramınız mı değişti? 🛌', 'Uyku düzenini ve günlük normal değerleri uygulamadan takip edin; bebeğiniz uyurken siz de gözlerinizi kapatın.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'Rutin kontroller başlıyor. 💉', 'Bebeğinizin boy ve kilo gelişimini Gelişim Takibi''ne girerek kişisel gelişim grafiğini oluşturun!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'Aralıkları unutmamanız için zamanlayıcı burada. 🍼', 'Bez değiştirme ve beslenme saatlerini Anacan ile kolayca düzenleyin.'),
  ('7797557a-9277-450c-98b3-b0fa58923513', 'Akşam banyosundan sonra uyku vakti! 🛁', 'Bebeğinizin rahatça uykuya dalması için gece uykusundan önce banyo yaptırmak çok faydalıdır.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'Günlük bez sayısını takip ediyor musunuz? 🧷', 'Bebeğinizin doyduğunun en iyi göstergesi bezleridir. Her bez değişiminde Anacan''a kaydetmeyi unutmayın!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'Uyku düzenini analiz edelim. ⏱️', 'Bebeğiniz uyurken uyku zamanlayıcısını başlatın, günlük uyku ihtiyacını ne ölçüde karşıladığını grafikten görün.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'Anneler için lezzetli ve faydalı bir seçenek! 🍲', 'Enerjinizi artıracak Sağlıklı Tarifler bölümümüze göz atın, kendinize iyi bakın.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'Bebeğiniz hızla büyüyor! ⚖', '️ Haftalık kilosunu Gelişim Takibi''ne girin ve sağlıklı gelişim eğrisini uygulamadan takip edin.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'Herhangi bir sorunuz mu var? 🤖', 'Geceleri bile Anacan AI yanınızda! Aklınıza takılan soruları sorun, hemen destek alın.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'Birlikte ilk yürüyüşler! 🌳', 'Hava güzelse dışarı çıkın. Bebeğinizin her gün temiz hava alması çok önemli ve faydalıdır.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'Anı ölümsüzleştirin! 📸', 'Bugünün tatlı anlarını Bebek Albümü''ne yükleyin, gelecekte bakıp gülümseyeceğiniz anılar biriktirin.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'Uyku ve beslenme arasındaki denge. 📚', 'Bloglar bölümündeki yenidoğan gelişimiyle ilgili en son makalemizi okudunuz mu?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'Tebrikler, artık 2 haftalıksınız! 🎈', 'Bu küçük dönüm noktasını kutlamak için Bebek Fotoğraf Çekimi bölümündeki eğlenceli temalardan yararlanın.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'Bazen beslenme süresi uzayabilir. 🍼', 'Zamanlayıcıyı kullanarak süreci analiz edin. Önemli olan hem sizin hem de bebeğinizin rahat olmasıdır.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'Kendinizi nasıl hissediyorsunuz? 🧘‍♀', '️ Annelik hem güzel hem de yorucudur. Duygu Günlüğü''ne girin ve bugünü değerlendirin.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'Bebek bakımı için ne eksik? 🧴', 'Diğer annelerin deneyip beğendiği ürünleri Önerilen Ürünler bölümünde bulabilirsiniz.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'Bez değiştirmek artık bir rutin! 👶', 'Günlük idrar ve dışkı takibini Bez Takibi''ne kaydederek bebeğinizin sağlığını takip edin.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'Anne de dinlenmeli! 🛋', '️ Bebeğinizin uyku düzenini zamanlayıcıyla kaydettiyseniz şimdi sıra sizde. Kendinize bir çay koyun ve rahatlayın.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'Gaz sancıları mı başladı? 🌪️', 'Panik yapmayın. Karnına nazikçe masaj yapın ve dikkatini dağıtmak için arka planda Beyaz Gürültüleri açın.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'Yüzüstü zamanı! 🐢', 'Günde birkaç dakika yüzüstü kalması, bebeğinizin boyun kaslarını güçlendirir.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'Gece uykusuna hazırlık. 🌙', 'Yatmadan önce odanın sıcaklığını ayarlayın ve Anacan''ın uyku zamanlayıcısını başlatın.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'Sütünüzü artıracak sırlar! 🥛', 'Sağlıklı tarifler bölümünde süt artırmaya yardımcı doğal besinler ve smoothie tarifleri sizi bekliyor.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'Gelişim sıçraması olabilir. 📈', 'Hiçbir neden yokken çığlık atarak ağlıyor mu? 3. hafta atağı, gaz sancılarının da zirve yaptığı dönemdir. Panik yapmayın.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'Kucağa mahkûm 🛋️', 'Bebeğinizi yatağına koyar koymaz uyanıp ağlıyor mu? Bugün dört duvar arasında, bebeğiniz sürekli kucağınızdaymış gibi hissedebilirsiniz. Ancak bebeğiniz için en güvenli yerin sizin kucağınız olduğunu unutmayın. Sabırlı olun.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'Eşinizi de sürece dahil edin. 👨‍👩‍👦', 'Bez değiştirme veya Beyaz Seslerle uyutma sırasını bu akşam ona verin, siz de dinlenin.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'Cilt bakımı zamanı. 🛁', 'Bebeğinizin hassas cildine uygun kremler mi arıyorsunuz? Önerilen Ürünler listesi yardımınıza koşacak.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'Refleksleri gelişiyor! 🖐️', 'Bebeğiniz parmağınızı ne kadar sıkı tutuyor? Bu konuda daha fazla bilgi edinmek için Bloglardaki yazılarımızı keşfedin.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'Günlük raporunuz hazır! 📊', 'Anacan uygulamasına girerek bugünkü uyku, beslenme ve bez değişimi grafiklerinizin analizine göz atın.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'Büyüme sürecini takip ediyoruz! 📏', 'Yeni ayı yaklaşıyor. Uygulamadaki Gelişim Takibi bölümüne girip bilgileri güncellediğinizden emin olun.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'Tam 20 gündür birliktesiniz! 🥰', 'Siz harika bir annesiniz! Bebek fotoğraf çekimi aracıyla bugünü güzel bir anıya dönüştürün.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'Bugün yalnızca olumlu duygular! ✨', 'Ruh Hali Günlüğünüzü açın ve bebeğinizin sizi en çok güldürdüğü anı kaydedin. Anacan AI sizi dinliyor!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'Gelişim sıçraması dönemi! 📈', 'Bebeğiniz daha sık acıkabilir. Zamanlayıcıyla Beslenmeyi takip ederek süreci izleyin.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'Akşam huzursuzluğu artıyor mu? 🎶', 'Nedeni gaz sancısı veya yorgunluk olabilir. Bebeğinizi Beyaz Sesler bölümündeki doğa sesleriyle sakinleştirin.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'Tam 3 haftalık! 🎉', 'Bebeğinizin bu küçük dönüm noktasını kutlamak için Bebek fotoğraf çekimi bölümünü kullanarak tatlı bir anı ölümsüzleştirin.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'Kendinizi unutmayın! 🥗', 'Sizin sağlığınız, onun da sağlığıdır. Kadınlara özel sağlıklı tarifler arasından enerjinizi yenileyecek bir atıştırmalık seçin.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'Günlük uyku süresi önemlidir. 😴', 'Bebeğiniz uyurken uyku zamanlayıcısını başlatın ve günlük uyku ihtiyacına ne kadar uyduğunu kontrol edin.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'Başını kaldırmaya çalışıyor! 🐢', 'Karnının üzerinde (tummy time) yatarken yaptığı hareketleri Bebek Albümüne video olarak ekleyin.'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'Sorunuz mu var? 🤖', '“Geceleri neden sık sık uyanıyor?” gibi aklınıza takılan sorular için Anacan AI her zaman desteğe hazırdır.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'Günlük bez durumu nasıl? 🧷', 'Bebeğinizin yeterince beslendiğini anlamanın en kolay yolu, bez değişimlerini kaydetmektir. Şimdi uygulamaya ekleyin!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'İlk gülümsemesi yaklaşıyor! 😊', 'Yüzünüze dikkatle baktığı anları kaçırmayın. Bu anların size hissettirdiklerini Duygu Günlüğüne yazın.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'Rutin oluşturmaya başlıyoruz! 🌙', 'Her gün aynı saatte banyo yaptırın, emzirin, Beyaz Gürültüyü açın ve uyku zamanlayıcısını başlatın.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'Annelik ihtiyaçlarınızı unutmayın. 🛍', '️Göğüs ucu kremi ve göğüs pedi kullanmak, kendinizi daha rahat hissetmenizi sağlar ve koruma sunar.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'Açık havada yürüyüş zamanı! ☀️', 'Rahatça dinlenebileceğiniz ve bebeğinizle gidebileceğiniz bir yer mi arıyorsunuz? Anne Dostu Mekanlar blogumuza mutlaka göz atın.'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'Fırsat buldukça okuyun ve öğrenin. 📚', 'Yenidoğan gelişimi ve bakımıyla ilgili en faydalı yazılar Bloglar bölümünde sizi bekliyor.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'İlk ay kontrolü yaklaşıyor. ⚖️', 'Bebeğinizin bugüne kadarki kilo ve boy artışını Gelişim Takibi bölümüne kaydettiğinizden emin olun.'),
