  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'Sosyal gülümsemeler! 😊', 'Onun tatlı gülümsemesi tüm yorgunluğunuzu alıp götürüyor.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'Haftalık istatistikleriniz hazır! 📊', 'Son günlerde uyku ve beslenme düzenine ne ölçüde uyduğunuzu analiz etmek için uygulamaya girin.'),
