  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'TAM 5 AY! 🎉', 'İnanılmaz! Tam 150 gündür, tam 5 aydır ekip olarak bu mucizeyi büyütüyorsunuz. Bu özel günü hemen Bebek Fotoğraf Çekimi ile ölümsüzleştirin!'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'Günlük koşuşturma içinde öğle yemeğini ayaküstü yemeyin. 🥑', 'Sağlıklı tariflerden kolay bir salata hazırlayın, oturup keyifle yiyin.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'Kahkaha karesi 📸', 'Her geçen gün daha çok gülüyor! Bebek fotoğraf çekimini açın ve bugünün olumsuzluğunu uzaklaştıracak neşeli bir kahkaha karesi çekin.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'Rahatlatıcı masal 🪄', 'Akıllı Masallar''da 5. ayına hazırlanan küçük kahramanın hikâyesini oluşturun ve odaya tatlı bir hava katın.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', '5. AYA DOĞRU! 🎂', 'Dikkat! Büyük güne, yani 5. ayın tamamlanmasına yalnızca 10 gün kaldı! Özel bir pasta sipariş etmeyi veya konsept planlamayı unutmadınız, değil mi? Hazırlıklara şimdiden başlayın!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'Bebek sakinleşmiyor ve siz çok mu yoruldunuz?  🛑', 'Bebeği güvenli bir şekilde beşiğine bırakıp 5 dakikalığına başka bir odaya geçin. Sizin de nefes almaya hakkınız var.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'Ses analizörü 😭', 'Odaya döndünüz ve hâlâ ağlıyor. Yıpranmayın! Sesini hemen Ağlama Analizi''ne dinletin, ihtiyacını doğru şekilde karşılayarak onu sakinleştirin.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'Elleri sürekli ağzında 🦷', 'Her şeyi kuvvetlice çiğniyor mu? Ilık ve temiz bezler diş etlerini rahatlatacaktır.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'Gece kahramanları 🦸‍♀️', 'Gece uyanmalarının sizi tükettiğini biliyoruz. Duygu günlüğüne yorgunluğunuzu yazın ve eşinizden size destek olmasını isteyin.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'Beni görebiliyor musun? 🧸', 'Oyuncağın yarısını battaniyenin altına gizleyin. Onu arayıp buluyor mu? Nesne sürekliliğini anlaması için harika bir gelişim adımıdır!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'Yürüyüş şart ⛅', 'Hava ve kıyafet aracını kontrol edin, bebeği giydirin ve parkta en az 20 dakika yürüyün. Buna hem sizin hem de onun kesinlikle ihtiyacı var.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'Bir doktor kadar akıllı 🤖', 'Bebeğinizin hareketlerinde size tuhaf gelen bir şey mi var? İnternette korkutucu haberler okumak yerine Anacan AI''dan net bir yanıt alın.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'Babadan ninni 👨‍🍼', 'Partner modunda bildirimler eşinize gitsin. Bu gece uykuya geçiş masalını ve ninniyi o okusun. Siz ise dinleyici olun.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'Sabah konseri 🎶', 'Size bakıp kocaman gülümseyerek farklı heceler çıkarıyor. Şu anda odadaki en güzel sabah konserini veriyor, dikkatle dinleyin!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'Uyku düzeni konusunda tereddütleriniz mi var? 🤖', '5. aya doğru yaşanan uyku değişiklikleriyle ilgili sorularınızı Anacan Topluluğu''nda paylaşın, diğer annelerden destek alın.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'Ses kontrolü 🤫', 'Dördüncü ayın sonunda uykuya dalmak bazen zorlaşabilir. Ses ölçeri açın, ses sınırını kontrol edin ve odanın mutlaka karanlık olmasını sağlayın.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'Siz en iyisisiniz! 💖', 'Mükemmel insan yoktur ama bebeğiniz için en iyi anne sizsiniz.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'Diğer anneler ne yapıyor? 💬', 'Endişeli misiniz? Anacan Topluluğuna katılın. Oradaki annelerin de aynı uykusuzluğu ve sorunları yaşadığını görmek size iyi gelecektir.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'Stoklar tükeniyor 🛒', 'Bebek bezi ya da bebek yağı mı bitti? Zihninizi küçük şeylerle yormayın; Alışveriş listesine ekleyin, eşiniz gelirken alsın.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'Sorunuz mu var? 🤖', 'Bebeğinizin gelişimiyle ilgili aklınızda binlerce soru mu var? Saatlerce forum okumak yerine Anacan AI''a yazın ve kısa, bilimsel bir yanıt alın.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'Günlük bez takibini yapıyoruz. 🧷', 'Bebeğin yeterince beslendiğinden emin olmak ve sindirim sistemini takip etmek için Anacan''da her bez değişimini kaydedin.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'Dayanışmanın gücü 🛋️', 'Zor bir günün ardından eşinizle karşılıklı oturup dertleşin. Birbirinize destek olmak ve takım ruhunu hissetmek yükünüzü yarıya indirir.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'Kendinizle gurur duyun 👏', 'Geriye dönüp baktığınızda ilk haftalarda ne kadar korktuğunuzu hatırlayın. Şimdi ise her şeyi ne kadar ustalıkla yönetiyorsunuz! Siz harikasınız!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'Lezzetli keşiflere çok az kaldı! 🥦', 'Ek gıdaya başlayacak bebekler için Tarifler bölümündeki ilk püre fikirlerini okuyarak gelecek aya hazırlanın.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'Cebinizdeki çocuk doktoru 🤖', 'Uyku düzeni aniden mi değişti? Endişeye kapılmadan önce Anacan AI''dan 5 aylık uyku gerilemesi hakkında bilgi ve öneri alın.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'Kendi kendine dönme 🤸‍♂️', 'Artık sırtından karnına rahatça dönebiliyor mu? Kaslarını özgürce hareket ettirebilmesi için onu geniş bir halının üzerine yatırın.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'Zamanı dondurmak 📸', 'O kadar hızlı büyüyor ki... Uykudayken o tatlı, huzurlu yüz hatlarını Bebek fotoğraf çekimiyle ölümsüzleştirip anı olarak saklayın.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'Gece uyanmalarını rutine dönüştürüyoruz. 😴', 'Her uyandığında ışıkları açmayın. Anacan zamanlayıcısıyla besleyin, Beyaz Seslerle yeniden uyutun.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'Bugün temizlik yok 🛑', 'Yoruldunuz mu? Eşinize söyleyin. Bugün ev yemeği yok, temizlik yok. Bugün annenin dinlenme ve kahve günü!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'Benimle konuş! 🗣️', 'Sizi dikkatle dinleyip farklı sesler mi çıkarıyor? Sizinle gerçek bir diyalog kuruyor. Sesine karşılık verin ve bu iletişimi destekleyin.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'İlk oturma denemeleri 🪑', 'Onu destekleyerek oturttuğunuzda başını ve sırtını daha dik mi tutuyor? Bu, kaslarının güçlendiğini gösterir. Kısa süreli destekli oturma egzersizlerine başlayın.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'Dört duvardan kaçış ☕', 'Evde bunaldınız mı? Bebek arabasıyla rahatça girilebilen en yakın kafeyi bulun ve farklı bir ortamda kahvenizi için.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'Uyku sinyalleri 🥱', 'Gözlerini ovuşturup boşluğa bakıyorsa huysuzlanmasını beklemeyin. Hemen odayı karartıp uyku rutinine başlayın.'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'Kendinizi alkışlayın 👏', 'Tüm notlarınıza ve gelişim grafiklerinize dönüp bakın. Onun ne kadar büyüdüğünü, sizin ise nasıl ustalaştığınızı görün!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'Zafer akşamı 🪄', 'Bu akşam Akıllı masallarda sevgi dolu bir hikâye seslendirin ve eşinizle birlikte bir ekip olarak zaferinizi kutlayın!'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', 'Anne için 10 dakika ☕', 'Evin dağınıklığı hiçbir yere kaçmıyor. O uyurken hemen işe koyulmayın. Kendinize sıcak bir kahve hazırlayıp 10 dakika boyunca sadece duvara bakın.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'Elden ele keşif 🧸', 'Oyuncağı bir elinden diğerine geçirebiliyor mu? Bu, beyninin iki yarım küresinin harika çalıştığının kanıtıdır! Gelişim takipçisinde bu önemli beceriyi kaydedin.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'Ruh hâlinizi paylaşın 📝', 'Bugün çok yorgun musunuz, yoksa enerjik misiniz? Duygularınızı ruh hâli günlüğüne içtenlikle yazın. İçinizi dökmek size iyi gelecektir.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'Sesli hikâyeler 🪄', 'Bu akşam odaya farklı bir sihir katalım. Akıllı masallarda Ay''a uçan cesur kedinin hikâyesini oluşturarak uyku rutinini eğlenceli hâle getirin.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'Doğal sakinleştirici ⛅', 'Çok huzursuz ve evde durmak istemiyor mu? Hava durumunu ve kıyafetlerini kontrol edip hemen parka çıkın. Temiz hava ikiniz için de en iyi ilaçtır.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'Eline geçen her şeyi mutlaka ağzına mı götürüyor? 🤤', 'Bu, onun dünyayı tanıma yöntemidir. Yalnızca çevresindeki eşyaların temiz ve güvenli olmasına dikkat edin.'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'Ağlama kodu 😭', 'Sabahki mızmızlanmaları açlıktan mı, yoksa diş çıkarmaktan mı kaynaklanıyor? Tahmin etmeyin; sesini Ağlama analizine dinleterek neye ihtiyacı olduğunu hemen öğrenin.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'Sabrınız mı tükeniyor?  👨‍👧', 'Bu akşam bırakın çocukla tamamen babası ilgilensin, siz de kulaklıklarınızı takıp dinlenin.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'Biz bir ekibiz! 🌟', 'Kendinizi yalnız ve anlaşılmamış mı hissediyorsunuz? Derin bir nefes alın. Siz bu fırtınalı günlerin en güçlü kahramanısınız ve harika bir iş çıkarıyorsunuz.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'Mutlak sessizlik 🤫', 'Uykuya dalması zorlaştı mı? Ses ölçer ile odadaki desibel düzeyini kontrol edin. Televizyonun sesini kapatın ve odayı tamamen karartın.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'Damakları mı kaşınıyor? 🦷', 'Parmakları sürekli ağzında ve çok fazla salya mı akıtıyor? Soğutulmuş diş kaşıyıcılarını kullanmanın zamanı geldi.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'Kendinizi unutmayın 🥑', 'Bebeği doyururken kendinizi aç mı bıraktınız? Sağlıklı tarifler arasından 10 dakikada hazırlanabilen, enerji verici bir yemek seçin.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'Gece ninnisi 🎶', 'Hiçbir ses anne sesi kadar sakinleştirici değildir. Bu akşam onu yalnızca göğsünüze yaslayın ve en sevdiği ninniyi usulca söyleyin.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'Odanın her yeri oyuncak mı? 🌪️', 'Odanın her yeri oyuncak mı? Eviniz dağınık diye strese girmeyin. Siz harika bir annesiniz; önceliğiniz temizlik değil, bebeğinizdir.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'Aç mı, yoksa yorgun mu? 🧩', 'Ne yaparsanız yapın susmuyor mu? Belki de sadece çok yorulmuştur. Emin olmak için Ağlama analizini kullanarak bu sesin ardındaki nedeni keşfedin.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'Ses kontrolü 🤫', 'Uykuya daldığında ani sesler onu uyandırıyor mu? Ses ölçer ile odadaki gürültü seviyesini kontrol altında tutun.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'Anne enerjisi 🔋', 'Günün ortasında enerjiniz mi tükeniyor? Sağlıklı tarifler arasından hem sütünüzü destekleyecek hem de size enerji verecek bir smoothie tarifine göz atın.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'Müziğin gücü 🎶', 'Akşamüstü başlayan sebepsiz ağlamaları yavaş tempolu klasik müzik veya beyaz gürültüyle durdurmayı deneyin.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'Hava sürprizi ⛅', 'Gezintiye çıktığınızda havaya aldanıp bebeğinizin üşütmesine neden olmayın. Hava ve kıyafet yardımcısıyla dışarıdaki koşullara uygun karar verin.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'Tatlara ilgi mi? 🍽️', 'Siz yemek yerken gözlerini tabağınızdan ayırmıyor mu? Ek gıdaya hazır olma belirtileri başlıyor. Ama henüz acele etmeyin, 6. ayı bekleyin.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'Deneyim paylaşımı 💬', 'Bebeğinizin yeni bir hareketi sizi şaşırttı mı? Anacan Topluluğuna katılın ve bu keşfi diğer annelerle konuşun.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'Masalın sonu yok 📖', 'Bu akşam Akıllı masallara güzel bir görev verin: Gökkuşağının üzerinde uyuyan perinin hikâyesi.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'Siz yeterlisiniz! 💖', 'Bugün her şey ters mi gitti? Kendinizi suçlamayın. Siz robot musunuz? Hayır. Duygularınızı kabul edin, kendinizi affedin ve gülümseyin.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'Yarım yaşa doğru 📈', 'İnanabiliyor musunuz? 6. ayın tamamlanmasına çok az kaldı! Gelişim takipçisini açın ve bu aya kadar katettiğiniz inanılmaz yolu gururla inceleyin.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'Nöbeti devredin 🛋️', 'Bebeğiniz uyuduğunda siz de hemen uyumak istiyorsanız, evdeki diğer işleri partnerinize devredin.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'Hafıza sisi 📝', 'Unutkanlık doğum sonrası dönemin bir parçasıdır. Hiçbir şeyi unutmamak için alışveriş listesini aktif olarak kullanın.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'Aynadaki arkadaş 👀', 'Onu aynanın karşısına götürün. Kendi yansımasına bakıp kıkırdaması, zihinsel gelişimi için harika ve eğlenceli bir etkinliktir.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'Takım sohbeti 🥂', 'Duygu günlüğünü açın, bugünün olumsuzluklarını geride bırakın ve partnerinizle birlikte bir takım olmanın tadını çıkarın.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'Diş kaşıyıcı arayışı 🦷', 'Salya ve diş eti kaşıntısı artıyor. Temiz diş kaşıma halkaları en yakın dostunuzdur.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'Beni görüyor musun? 🧸', 'Oyuncağı battaniyenin altına saklayın. Onu arayıp buluyor mu? Nesne sürekliliğini anlaması için harika bir gelişim anıdır!'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'Gecenin kahramanı baba 🦸‍♂️', 'İlk ayların en güzel kuralı: Ninni söyleme işi dönüşümlü olmalı! Bu akşam bebek babasının kucağında, siz dinleniyorsunuz.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'Dışarı çıkma zamanı 🌳', 'Onu bebek arabasına koyun ve 15 dakikalığına da olsa temiz havaya çıkın. İkinizin de buna ihtiyacı var.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'Sabah konseri 🎶', 'Size bakıp kocaman gülümseyerek yeni sesler çıkarıyor. Şu anda odadaki en güzel konseri o veriyor, dikkatle dinleyin!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'Uykunun temeli ⏱️', 'Ilık bir banyo, masaj ve odanın karartılması... Gecelerinizin rahat geçmesi için uyku rutinini asla bozmayın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid, 'Doktor kadar akıllı 🤖', 'İnternette korkutucu haberler okumak yerine ek gıdaya geçişle ilgili sorularınızı Anacan AI''a sorun ve rahatlayın.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'Akıllı sessizlik 🤫', 'Uykuya dalarken ani sesler onu uyandırıyor mu? Ses ölçerle odadaki desibel seviyesini kontrol edin.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'Kafa karıştıran kıyafetler 👗', 'Bazen çok ince, bazen de çok kalın mı giydiriyorsunuz? Tereddüt etmeyin. Hava durumunu ve kıyafetleri kontrol ederek onu güvenle giydirin.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'Anneye ziyafet 🥑', 'Günlük koşuşturma içinde öğle yemeğini ayaküstü yemeyin. Sağlıklı tariflerden kolay bir salata hazırlayın, oturup keyifle yiyin.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'Kendinizi koruyun 🛋️', 'Bebek uyuduğunda ev işlerine değil, kendinize zaman ayırın. Oda dağınık kalabilir ama sizin enerjinizi yeniden toplamanız gerekir.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'Oyuncaklarını yere atıp izliyor mu? 🎯', 'Bunu yer çekimini ve neden-sonuç ilişkisini öğrenmek için yapıyor! Sabırla oyuncağı ona geri verin.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'Yalnız değilsiniz 💬', 'Endişeli misiniz? Anacan Topluluğuna katılıp sorunuzu sorun. İnanın, tüm anneler benzer süreçlerden geçiyor.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'Ek gıdaya hazırlık 🥣', '6. aya çok az kaldı. İlk püreleri merak ediyor musunuz? Anacan AI''dan ek gıdaya geçişle ilgili temel bilgileri öğrenin.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'Dayanışmanın gücü 🥂', 'Bu akşam eşinizle bu önemli aşamaya nasıl ulaştığınızı konuşun. Bir ekip olarak harika bir iş başardınız.'),
